// Nuvemath — 7-sinf, Algebra (II qism) nazariyasi. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-2';

  // ---------- t1. Sonli va algebraik ifodalar. Formulalar ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Harflar sonlar o‘rnida', 'Буквы вместо чисел', 'Letters in place of numbers'), p: [
      L('Tasavvur qiling: siz do‘konda bir xil daftarlardan bir nechtasini olmoqchisiz. Bitta daftar 3 000 so‘m. Ikkita — 6 000, uchta — 9 000. Har safar yangidan hisoblash o‘rniga qisqa qoida yozamiz: narx = 3 000 · n, bu yerda n — daftarlar soni. Mana shu <b>n</b> harfi — algebraning asosiy g‘oyasi. Harf istalgan sonning o‘rnini bosadi, qoida esa hamma hollar uchun bir xil qoladi.', 'Представьте: вы хотите купить в магазине несколько одинаковых тетрадей. Одна тетрадь стоит 3 000 сум. Две — 6 000, три — 9 000. Вместо того чтобы каждый раз считать заново, запишем короткое правило: цена = 3 000 · n, где n — число тетрадей. Эта буква <b>n</b> — главная идея алгебры. Буква заменяет любое число, а правило остаётся одним и тем же для всех случаев.', 'Imagine you want to buy several identical notebooks. One notebook costs 3 000 sum. Two cost 6 000, three cost 9 000. Instead of calculating from scratch each time, we write one short rule: price = 3 000 · n, where n is the number of notebooks. That letter <b>n</b> is the main idea of algebra. A letter stands for any number, and the rule stays the same for every case.'),
      L('Bu mavzuda biz sonli ifoda va algebraik ifoda nima ekanini, ifodaning qiymati qanday topilishini va formula degan so‘z nimani anglatishini o‘rganamiz. Bular butun algebra kursining poydevori: keyinroq darajalar, ko‘phadlar, tenglamalar va funksiyalar aynan shu tushunchalar ustiga quriladi.', 'В этой теме мы узнаем, что такое числовое и алгебраическое выражение, как находить значение выражения и что означает слово «формула». Это фундамент всего курса алгебры: степени, многочлены, уравнения и функции строятся именно на этих понятиях.', 'In this topic we learn what numerical and algebraic expressions are, how to find the value of an expression, and what the word “formula” means. This is the foundation of the whole algebra course: powers, polynomials, equations and functions are all built on these ideas.'),
      L('Nega «algebra» deyiladi? Bu so‘z vatandoshimiz Muhammad al-Xorazmiyning kitobidan kelib chiqqan — bu haqda tarix sahifasida gaplashamiz.', 'Почему это называется «алгебра»? Слово пришло из книги нашего соотечественника Мухаммада аль-Хорезми — об этом поговорим на странице истории.', 'Why is it called “algebra”? The word comes from a book by Muhammad al-Khwarizmi, a scholar from Khorezm — we will talk about him on the history page.')
    ] },
    { kind: 'def', h: L('Sonli va algebraik ifoda', 'Числовое и алгебраическое выражение', 'Numerical and algebraic expressions'), p: [
      L('<b>Sonli ifoda</b> — sonlar, amal belgilari va qavslardan tuzilgan yozuv: 2 · (7 + 3) − 5. Uni hisoblab, bitta son — <b>ifodaning qiymatini</b> olamiz: 2 · 10 − 5 = 15.', '<b>Числовое выражение</b> — запись из чисел, знаков действий и скобок: 2 · (7 + 3) − 5. Вычислив его, получаем одно число — <b>значение выражения</b>: 2 · 10 − 5 = 15.', 'A <b>numerical expression</b> is made of numbers, operation signs and brackets: 2 · (7 + 3) − 5. Working it out gives one number, the <b>value of the expression</b>: 2 · 10 − 5 = 15.'),
      L('<b>Algebraik ifoda</b> — sonlar bilan birga harflar ham qatnashgan ifoda: 3n, a<sup>2</sup> − 2ab, (x + y) : 2. Harflar <b>o‘zgaruvchilar</b> deyiladi, chunki ularning o‘rniga turli sonlar qo‘yish mumkin. Harflar o‘rniga aniq sonlar qo‘yilsa, algebraik ifoda sonli ifodaga aylanadi va uning qiymatini hisoblash mumkin.', '<b>Алгебраическое выражение</b> — выражение, в котором вместе с числами есть буквы: 3n, a<sup>2</sup> − 2ab, (x + y) : 2. Буквы называют <b>переменными</b>, потому что вместо них можно подставлять разные числа. Если подставить конкретные числа, алгебраическое выражение превращается в числовое, и его значение можно вычислить.', 'An <b>algebraic expression</b> contains letters as well as numbers: 3n, a<sup>2</sup> − 2ab, (x + y) : 2. The letters are called <b>variables</b>, because different numbers can be put in their place. When specific numbers are substituted, the algebraic expression becomes a numerical one and its value can be calculated.')
    ], list: [
      L('<b>Ifodaning qiymati</b> — harflar o‘rniga sonlar qo‘yilgandan keyin chiqqan natija.', '<b>Значение выражения</b> — результат, полученный после подстановки чисел вместо букв.', '<b>Value of an expression</b> — the result after substituting numbers for the letters.'),
      L('<b>Ruxsat etilgan qiymatlar</b> — ifoda ma’noga ega bo‘ladigan harf qiymatlari. Masalan, 10 : (x − 2) ifodasida x = 2 bo‘lishi mumkin emas, chunki nolga bo‘lib bo‘lmaydi.', '<b>Допустимые значения</b> — значения букв, при которых выражение имеет смысл. Например, в 10 : (x − 2) нельзя брать x = 2, так как делить на ноль нельзя.', '<b>Permitted values</b> — the values of the letters for which the expression makes sense. In 10 : (x − 2), x cannot be 2, because division by zero is impossible.'),
      L('<b>Formula</b> — ikki yoki undan ko‘p miqdor orasidagi bog‘lanishni harflar bilan yozgan tenglik: S = v · t, P = 2(a + b).', '<b>Формула</b> — равенство, записывающее буквами связь между двумя или несколькими величинами: S = v · t, P = 2(a + b).', 'A <b>formula</b> is an equality that uses letters to record a link between two or more quantities: S = v · t, P = 2(a + b).')
    ] },
    { kind: 'history', h: L('Al-Xorazmiy va «al-jabr»', 'Аль-Хорезми и «аль-джабр»', 'Al-Khwarizmi and “al-jabr”'), p: [
      L('IX asrda Bag‘doddagi «Bayt ul-hikma» («Donishmandlik uyi»)da xorazmlik olim <b>Muhammad ibn Muso al-Xorazmiy</b> (taxminan 783–850) ishlagan. Taxminan 820-yilda u «Al-kitob al-muxtasar fi hisob al-jabr va-l-muqobala» nomli kitob yozdi. «Al-jabr» so‘zi «to‘ldirish, tiklash» degan ma’noni bildiradi. Yevropaliklar shu so‘zni «algebra» deb o‘qishgan — fanning nomi shunday paydo bo‘lgan.', 'В IX веке в багдадском «Доме мудрости» работал учёный из Хорезма <b>Мухаммад ибн Муса аль-Хорезми</b> (около 783–850). Примерно в 820 году он написал книгу «Аль-китаб аль-мухтасар фи хисаб аль-джабр ва-ль-мукабала». Слово «аль-джабр» означает «восполнение, восстановление». Европейцы прочитали его как «алгебра» — так появилось название науки.', 'In the 9th century, a scholar from Khorezm, <b>Muhammad ibn Musa al-Khwarizmi</b> (about 783–850), worked at the House of Wisdom in Baghdad. Around the year 820 he wrote a book called “Al-kitab al-mukhtasar fi hisab al-jabr wa-l-muqabala”. The word “al-jabr” means “restoring, completing”. Europeans read it as “algebra”, and that is how the science got its name.'),
      L('Qizig‘i shundaki, al-Xorazmiy kitobida hech qanday harf yo‘q edi! U hamma masalani so‘zlar bilan yozgan: noma’lum sonni «shay» (narsa), uning kvadratini «mol» deb atagan. Harflar bilan yozish odati faqat XVI–XVII asrlarda fransuz matematiklari Fransua Viyet va Rene Dekart tufayli paydo bo‘ldi. Dekart noma’lumlarni x, y, z bilan, ma’lum sonlarni a, b, c bilan belgilashni taklif qildi — biz hozir ham shunday yozamiz.', 'Интересно, что в книге аль-Хорезми не было ни одной буквы! Все задачи он записывал словами: неизвестное называл «шай» (вещь), его квадрат — «маль». Привычка писать буквами появилась лишь в XVI–XVII веках благодаря французским математикам Франсуа Виету и Рене Декарту. Декарт предложил обозначать неизвестные буквами x, y, z, а известные числа — a, b, c. Так мы пишем до сих пор.', 'Curiously, there were no letters at all in al-Khwarizmi’s book! He wrote every problem in words: the unknown was “shay” (a thing) and its square was “mal”. The habit of writing with letters appeared only in the 16th–17th centuries thanks to the French mathematicians François Viète and René Descartes. Descartes suggested using x, y, z for unknowns and a, b, c for known numbers — and that is still how we write today.'),
      L('«Algoritm» so‘zi ham al-Xorazmiy nomidan kelib chiqqan: lotinchada uning ismi «Algoritmi» deb yozilgan. Demak, har safar «algebra» yoki «algoritm» deganimizda biz Xorazm olimini eslaymiz.', 'Слово «алгоритм» тоже произошло от имени аль-Хорезми: на латыни его имя писали «Algoritmi». Значит, каждый раз, говоря «алгебра» или «алгоритм», мы вспоминаем учёного из Хорезма.', 'The word “algorithm” also comes from al-Khwarizmi’s name: in Latin it was written “Algoritmi”. So every time we say “algebra” or “algorithm”, we remember the scholar from Khorezm.')
    ] },
    { kind: 'rule', h: L('Amallar tartibi va qiymatni topish', 'Порядок действий и нахождение значения', 'Order of operations and finding a value'), p: [
      L('Ifodaning qiymatini topishda amallar tartibi qat’iy: avval <b>qavslar</b> ichi, so‘ng <b>daraja</b>, keyin <b>ko‘paytirish va bo‘lish</b> (chapdan o‘ngga), eng oxirida <b>qo‘shish va ayirish</b>. Manfiy sonni harf o‘rniga qo‘yganda uni albatta qavsga oling: a = −2 bo‘lsa, a<sup>2</sup> = (−2)<sup>2</sup> = 4, lekin −a<sup>2</sup> = −4.', 'При нахождении значения выражения порядок действий строгий: сначала внутри <b>скобок</b>, затем <b>степень</b>, потом <b>умножение и деление</b> (слева направо), в конце <b>сложение и вычитание</b>. Подставляя отрицательное число, обязательно берите его в скобки: при a = −2 имеем a<sup>2</sup> = (−2)<sup>2</sup> = 4, но −a<sup>2</sup> = −4.', 'The order of operations is strict: first inside <b>brackets</b>, then <b>powers</b>, then <b>multiplication and division</b> (left to right), and finally <b>addition and subtraction</b>. When substituting a negative number, always put it in brackets: if a = −2, then a<sup>2</sup> = (−2)<sup>2</sup> = 4, but −a<sup>2</sup> = −4.'),
      L('Ko‘paytirish belgisi harf va son yoki ikki harf orasida odatda yozilmaydi: 3 · n o‘rniga 3n, a · b o‘rniga ab. Son doim harfdan oldin turadi: n3 emas, 3n. 1 · x o‘rniga shunchaki x, (−1) · x o‘rniga −x yoziladi.', 'Знак умножения между буквой и числом или двумя буквами обычно не пишут: вместо 3 · n пишут 3n, вместо a · b — ab. Число всегда стоит перед буквой: 3n, а не n3. Вместо 1 · x пишут просто x, вместо (−1) · x — просто −x.', 'The multiplication sign between a number and a letter, or two letters, is usually left out: 3n instead of 3 · n, ab instead of a · b. The number always comes before the letter: 3n, not n3. Instead of 1 · x we write just x, and instead of (−1) · x we write −x.')
    ] },
    { kind: 'steps', h: L('Qiymat topish algoritmi', 'Алгоритм нахождения значения', 'Algorithm for finding a value'), p: [
      L('Algebraik ifodaning berilgan qiymatdagi sonini topish uchun quyidagi qadamlarni bajaring:', 'Чтобы найти значение алгебраического выражения при данных числах, выполните шаги:', 'To find the value of an algebraic expression for given numbers, follow these steps:')
    ], list: [
      L('1. Ifodani ko‘chirib yozing va har bir harf qaysi songa teng ekanini aniqlang.', '1. Перепишите выражение и выясните, какому числу равна каждая буква.', '1. Copy the expression and note which number each letter equals.'),
      L('2. Harflar o‘rniga sonlarni qo‘ying; manfiy sonlar va kasrlarni qavsga oling.', '2. Подставьте числа вместо букв; отрицательные числа и дроби возьмите в скобки.', '2. Substitute the numbers; put negatives and fractions in brackets.'),
      L('3. Amallar tartibiga rioya qilib hisoblang: qavs → daraja → ko‘paytirish/bo‘lish → qo‘shish/ayirish.', '3. Вычисляйте по порядку: скобки → степень → умножение/деление → сложение/вычитание.', '3. Calculate in order: brackets → powers → multiply/divide → add/subtract.'),
      L('4. Javobni tekshiring: ishoralar to‘g‘rimi, maxrajda nol chiqmadimi?', '4. Проверьте ответ: верны ли знаки, не получился ли ноль в знаменателе?', '4. Check the answer: are the signs right, is there a zero in a denominator?')
    ], after: [
      L('Agar bir ifodani bir nechta qiymatda hisoblash kerak bo‘lsa, avval ifodani <b>soddalashtirish</b> foydali: 3x + 5x − 2x = 6x. Shunda har safar faqat bitta ko‘paytirish qoladi.', 'Если одно выражение нужно вычислить при нескольких значениях, полезно сначала его <b>упростить</b>: 3x + 5x − 2x = 6x. Тогда каждый раз останется лишь одно умножение.', 'If the same expression must be evaluated for several values, it helps to <b>simplify</b> it first: 3x + 5x − 2x = 6x. Then only one multiplication remains each time.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('a = −2, b = 3 bo‘lganda a<sup>2</sup> − 2ab ifodaning qiymatini toping.', 'Найдите значение a<sup>2</sup> − 2ab при a = −2, b = 3.', 'Find the value of a<sup>2</sup> − 2ab when a = −2 and b = 3.'), s: L('a<sup>2</sup> − 2ab = (−2)<sup>2</sup> − 2 · (−2) · 3 = 4 − (−12) = 4 + 12 = <b>16</b>. E’tibor bering: manfiy sonni manfiyga ko‘paytirganda musbat chiqdi.', 'a<sup>2</sup> − 2ab = (−2)<sup>2</sup> − 2 · (−2) · 3 = 4 − (−12) = 4 + 12 = <b>16</b>. Обратите внимание: произведение двух отрицательных дало плюс.', 'a<sup>2</sup> − 2ab = (−2)<sup>2</sup> − 2 · (−2) · 3 = 4 − (−12) = 4 + 12 = <b>16</b>. Notice that the product of two negatives gave a plus.') },
      { q: L('To‘g‘ri to‘rtburchakning tomonlari a = 7 sm, b = 4 sm. Perimetr va yuzni formula bilan toping.', 'Стороны прямоугольника a = 7 см, b = 4 см. Найдите периметр и площадь по формулам.', 'A rectangle has sides a = 7 cm and b = 4 cm. Use formulas to find its perimeter and area.'), s: L('P = 2(a + b) = 2 · (7 + 4) = 2 · 11 = <b>22 sm</b>. S = ab = 7 · 4 = <b>28 sm<sup>2</sup></b>.', 'P = 2(a + b) = 2 · (7 + 4) = 2 · 11 = <b>22 см</b>. S = ab = 7 · 4 = <b>28 см<sup>2</sup></b>.', 'P = 2(a + b) = 2 · (7 + 4) = 2 · 11 = <b>22 cm</b>. S = ab = 7 · 4 = <b>28 cm<sup>2</sup></b>.') },
      { q: L('x = −1 bo‘lganda x<sup>3</sup> + x<sup>2</sup> + x + 1 ning qiymati nechaga teng?', 'Чему равно x<sup>3</sup> + x<sup>2</sup> + x + 1 при x = −1?', 'What is x<sup>3</sup> + x<sup>2</sup> + x + 1 when x = −1?'), s: L('(−1)<sup>3</sup> + (−1)<sup>2</sup> + (−1) + 1 = −1 + 1 − 1 + 1 = <b>0</b>. Toq daraja manfiy, juft daraja musbat chiqadi.', '(−1)<sup>3</sup> + (−1)<sup>2</sup> + (−1) + 1 = −1 + 1 − 1 + 1 = <b>0</b>. Нечётная степень даёт минус, чётная — плюс.', '(−1)<sup>3</sup> + (−1)<sup>2</sup> + (−1) + 1 = −1 + 1 − 1 + 1 = <b>0</b>. An odd power gives a minus, an even power a plus.') },
      { q: L('Poyezd v = 80 km/soat tezlik bilan t = 2,5 soat yurdi. S = vt formula bo‘yicha masofani toping.', 'Поезд ехал со скоростью v = 80 км/ч в течение t = 2,5 ч. Найдите путь по формуле S = vt.', 'A train travelled at v = 80 km/h for t = 2.5 hours. Find the distance using S = vt.'), s: L('S = 80 · 2,5 = <b>200 km</b>. Formula bir xil, faqat sonlar o‘zgaradi — mana shuning uchun formulalar qulay.', 'S = 80 · 2,5 = <b>200 км</b>. Формула одна и та же, меняются только числа — вот почему формулы удобны.', 'S = 80 · 2.5 = <b>200 km</b>. The formula is the same; only the numbers change — that is why formulas are so convenient.') }
    ] },
    { kind: 'table', h: L('Ko‘p uchraydigan formulalar', 'Часто встречающиеся формулы', 'Common formulas'), p: [
      L('Quyidagi jadvalda maktabda eng ko‘p ishlatiladigan formulalar jamlangan. Har birida harflar ma’lum miqdorni bildiradi.', 'В таблице собраны формулы, которые чаще всего используются в школе. В каждой буквы обозначают определённые величины.', 'The table collects the formulas used most often at school. In each one the letters stand for particular quantities.')
    ], table: { head: [L('Formula', 'Формула', 'Formula'), L('Ma’nosi', 'Смысл', 'Meaning'), L('Misol', 'Пример', 'Example')], rows: [
      ['S = v · t', L('yo‘l = tezlik · vaqt', 'путь = скорость · время', 'distance = speed · time'), L('60 · 3 = 180 km', '60 · 3 = 180 км', '60 · 3 = 180 km')],
      ['P = 2(a + b)', L('to‘g‘ri to‘rtburchak perimetri', 'периметр прямоугольника', 'perimeter of a rectangle'), L('2(5 + 3) = 16 sm', '2(5 + 3) = 16 см', '2(5 + 3) = 16 cm')],
      ['S = a · b', L('to‘g‘ri to‘rtburchak yuzi', 'площадь прямоугольника', 'area of a rectangle'), L('5 · 3 = 15 sm<sup>2</sup>', '5 · 3 = 15 см<sup>2</sup>', '5 · 3 = 15 cm<sup>2</sup>')],
      ['V = a · b · c', L('parallelepiped hajmi', 'объём параллелепипеда', 'volume of a box'), L('2 · 3 · 4 = 24 sm<sup>3</sup>', '2 · 3 · 4 = 24 см<sup>3</sup>', '2 · 3 · 4 = 24 cm<sup>3</sup>')],
      ['C = n · p', L('narx = soni · birlik narxi', 'стоимость = количество · цена', 'cost = number · unit price'), L('4 · 3 000 = 12 000 so‘m', '4 · 3 000 = 12 000 сум', '4 · 3 000 = 12 000 sum')],
      ['A = v · t', L('bajarilgan ish = unumdorlik · vaqt', 'работа = производительность · время', 'work = rate · time'), L('5 · 8 = 40 detal', '5 · 8 = 40 деталей', '5 · 8 = 40 parts')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), p: [
      L('Quyidagi xatolar 7-sinf o‘quvchilarida eng ko‘p uchraydi. Ularni oldindan bilib olsangiz, ko‘p ballni saqlab qolasiz.', 'Эти ошибки чаще всего встречаются у семиклассников. Зная их заранее, вы сохраните много баллов.', 'These mistakes are the most common among grade 7 pupils. Knowing them in advance will save you many marks.')
    ], list: [
      L('<b>Qavssiz manfiy son.</b> a = −3 da a<sup>2</sup> ni −3<sup>2</sup> = −9 deb hisoblash xato; to‘g‘risi (−3)<sup>2</sup> = 9.', '<b>Отрицательное число без скобок.</b> При a = −3 считать a<sup>2</sup> как −3<sup>2</sup> = −9 — ошибка; верно (−3)<sup>2</sup> = 9.', '<b>Negative number without brackets.</b> For a = −3, computing a<sup>2</sup> as −3<sup>2</sup> = −9 is wrong; the correct value is (−3)<sup>2</sup> = 9.'),
      L('<b>Amallar tartibini buzish.</b> 2 + 3 · x da avval 2 + 3 ni qo‘shib bo‘lmaydi — ko‘paytirish birinchi.', '<b>Нарушение порядка действий.</b> В 2 + 3 · x нельзя сначала сложить 2 + 3 — умножение выполняется первым.', '<b>Breaking the order of operations.</b> In 2 + 3 · x you cannot add 2 + 3 first — multiplication comes first.'),
      L('<b>2ab ni 2a · 2b deb o‘qish.</b> 2ab — bu 2 · a · b, koeffitsiyent faqat bitta.', '<b>Читать 2ab как 2a · 2b.</b> 2ab — это 2 · a · b, коэффициент один.', '<b>Reading 2ab as 2a · 2b.</b> 2ab means 2 · a · b; there is only one coefficient.'),
      L('<b>Nolga bo‘lishni unutish.</b> 6 : (x − 4) da x = 4 ruxsat etilmagan qiymat.', '<b>Забыть про деление на ноль.</b> В 6 : (x − 4) значение x = 4 недопустимо.', '<b>Forgetting division by zero.</b> In 6 : (x − 4), the value x = 4 is not permitted.'),
      L('<b>Birliklarni tashlab ketish.</b> Formula bilan ishlaganda javob «22» emas, «22 sm» bo‘lishi kerak.', '<b>Терять единицы измерения.</b> При работе с формулой ответ должен быть «22 см», а не просто «22».', '<b>Dropping units.</b> When using a formula, the answer should be “22 cm”, not just “22”.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda uchraydi?', 'Где это встречается в жизни?', 'Where does it appear in real life?'), p: [
      L('Formulalar bizni har kuni o‘rab turadi. Taksi haqi: narx = 5 000 + 2 000 · k, bu yerda k — kilometrlar soni. Telefon tarifi: to‘lov = oylik + m · daqiqa narxi. Oshxonada retseptni 2 marta ko‘paytirish — har bir masalliqni 2n ga aylantirish.', 'Формулы окружают нас каждый день. Плата за такси: цена = 5 000 + 2 000 · k, где k — число километров. Тариф телефона: плата = абонентская + m · цена минуты. Удвоить рецепт на кухне — заменить каждый ингредиент на 2n.', 'Formulas surround us every day. A taxi fare: price = 5 000 + 2 000 · k, where k is the number of kilometres. A phone plan: payment = monthly fee + m · price per minute. Doubling a recipe in the kitchen means turning every ingredient into 2n.'),
      L('Sportda ham formula bor: yuguruvchining o‘rtacha tezligi v = S : t. Qurilishda devorga kerakli g‘ishtlar soni N = S : s, bu yerda S — devor yuzi, s — bitta g‘isht yuzi. Dasturchilar esa har kuni algebraik ifodalar yozadi: <i>total = price * count</i> — bu ham aynan formula.', 'В спорте тоже есть формула: средняя скорость бегуна v = S : t. В строительстве число кирпичей для стены N = S : s, где S — площадь стены, s — площадь одного кирпича. А программисты каждый день пишут алгебраические выражения: <i>total = price * count</i> — это та же формула.', 'Sport has formulas too: a runner’s average speed is v = S : t. In building, the number of bricks for a wall is N = S : s, where S is the wall area and s the area of one brick. Programmers write algebraic expressions every day: <i>total = price * count</i> is exactly a formula.'),
      L('Shuning uchun harflar bilan ishlashni o‘rganish — bu kelajakdagi kasbingiz uchun til o‘rganish bilan barobar.', 'Поэтому научиться работать с буквами — всё равно что выучить язык для будущей профессии.', 'That is why learning to work with letters is like learning a language for your future profession.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«=» tenglik belgisini 1557-yilda uelslik matematik Robert Rekord o‘ylab topgan. U «ikki parallel chiziqdan ko‘ra tengroq narsa yo‘q» degan.', 'Знак равенства «=» придумал в 1557 году валлийский математик Роберт Рекорд. Он сказал, что «нет ничего более равного, чем две параллельные линии».', 'The equals sign “=” was invented in 1557 by the Welsh mathematician Robert Recorde. He said that nothing is more equal than two parallel lines.'),
      L('«+» va «−» belgilari XV asr oxirida nemis savdogarlarining yuk hisob-kitobidan matematikaga o‘tgan.', 'Знаки «+» и «−» пришли в математику в конце XV века из торговых записей немецких купцов.', 'The “+” and “−” signs came into mathematics at the end of the 15th century from the trade records of German merchants.'),
      L('Dekartgacha noma’lumni har kim turlicha belgilagan: italyanlar «cosa» (narsa), nemislar «coss» deb yozgan. Shuning uchun algebra bir paytlar «kossik san’ati» deb atalgan.', 'До Декарта неизвестное обозначали по-разному: итальянцы писали «cosa» (вещь), немцы — «coss». Поэтому алгебру одно время называли «коссическим искусством».', 'Before Descartes, everyone wrote the unknown differently: Italians wrote “cosa” (thing), Germans wrote “coss”. For a while algebra was called “the cossic art”.'),
      L('Bitta formula E = mc<sup>2</sup> dunyodagi eng mashhur algebraik ifoda hisoblanadi — uni Albert Eynshteyn 1905-yilda yozgan.', 'Одна формула E = mc<sup>2</sup> считается самым знаменитым алгебраическим выражением в мире — её записал Альберт Эйнштейн в 1905 году.', 'The single formula E = mc<sup>2</sup> is considered the most famous algebraic expression in the world — Albert Einstein wrote it in 1905.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), p: [
      L('Javobni daftaringizda yozib, keyin tekshiring.', 'Запишите ответ в тетради, затем проверьте.', 'Write your answer in your notebook, then check.')
    ], list: [
      L('1. x = −3 bo‘lganda 2x<sup>2</sup> − 5x + 1 ning qiymatini toping.', '1. Найдите значение 2x<sup>2</sup> − 5x + 1 при x = −3.', '1. Find the value of 2x<sup>2</sup> − 5x + 1 when x = −3.'),
      L('2. 12 : (y + 6) ifodasi uchun y ning qaysi qiymati ruxsat etilmagan?', '2. Какое значение y недопустимо для выражения 12 : (y + 6)?', '2. Which value of y is not permitted in 12 : (y + 6)?'),
      L('3. Kvadrat tomoni a bo‘lsa, perimetr va yuz formulasini yozing; a = 9 da hisoblang.', '3. Запишите формулы периметра и площади квадрата со стороной a; вычислите при a = 9.', '3. Write the perimeter and area formulas for a square of side a; evaluate them for a = 9.'),
      L('4. «Sonning uch karrasidan 7 ayirilgan» ifodani harf bilan yozing.', '4. Запишите буквами: «из утроенного числа вычли 7».', '4. Write with a letter: “7 is subtracted from three times a number”.')
    ], after: [
      L('Javoblar: 1) 2 · 9 + 15 + 1 = 34; 2) y = −6; 3) P = 4a = 36, S = a<sup>2</sup> = 81; 4) 3n − 7.', 'Ответы: 1) 2 · 9 + 15 + 1 = 34; 2) y = −6; 3) P = 4a = 36, S = a<sup>2</sup> = 81; 4) 3n − 7.', 'Answers: 1) 2 · 9 + 15 + 1 = 34; 2) y = −6; 3) P = 4a = 36, S = a<sup>2</sup> = 81; 4) 3n − 7.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Sonli ifoda faqat sonlardan, algebraik ifoda sonlar va harflardan tuziladi.', 'Числовое выражение состоит только из чисел, алгебраическое — из чисел и букв.', 'A numerical expression has only numbers; an algebraic one has numbers and letters.'),
      L('Harflar o‘rniga sonlar qo‘yib, ifodaning qiymatini topamiz.', 'Подставляя числа вместо букв, находим значение выражения.', 'Substituting numbers for letters gives the value of the expression.'),
      L('Manfiy sonni qo‘yganda qavsga oling: (−2)<sup>2</sup> = 4.', 'Подставляя отрицательное число, берите его в скобки: (−2)<sup>2</sup> = 4.', 'Put a negative number in brackets when substituting: (−2)<sup>2</sup> = 4.'),
      L('Maxrajni nolga aylantiradigan qiymatlar ruxsat etilmaydi.', 'Значения, обращающие знаменатель в ноль, недопустимы.', 'Values that make a denominator zero are not permitted.'),
      L('Formula — miqdorlar orasidagi bog‘lanishni harflar bilan yozgan tenglik: S = vt, P = 2(a + b).', 'Формула — равенство, записывающее связь величин буквами: S = vt, P = 2(a + b).', 'A formula is an equality that links quantities with letters: S = vt, P = 2(a + b).'),
      L('«Algebra» so‘zi al-Xorazmiyning «al-jabr» kitobidan, harfli yozuv esa Dekartdan kelgan.', 'Слово «алгебра» пришло из книги аль-Хорезми «аль-джабр», а буквенная запись — от Декарта.', 'The word “algebra” comes from al-Khwarizmi’s “al-jabr”; letter notation comes from Descartes.')
    ] }
  ] });

  // ---------- t2. Natural ko‘rsatkichli daraja va uning xossalari ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Qog‘ozni 42 marta buklash', 'Сложить лист 42 раза', 'Folding paper 42 times'), p: [
      L('Bir varaq qog‘ozning qalinligi taxminan 0,1 mm. Uni bir marta buklasak, qalinlik 2 marta oshadi, ikki marta buklasak — 4 marta, uch marta — 8 marta. Agar qog‘ozni 42 marta buklash mumkin bo‘lganda, uning qalinligi 2<sup>42</sup> · 0,1 mm ≈ 440 000 km bo‘lar edi — Yerdan Oygacha bo‘lgan masofadan ham ko‘p! Bu hisobda «2 ni o‘z-o‘ziga 42 marta ko‘paytirish» bor. Mana shunday takroriy ko‘paytirishni qisqa yozish uchun <b>daraja</b> o‘ylab topilgan.', 'Толщина листа бумаги примерно 0,1 мм. Сложим его один раз — толщина удвоится, два раза — вырастет в 4 раза, три — в 8 раз. Если бы лист можно было сложить 42 раза, его толщина стала бы 2<sup>42</sup> · 0,1 мм ≈ 440 000 км — больше расстояния от Земли до Луны! В этом расчёте «2 умножается само на себя 42 раза». Чтобы коротко записывать такое повторное умножение, придумали <b>степень</b>.', 'A sheet of paper is about 0.1 mm thick. Fold it once and the thickness doubles; fold it twice and it is 4 times thicker; three times gives 8 times. If a sheet could be folded 42 times, its thickness would be 2<sup>42</sup> · 0.1 mm ≈ 440 000 km — more than the distance from the Earth to the Moon! This calculation multiplies 2 by itself 42 times. The <b>power</b> was invented to write such repeated multiplication briefly.'),
      L('Bu mavzuda daraja nima ekanini, uning to‘rtta asosiy xossasini va nega bu xossalar to‘g‘ri ekanini o‘rganamiz. Xossalarni yodlab emas, <i>tushunib</i> olsangiz, hech qachon chalkashmaysiz.', 'В этой теме мы узнаем, что такое степень, её четыре основных свойства и почему они верны. Если не зазубрить, а <i>понять</i> свойства, вы никогда не запутаетесь.', 'In this topic we learn what a power is, its four main laws, and why those laws are true. If you <i>understand</i> the laws instead of memorising them, you will never get confused.')
    ] },
    { kind: 'def', h: L('Daraja, asos, ko‘rsatkich', 'Степень, основание, показатель', 'Power, base, exponent'), p: [
      L('<b>Ta’rif.</b> a sonining natural ko‘rsatkichli darajasi a<sup>n</sup> (n ≥ 2) — bu n ta a ko‘paytuvchining ko‘paytmasi: a<sup>n</sup> = a · a · … · a (n marta). a — <b>asos</b>, n — <b>ko‘rsatkich</b>. Birinchi daraja — sonning o‘zi: a<sup>1</sup> = a.', '<b>Определение.</b> Степень числа a с натуральным показателем n (n ≥ 2) — это произведение n множителей, равных a: a<sup>n</sup> = a · a · … · a (n раз). a — <b>основание</b>, n — <b>показатель</b>. Первая степень — само число: a<sup>1</sup> = a.', '<b>Definition.</b> The power of a with natural exponent n (n ≥ 2) is the product of n factors equal to a: a<sup>n</sup> = a · a · … · a (n times). a is the <b>base</b>, n is the <b>exponent</b>. The first power is the number itself: a<sup>1</sup> = a.'),
      L('Masalan, 2<sup>5</sup> = 2 · 2 · 2 · 2 · 2 = 32, (−3)<sup>3</sup> = (−3) · (−3) · (−3) = −27, (0,5)<sup>2</sup> = 0,25. Ikkinchi daraja <b>kvadrat</b>, uchinchi daraja <b>kub</b> deb ham ataladi, chunki tomoni a bo‘lgan kvadratning yuzi a<sup>2</sup>, kubning hajmi a<sup>3</sup>.', 'Например, 2<sup>5</sup> = 2 · 2 · 2 · 2 · 2 = 32, (−3)<sup>3</sup> = (−3) · (−3) · (−3) = −27, (0,5)<sup>2</sup> = 0,25. Вторую степень называют <b>квадратом</b>, третью — <b>кубом</b>, потому что площадь квадрата со стороной a равна a<sup>2</sup>, а объём куба — a<sup>3</sup>.', 'For example, 2<sup>5</sup> = 2 · 2 · 2 · 2 · 2 = 32, (−3)<sup>3</sup> = (−3) · (−3) · (−3) = −27, (0.5)<sup>2</sup> = 0.25. The second power is called the <b>square</b> and the third the <b>cube</b>, because a square of side a has area a<sup>2</sup> and a cube has volume a<sup>3</sup>.')
    ], list: [
      L('Manfiy sonning <b>juft</b> darajasi musbat: (−2)<sup>4</sup> = 16.', '<b>Чётная</b> степень отрицательного числа положительна: (−2)<sup>4</sup> = 16.', 'An <b>even</b> power of a negative number is positive: (−2)<sup>4</sup> = 16.'),
      L('Manfiy sonning <b>toq</b> darajasi manfiy: (−2)<sup>3</sup> = −8.', '<b>Нечётная</b> степень отрицательного числа отрицательна: (−2)<sup>3</sup> = −8.', 'An <b>odd</b> power of a negative number is negative: (−2)<sup>3</sup> = −8.'),
      L('1 ning istalgan darajasi 1, 0 ning istalgan natural darajasi 0.', 'Любая степень 1 равна 1, любая натуральная степень 0 равна 0.', 'Any power of 1 is 1; any natural power of 0 is 0.'),
      L('(−2)<sup>4</sup> va −2<sup>4</sup> — har xil: birinchisi 16, ikkinchisi −16.', '(−2)<sup>4</sup> и −2<sup>4</sup> — разные вещи: первое равно 16, второе −16.', '(−2)<sup>4</sup> and −2<sup>4</sup> are different: the first is 16, the second is −16.')
    ] },
    { kind: 'history', h: L('Shaxmat taxtasi va bug‘doy donalari', 'Шахматная доска и зёрна пшеницы', 'The chessboard and the grains of wheat'), p: [
      L('Qadimgi afsonaga ko‘ra, shaxmatni o‘ylab topgan donishmand hukmdordan g‘alati mukofot so‘ragan: taxtaning birinchi katagiga 1 dona bug‘doy, ikkinchisiga 2, uchinchisiga 4 — har keyingi katakka oldingisidan 2 marta ko‘p. Hukmdor kuldi: «Shunchami?» Lekin 64-katakda 2<sup>63</sup> dona bug‘doy turishi kerak edi, jami esa 2<sup>64</sup> − 1 ≈ 18 trillion trillion dona — butun dunyo hosilidan ming marta ko‘p.', 'По древней легенде, мудрец, придумавший шахматы, попросил у правителя странную награду: на первую клетку доски 1 зерно пшеницы, на вторую 2, на третью 4 — на каждую следующую вдвое больше. Правитель рассмеялся: «И только?» Но на 64-й клетке должно было лежать 2<sup>63</sup> зёрен, а всего 2<sup>64</sup> − 1 ≈ 18 триллионов триллионов — в тысячи раз больше мирового урожая.', 'According to an old legend, the sage who invented chess asked the ruler for a strange reward: 1 grain of wheat on the first square, 2 on the second, 4 on the third — twice as many on each next square. The ruler laughed: “Is that all?” But the 64th square needed 2<sup>63</sup> grains, and the total 2<sup>64</sup> − 1 ≈ 18 trillion trillion — thousands of times the world harvest.'),
      L('Darajani yuqoriga kichik raqam bilan yozishni 1637-yilda <b>Rene Dekart</b> «Geometriya» asarida joriy qilgan. Undan oldin olimlar x<sup>3</sup> ni «xxx» yoki «kub» deb yozishgan. Ko‘rsatkichlar qoidalarini esa XIV asrda fransuz Nikola Orem va XV asrda samarqandlik <b>G‘iyosiddin Jamshid Koshiy</b> ishlatgan — Koshiy Ulug‘bek rasadxonasida ishlab, 2π ni 16 ta to‘g‘ri raqam bilan hisoblagan.', 'Записывать показатель маленькой цифрой сверху ввёл в 1637 году <b>Рене Декарт</b> в книге «Геометрия». До него x<sup>3</sup> писали как «xxx» или «куб». Правилами показателей пользовались француз Николя Орем в XIV веке и самаркандский учёный <b>Гиясиддин Джамшид Каши</b> в XV веке — Каши работал в обсерватории Улугбека и вычислил 2π с 16 верными знаками.', 'Writing the exponent as a small raised number was introduced by <b>René Descartes</b> in his “Geometry” of 1637. Before him, scholars wrote x<sup>3</sup> as “xxx” or “cube”. Rules for exponents were used by the Frenchman Nicole Oresme in the 14th century and by <b>Jamshid al-Kashi</b> of Samarkand in the 15th century — al-Kashi worked at Ulugh Beg’s observatory and computed 2π to 16 correct digits.')
    ] },
    { kind: 'rule', h: L('Darajaning to‘rt xossasi va ularning sababi', 'Четыре свойства степени и их причины', 'The four laws of powers and why they hold'), p: [
      L('<b>1. Ko‘paytirish:</b> a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup>. Sabab: a<sup>3</sup> · a<sup>4</sup> = (a·a·a) · (a·a·a·a) — jami 3 + 4 = 7 ta ko‘paytuvchi. Asoslar bir xil bo‘lsa, ko‘rsatkichlar qo‘shiladi.', '<b>1. Умножение:</b> a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup>. Причина: a<sup>3</sup> · a<sup>4</sup> = (a·a·a) · (a·a·a·a) — всего 3 + 4 = 7 множителей. При одинаковых основаниях показатели складываются.', '<b>1. Multiplying:</b> a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup>. Reason: a<sup>3</sup> · a<sup>4</sup> = (a·a·a) · (a·a·a·a) — 3 + 4 = 7 factors in all. With the same base, exponents are added.'),
      L('<b>2. Bo‘lish:</b> a<sup>m</sup> : a<sup>n</sup> = a<sup>m−n</sup> (a ≠ 0, m &gt; n). Sabab: a<sup>5</sup> : a<sup>2</sup> kasrida surat va maxrajdagi ikkita a qisqaradi, 5 − 2 = 3 ta qoladi.', '<b>2. Деление:</b> a<sup>m</sup> : a<sup>n</sup> = a<sup>m−n</sup> (a ≠ 0, m &gt; n). Причина: в дроби a<sup>5</sup> : a<sup>2</sup> два множителя a сокращаются, остаётся 5 − 2 = 3.', '<b>2. Dividing:</b> a<sup>m</sup> : a<sup>n</sup> = a<sup>m−n</sup> (a ≠ 0, m &gt; n). Reason: in a<sup>5</sup> : a<sup>2</sup> two factors of a cancel, leaving 5 − 2 = 3.'),
      L('<b>3. Darajaning darajasi:</b> (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>. Sabab: (a<sup>2</sup>)<sup>3</sup> = a<sup>2</sup> · a<sup>2</sup> · a<sup>2</sup> = a<sup>6</sup> — ko‘rsatkichlar ko‘paytiriladi.', '<b>3. Степень степени:</b> (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>. Причина: (a<sup>2</sup>)<sup>3</sup> = a<sup>2</sup> · a<sup>2</sup> · a<sup>2</sup> = a<sup>6</sup> — показатели перемножаются.', '<b>3. Power of a power:</b> (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>. Reason: (a<sup>2</sup>)<sup>3</sup> = a<sup>2</sup> · a<sup>2</sup> · a<sup>2</sup> = a<sup>6</sup> — exponents are multiplied.'),
      L('<b>4. Ko‘paytma va kasrning darajasi:</b> (ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup>, (a/b)<sup>n</sup> = a<sup>n</sup>/b<sup>n</sup>. Sabab: (2a)<sup>3</sup> = 2a · 2a · 2a = 2·2·2 · a·a·a = 8a<sup>3</sup>. Har bir ko‘paytuvchi darajaga ko‘tariladi.', '<b>4. Степень произведения и дроби:</b> (ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup>, (a/b)<sup>n</sup> = a<sup>n</sup>/b<sup>n</sup>. Причина: (2a)<sup>3</sup> = 2a · 2a · 2a = 2·2·2 · a·a·a = 8a<sup>3</sup>. Каждый множитель возводится в степень.', '<b>4. Power of a product or fraction:</b> (ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup>, (a/b)<sup>n</sup> = a<sup>n</sup>/b<sup>n</sup>. Reason: (2a)<sup>3</sup> = 2a · 2a · 2a = 2·2·2 · a·a·a = 8a<sup>3</sup>. Every factor is raised to the power.'),
      L('Muhim: yig‘indi uchun bunday qoida <b>yo‘q</b>! (a + b)<sup>2</sup> ≠ a<sup>2</sup> + b<sup>2</sup>. Tekshiring: (1 + 2)<sup>2</sup> = 9, lekin 1 + 4 = 5.', 'Важно: для суммы такого правила <b>нет</b>! (a + b)<sup>2</sup> ≠ a<sup>2</sup> + b<sup>2</sup>. Проверьте: (1 + 2)<sup>2</sup> = 9, а 1 + 4 = 5.', 'Important: there is <b>no</b> such rule for a sum! (a + b)<sup>2</sup> ≠ a<sup>2</sup> + b<sup>2</sup>. Check: (1 + 2)<sup>2</sup> = 9, but 1 + 4 = 5.')
    ] },
    { kind: 'steps', h: L('Ifodani soddalashtirish tartibi', 'Порядок упрощения выражения', 'How to simplify an expression'), list: [
      L('1. Har bir qavsni alohida oching: (a<sup>2</sup>b)<sup>3</sup> = a<sup>6</sup>b<sup>3</sup>.', '1. Раскройте каждую скобку отдельно: (a<sup>2</sup>b)<sup>3</sup> = a<sup>6</sup>b<sup>3</sup>.', '1. Expand each bracket separately: (a<sup>2</sup>b)<sup>3</sup> = a<sup>6</sup>b<sup>3</sup>.'),
      L('2. Bir xil asosli darajalarni ko‘paytirganda ko‘rsatkichlarni qo‘shing, bo‘lganda ayiring.', '2. При умножении степеней с одинаковым основанием складывайте показатели, при делении — вычитайте.', '2. When multiplying powers with the same base add the exponents; when dividing, subtract.'),
      L('3. Son koeffitsiyentlarni alohida hisoblang: 2<sup>3</sup> · 2<sup>2</sup> = 2<sup>5</sup> = 32.', '3. Числовые коэффициенты считайте отдельно: 2<sup>3</sup> · 2<sup>2</sup> = 2<sup>5</sup> = 32.', '3. Work out numerical coefficients separately: 2<sup>3</sup> · 2<sup>2</sup> = 2<sup>5</sup> = 32.'),
      L('4. Manfiy asosning ishorasini ko‘rsatkich juft-toqligiga qarab aniqlang.', '4. Знак отрицательного основания определяйте по чётности показателя.', '4. Decide the sign of a negative base from whether the exponent is even or odd.'),
      L('5. Javobni standart ko‘rinishda yozing: oldin son, keyin harflar alifbo tartibida.', '5. Запишите ответ в стандартном виде: сначала число, затем буквы по алфавиту.', '5. Write the answer in standard form: number first, then letters in alphabetical order.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Soddalashtiring: x<sup>3</sup> · x<sup>4</sup> · x.', 'Упростите: x<sup>3</sup> · x<sup>4</sup> · x.', 'Simplify: x<sup>3</sup> · x<sup>4</sup> · x.'), s: L('x = x<sup>1</sup> ekanini eslaymiz. Ko‘rsatkichlar qo‘shiladi: 3 + 4 + 1 = 8. Javob: <b>x<sup>8</sup></b>.', 'Помним, что x = x<sup>1</sup>. Показатели складываются: 3 + 4 + 1 = 8. Ответ: <b>x<sup>8</sup></b>.', 'Remember x = x<sup>1</sup>. Exponents add: 3 + 4 + 1 = 8. Answer: <b>x<sup>8</sup></b>.') },
      { q: L('Hisoblang: 2<sup>10</sup> : 2<sup>7</sup>.', 'Вычислите: 2<sup>10</sup> : 2<sup>7</sup>.', 'Calculate: 2<sup>10</sup> : 2<sup>7</sup>.'), s: L('Asoslar bir xil, ko‘rsatkichlar ayiriladi: 2<sup>10−7</sup> = 2<sup>3</sup> = <b>8</b>. 1024 : 128 ni hisoblashdan ancha oson!', 'Основания одинаковые, показатели вычитаются: 2<sup>10−7</sup> = 2<sup>3</sup> = <b>8</b>. Намного проще, чем делить 1024 на 128!', 'Same base, so subtract exponents: 2<sup>10−7</sup> = 2<sup>3</sup> = <b>8</b>. Much easier than dividing 1024 by 128!') },
      { q: L('Soddalashtiring: (−2a<sup>2</sup>b)<sup>3</sup>.', 'Упростите: (−2a<sup>2</sup>b)<sup>3</sup>.', 'Simplify: (−2a<sup>2</sup>b)<sup>3</sup>.'), s: L('Har bir ko‘paytuvchini kubga ko‘taramiz: (−2)<sup>3</sup> · (a<sup>2</sup>)<sup>3</sup> · b<sup>3</sup> = −8 · a<sup>6</sup> · b<sup>3</sup> = <b>−8a<sup>6</sup>b<sup>3</sup></b>. Toq daraja — ishora saqlanadi.', 'Возводим каждый множитель в куб: (−2)<sup>3</sup> · (a<sup>2</sup>)<sup>3</sup> · b<sup>3</sup> = −8 · a<sup>6</sup> · b<sup>3</sup> = <b>−8a<sup>6</sup>b<sup>3</sup></b>. Нечётная степень — знак сохраняется.', 'Cube each factor: (−2)<sup>3</sup> · (a<sup>2</sup>)<sup>3</sup> · b<sup>3</sup> = −8 · a<sup>6</sup> · b<sup>3</sup> = <b>−8a<sup>6</sup>b<sup>3</sup></b>. Odd power, so the sign stays.') },
      { q: L('Hisoblang: 4<sup>5</sup> · 25<sup>5</sup>.', 'Вычислите: 4<sup>5</sup> · 25<sup>5</sup>.', 'Calculate: 4<sup>5</sup> · 25<sup>5</sup>.'), s: L('Ko‘rsatkichlar bir xil — 4-xossani teskari ishlatamiz: (4 · 25)<sup>5</sup> = 100<sup>5</sup> = <b>10 000 000 000</b> (10 milliard). Darajalarni alohida hisoblash shart emas.', 'Показатели одинаковые — применяем 4-е свойство в обратную сторону: (4 · 25)<sup>5</sup> = 100<sup>5</sup> = <b>10 000 000 000</b> (10 миллиардов). Считать степени по отдельности не нужно.', 'Same exponents, so use law 4 backwards: (4 · 25)<sup>5</sup> = 100<sup>5</sup> = <b>10 000 000 000</b> (ten billion). No need to compute the powers separately.') },
      { q: L('Taqqoslang: 2<sup>30</sup> va 3<sup>20</sup>.', 'Сравните: 2<sup>30</sup> и 3<sup>20</sup>.', 'Compare 2<sup>30</sup> and 3<sup>20</sup>.'), s: L('Umumiy ko‘rsatkich 10 ga keltiramiz: 2<sup>30</sup> = (2<sup>3</sup>)<sup>10</sup> = 8<sup>10</sup>, 3<sup>20</sup> = (3<sup>2</sup>)<sup>10</sup> = 9<sup>10</sup>. 8 &lt; 9, demak <b>2<sup>30</sup> &lt; 3<sup>20</sup></b>.', 'Приводим к общему показателю 10: 2<sup>30</sup> = (2<sup>3</sup>)<sup>10</sup> = 8<sup>10</sup>, 3<sup>20</sup> = (3<sup>2</sup>)<sup>10</sup> = 9<sup>10</sup>. 8 &lt; 9, значит <b>2<sup>30</sup> &lt; 3<sup>20</sup></b>.', 'Bring both to exponent 10: 2<sup>30</sup> = (2<sup>3</sup>)<sup>10</sup> = 8<sup>10</sup>, 3<sup>20</sup> = (3<sup>2</sup>)<sup>10</sup> = 9<sup>10</sup>. Since 8 &lt; 9, <b>2<sup>30</sup> &lt; 3<sup>20</sup></b>.') }
    ] },
    { kind: 'table', h: L('Ikkining darajalari', 'Степени двойки', 'Powers of two'), p: [
      L('Ikkining darajalari kompyuter olamida hamma joyda uchraydi: 1 bayt = 2<sup>3</sup> bit, 1 kilobayt = 2<sup>10</sup> bayt. Ularni yodda tutish foydali.', 'Степени двойки встречаются в мире компьютеров повсюду: 1 байт = 2<sup>3</sup> бит, 1 килобайт = 2<sup>10</sup> байт. Их полезно помнить.', 'Powers of two are everywhere in the computer world: 1 byte = 2<sup>3</sup> bits, 1 kilobyte = 2<sup>10</sup> bytes. They are worth remembering.')
    ], table: { head: [L('Daraja', 'Степень', 'Power'), L('Qiymat', 'Значение', 'Value'), L('Daraja', 'Степень', 'Power'), L('Qiymat', 'Значение', 'Value')], rows: [
      ['2<sup>1</sup>', '2', '2<sup>6</sup>', '64'],
      ['2<sup>2</sup>', '4', '2<sup>7</sup>', '128'],
      ['2<sup>3</sup>', '8', '2<sup>8</sup>', '256'],
      ['2<sup>4</sup>', '16', '2<sup>9</sup>', '512'],
      ['2<sup>5</sup>', '32', '2<sup>10</sup>', '1024']
    ] }, after: [
      L('Shuningdek, 3<sup>4</sup> = 81, 5<sup>3</sup> = 125, 10<sup>6</sup> = 1 000 000 (million), 10<sup>9</sup> = milliard. O‘nning darajasida ko‘rsatkich nollar sonini bildiradi.', 'Также 3<sup>4</sup> = 81, 5<sup>3</sup> = 125, 10<sup>6</sup> = 1 000 000 (миллион), 10<sup>9</sup> = миллиард. У степени десяти показатель равен числу нулей.', 'Also 3<sup>4</sup> = 81, 5<sup>3</sup> = 125, 10<sup>6</sup> = 1 000 000 (a million), 10<sup>9</sup> = a billion. In a power of ten the exponent equals the number of zeros.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Ko‘rsatkichlarni ko‘paytirish.</b> a<sup>3</sup> · a<sup>4</sup> = a<sup>12</sup> — xato! To‘g‘risi a<sup>7</sup>: ko‘paytirganda ko‘rsatkichlar qo‘shiladi.', '<b>Перемножать показатели.</b> a<sup>3</sup> · a<sup>4</sup> = a<sup>12</sup> — ошибка! Верно a<sup>7</sup>: при умножении показатели складываются.', '<b>Multiplying exponents.</b> a<sup>3</sup> · a<sup>4</sup> = a<sup>12</sup> is wrong! The answer is a<sup>7</sup>: exponents add when multiplying.'),
      L('<b>Asoslarni ko‘paytirish.</b> 2<sup>3</sup> · 2<sup>2</sup> = 4<sup>5</sup> — xato! Asos o‘zgarmaydi: 2<sup>5</sup> = 32.', '<b>Перемножать основания.</b> 2<sup>3</sup> · 2<sup>2</sup> = 4<sup>5</sup> — ошибка! Основание не меняется: 2<sup>5</sup> = 32.', '<b>Multiplying bases.</b> 2<sup>3</sup> · 2<sup>2</sup> = 4<sup>5</sup> is wrong! The base stays: 2<sup>5</sup> = 32.'),
      L('<b>Har xil asosli darajalarni qo‘shib yuborish.</b> a<sup>2</sup> · b<sup>3</sup> ni soddalashtirib bo‘lmaydi — asoslar turli.', '<b>Складывать показатели при разных основаниях.</b> a<sup>2</sup> · b<sup>3</sup> упростить нельзя — основания разные.', '<b>Adding exponents with different bases.</b> a<sup>2</sup> · b<sup>3</sup> cannot be simplified — the bases differ.'),
      L('<b>Yig‘indining darajasi.</b> (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> — eng mashhur xato. To‘g‘ri formula keyingi bobda.', '<b>Степень суммы.</b> (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> — самая знаменитая ошибка. Верную формулу узнаем в следующей главе.', '<b>Power of a sum.</b> (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> is the most famous mistake. The correct formula comes in the next chapter.'),
      L('<b>Ishorani unutish.</b> (−3)<sup>2</sup> = −9 emas, 9. Lekin −3<sup>2</sup> = −9.', '<b>Забыть про знак.</b> (−3)<sup>2</sup> = 9, а не −9. Но −3<sup>2</sup> = −9.', '<b>Forgetting the sign.</b> (−3)<sup>2</sup> = 9, not −9. But −3<sup>2</sup> = −9.'),
      L('<b>Darajani ko‘paytirish bilan almashtirish.</b> 2<sup>3</sup> = 6 emas, 8; 5<sup>2</sup> = 10 emas, 25.', '<b>Путать степень с умножением.</b> 2<sup>3</sup> = 8, а не 6; 5<sup>2</sup> = 25, а не 10.', '<b>Confusing a power with multiplication.</b> 2<sup>3</sup> = 8, not 6; 5<sup>2</sup> = 25, not 10.')
    ] },
    { kind: 'life', h: L('Darajalar hayotda', 'Степени в жизни', 'Powers in real life'), p: [
      L('<b>Kompyuter xotirasi.</b> Telefoningizda 128 GB xotira bo‘lsa, bu 2<sup>7</sup> GB, har GB esa 2<sup>30</sup> bayt. Dasturchilar ikkining darajalarini xuddi ko‘paytirish jadvalidek biladi.', '<b>Память компьютера.</b> Если в телефоне 128 ГБ памяти, это 2<sup>7</sup> ГБ, а каждый ГБ — 2<sup>30</sup> байт. Программисты знают степени двойки как таблицу умножения.', '<b>Computer memory.</b> If your phone has 128 GB of storage, that is 2<sup>7</sup> GB, and each GB is 2<sup>30</sup> bytes. Programmers know the powers of two like a times table.'),
      L('<b>Bakteriyalar ko‘payishi.</b> Ba’zi bakteriyalar har 20 daqiqada ikkiga bo‘linadi. 1 ta bakteriyadan 10 soatda 2<sup>30</sup> ≈ 1 milliard bakteriya paydo bo‘ladi. Shuning uchun ovqatni muzlatgichda saqlash muhim: sovuq bo‘linishni sekinlashtiradi.', '<b>Размножение бактерий.</b> Некоторые бактерии делятся надвое каждые 20 минут. Из 1 бактерии за 10 часов получается 2<sup>30</sup> ≈ 1 миллиард. Поэтому важно хранить еду в холодильнике: холод замедляет деление.', '<b>Bacteria growth.</b> Some bacteria split in two every 20 minutes. From 1 bacterium, 10 hours give 2<sup>30</sup> ≈ 1 billion. That is why food belongs in the fridge: cold slows the splitting.'),
      L('<b>Zilzila kuchi.</b> Rixter shkalasida har bir ball zilzila energiyasini taxminan 32 marta oshiradi: 7 balli zilzila 5 ballidan 32<sup>2</sup> ≈ 1000 marta kuchli. <b>Astronomiya.</b> Quyoshgacha masofa 1,5 · 10<sup>8</sup> km, Quyosh massasi 2 · 10<sup>30</sup> kg — bunday sonlarni darajasiz yozish deyarli mumkin emas.', '<b>Сила землетрясения.</b> Каждый балл шкалы Рихтера увеличивает энергию примерно в 32 раза: землетрясение в 7 баллов в 32<sup>2</sup> ≈ 1000 раз сильнее, чем в 5. <b>Астрономия.</b> Расстояние до Солнца 1,5 · 10<sup>8</sup> км, масса Солнца 2 · 10<sup>30</sup> кг — такие числа без степеней почти не записать.', '<b>Earthquake strength.</b> Each step on the Richter scale multiplies the energy by about 32: a magnitude 7 quake is 32<sup>2</sup> ≈ 1000 times stronger than magnitude 5. <b>Astronomy.</b> The Sun is 1.5 · 10<sup>8</sup> km away and has mass 2 · 10<sup>30</sup> kg — such numbers are almost impossible to write without powers.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('2<sup>10</sup> = 1024 ≈ 1000. Shuning uchun kompyuterda «kilo» 1000 emas, 1024 ni bildiradi.', '2<sup>10</sup> = 1024 ≈ 1000. Поэтому в компьютере «кило» означает не 1000, а 1024.', '2<sup>10</sup> = 1024 ≈ 1000. That is why in computing “kilo” means 1024, not 1000.'),
      L('Googol — 10<sup>100</sup>, ya’ni 1 dan keyin 100 ta nol. Koinotdagi barcha atomlar soni «faqat» 10<sup>80</sup> atrofida. Google kompaniyasining nomi shu sondan olingan.', 'Гугол — 10<sup>100</sup>, то есть единица со ста нулями. Атомов во Вселенной «всего» около 10<sup>80</sup>. Название компании Google произошло от этого числа.', 'A googol is 10<sup>100</sup>, a 1 followed by 100 zeros. The universe contains “only” about 10<sup>80</sup> atoms. The company name Google comes from this number.'),
      L('Eng katta ma’lum tub son 2<sup>136 279 841</sup> − 1 — unda 41 milliondan ortiq raqam bor (2024-yilda topilgan).', 'Наибольшее известное простое число — 2<sup>136 279 841</sup> − 1, в нём более 41 миллиона цифр (найдено в 2024 году).', 'The largest known prime is 2<sup>136 279 841</sup> − 1 — it has over 41 million digits (found in 2024).'),
      L('Istalgan sonning oxirgi raqami darajalarda davriy takrorlanadi: 7<sup>1</sup>=7, 7<sup>2</sup>=49, 7<sup>3</sup>=343, 7<sup>4</sup>=2401, 7<sup>5</sup>=16807 — oxirgi raqamlar 7, 9, 3, 1, 7, …', 'Последняя цифра степеней повторяется по кругу: 7<sup>1</sup>=7, 7<sup>2</sup>=49, 7<sup>3</sup>=343, 7<sup>4</sup>=2401, 7<sup>5</sup>=16807 — последние цифры 7, 9, 3, 1, 7, …', 'The last digit of powers repeats in a cycle: 7<sup>1</sup>=7, 7<sup>2</sup>=49, 7<sup>3</sup>=343, 7<sup>4</sup>=2401, 7<sup>5</sup>=16807 — the last digits go 7, 9, 3, 1, 7, …')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. Soddalashtiring: a<sup>5</sup> · a<sup>3</sup> : a<sup>6</sup>.', '1. Упростите: a<sup>5</sup> · a<sup>3</sup> : a<sup>6</sup>.', '1. Simplify: a<sup>5</sup> · a<sup>3</sup> : a<sup>6</sup>.'),
      L('2. Hisoblang: (−1)<sup>99</sup> + (−1)<sup>100</sup>.', '2. Вычислите: (−1)<sup>99</sup> + (−1)<sup>100</sup>.', '2. Calculate: (−1)<sup>99</sup> + (−1)<sup>100</sup>.'),
      L('3. 8<sup>4</sup> ni ikkining darajasi ko‘rinishida yozing.', '3. Запишите 8<sup>4</sup> в виде степени двойки.', '3. Write 8<sup>4</sup> as a power of two.'),
      L('4. 3<sup>100</sup> sonining oxirgi raqami qanday? (3, 9, 7, 1 davrini ishlating.)', '4. Какая последняя цифра у 3<sup>100</sup>? (Используйте цикл 3, 9, 7, 1.)', '4. What is the last digit of 3<sup>100</sup>? (Use the cycle 3, 9, 7, 1.)')
    ], after: [
      L('Javoblar: 1) a<sup>2</sup>; 2) −1 + 1 = 0; 3) (2<sup>3</sup>)<sup>4</sup> = 2<sup>12</sup>; 4) 100 = 4 · 25, davr to‘liq tugaydi — oxirgi raqam 1.', 'Ответы: 1) a<sup>2</sup>; 2) −1 + 1 = 0; 3) (2<sup>3</sup>)<sup>4</sup> = 2<sup>12</sup>; 4) 100 = 4 · 25, цикл завершается — последняя цифра 1.', 'Answers: 1) a<sup>2</sup>; 2) −1 + 1 = 0; 3) (2<sup>3</sup>)<sup>4</sup> = 2<sup>12</sup>; 4) 100 = 4 · 25, the cycle completes — last digit 1.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('a<sup>n</sup> — n ta a ko‘paytuvchining ko‘paytmasi; a — asos, n — ko‘rsatkich.', 'a<sup>n</sup> — произведение n множителей a; a — основание, n — показатель.', 'a<sup>n</sup> is the product of n factors a; a is the base, n the exponent.'),
      L('a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup> — ko‘paytirganda ko‘rsatkichlar qo‘shiladi.', 'a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup> — при умножении показатели складываются.', 'a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup> — exponents add when multiplying.'),
      L('a<sup>m</sup> : a<sup>n</sup> = a<sup>m−n</sup> — bo‘lganda ayiriladi.', 'a<sup>m</sup> : a<sup>n</sup> = a<sup>m−n</sup> — при делении вычитаются.', 'a<sup>m</sup> : a<sup>n</sup> = a<sup>m−n</sup> — exponents subtract when dividing.'),
      L('(a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup> — darajaning darajasida ko‘paytiriladi.', '(a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup> — при возведении степени в степень перемножаются.', '(a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup> — exponents multiply for a power of a power.'),
      L('(ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup> — ko‘paytmaning har bir ko‘paytuvchisi darajaga ko‘tariladi; yig‘indi uchun bunday qoida yo‘q.', '(ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup> — каждый множитель произведения возводится в степень; для суммы такого правила нет.', '(ab)<sup>n</sup> = a<sup>n</sup>b<sup>n</sup> — each factor of a product is raised to the power; there is no such rule for a sum.'),
      L('Manfiy asosning juft darajasi musbat, toq darajasi manfiy.', 'Чётная степень отрицательного основания положительна, нечётная — отрицательна.', 'An even power of a negative base is positive; an odd power is negative.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-2';

  // ---------- t3. Birhadlar ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Algebraning «g‘ishtlari»', '«Кирпичики» алгебры', 'The bricks of algebra'), p: [
      L('Uy g‘ishtlardan quriladi, so‘z harflardan, algebraik ifodalar esa <b>birhadlardan</b>. 5x, −3a<sup>2</sup>b, 0,5xy<sup>3</sup> — bularning har biri birhad. Ular sonlar va harflarning ko‘paytmasidan iborat, ichida qo‘shish ham, ayirish ham yo‘q. Keyingi mavzularda ko‘phadlar, qisqa ko‘paytirish formulalari va algebraik kasrlar — hammasi birhadlardan yig‘iladi.', 'Дом строится из кирпичей, слово — из букв, а алгебраические выражения — из <b>одночленов</b>. 5x, −3a<sup>2</sup>b, 0,5xy<sup>3</sup> — каждое из них одночлен. Они состоят из произведения чисел и букв, внутри нет ни сложения, ни вычитания. В следующих темах многочлены, формулы сокращённого умножения и алгебраические дроби — всё собирается из одночленов.', 'A house is built from bricks, a word from letters, and algebraic expressions from <b>monomials</b>. 5x, −3a<sup>2</sup>b, 0.5xy<sup>3</sup> — each of these is a monomial. They are products of numbers and letters, with no addition or subtraction inside. In the coming topics, polynomials, special products and algebraic fractions are all assembled from monomials.'),
      L('Bu mavzuda birhadni standart shaklga keltirishni, uning koeffitsiyenti va darajasini aniqlashni, birhadlarni ko‘paytirish, darajaga ko‘tarish va bo‘lishni o‘rganamiz. Bunda oldingi mavzudagi daraja xossalari asosiy quroldir.', 'В этой теме мы научимся приводить одночлен к стандартному виду, находить его коэффициент и степень, умножать одночлены, возводить их в степень и делить. Главный инструмент — свойства степени из прошлой темы.', 'In this topic we learn to put a monomial in standard form, find its coefficient and degree, and multiply, raise to a power and divide monomials. Our main tool is the laws of powers from the previous topic.')
    ] },
    { kind: 'def', h: L('Birhad, koeffitsiyent, daraja', 'Одночлен, коэффициент, степень', 'Monomial, coefficient, degree'), p: [
      L('<b>Birhad</b> — sonlar, o‘zgaruvchilar va ularning natural darajalari ko‘paytmasidan iborat ifoda. Masalan: 7, x, −2ab, 3x<sup>2</sup>y · 4y. Yolg‘iz son ham, yolg‘iz harf ham birhad hisoblanadi. Lekin a + b, x − 1, 5 : x birhad emas.', '<b>Одночлен</b> — выражение, являющееся произведением чисел, переменных и их натуральных степеней. Например: 7, x, −2ab, 3x<sup>2</sup>y · 4y. Отдельное число и отдельная буква тоже одночлены. А вот a + b, x − 1, 5 : x — не одночлены.', 'A <b>monomial</b> is an expression that is a product of numbers, variables and their natural powers. For example: 7, x, −2ab, 3x<sup>2</sup>y · 4y. A single number or a single letter is also a monomial. But a + b, x − 1 and 5 : x are not.'),
      L('Birhad <b>standart shaklda</b> yozilgan deyiladi, agar unda birinchi o‘rinda bitta son ko‘paytuvchi turgan bo‘lsa, har bir harf faqat bir marta (o‘z darajasi bilan) qatnashsa. Masalan, 3x<sup>2</sup>y · 4y ning standart shakli 12x<sup>2</sup>y<sup>2</sup>. Birinchi turgan son — <b>koeffitsiyent</b> (bu yerda 12). Barcha harflar ko‘rsatkichlari yig‘indisi — <b>birhadning darajasi</b> (2 + 2 = 4).', 'Одночлен записан в <b>стандартном виде</b>, если в нём на первом месте стоит один числовой множитель и каждая буква встречается только один раз (со своей степенью). Например, стандартный вид 3x<sup>2</sup>y · 4y — это 12x<sup>2</sup>y<sup>2</sup>. Число впереди — <b>коэффициент</b> (здесь 12). Сумма показателей всех букв — <b>степень одночлена</b> (2 + 2 = 4).', 'A monomial is in <b>standard form</b> if a single numerical factor comes first and each letter appears only once (with its power). For example, the standard form of 3x<sup>2</sup>y · 4y is 12x<sup>2</sup>y<sup>2</sup>. The number in front is the <b>coefficient</b> (here 12). The sum of the exponents of all letters is the <b>degree of the monomial</b> (2 + 2 = 4).')
    ], list: [
      L('x<sup>3</sup> ning koeffitsiyenti 1, −ab ning koeffitsiyenti −1.', 'Коэффициент x<sup>3</sup> равен 1, коэффициент −ab равен −1.', 'The coefficient of x<sup>3</sup> is 1, and of −ab is −1.'),
      L('Nolga teng bo‘lmagan sonning darajasi 0: masalan, 7 — nolinchi darajali birhad.', 'Число, не равное нулю, — одночлен нулевой степени: например, 7.', 'A non-zero number is a monomial of degree 0: for example, 7.'),
      L('Harf qismi bir xil birhadlar <b>o‘xshash</b> deyiladi: 5a<sup>2</sup>b va −2a<sup>2</sup>b.', 'Одночлены с одинаковой буквенной частью называются <b>подобными</b>: 5a<sup>2</sup>b и −2a<sup>2</sup>b.', 'Monomials with the same letter part are called <b>like</b> terms: 5a<sup>2</sup>b and −2a<sup>2</sup>b.')
    ] },
    { kind: 'history', h: L('Diofant va «arifmetika»', 'Диофант и «Арифметика»', 'Diophantus and his Arithmetica'), p: [
      L('III asrda Iskandariyada yashagan yunon matematigi <b>Diofant</b> birinchilardan bo‘lib noma’lum va uning darajalari uchun qisqa belgilar ishlatgan. U noma’lumning kvadratini «dinamis», kubini «kubos» deb atagan va bu so‘zlarning bosh harflarini yozgan. Uning «Arifmetika» kitobi keyinchalik arab tiliga tarjima qilinib, Sharq olimlariga ham ma’lum bo‘lgan.', 'В III веке в Александрии жил греческий математик <b>Диофант</b>, одним из первых использовавший краткие обозначения для неизвестного и его степеней. Квадрат неизвестного он называл «динамис», куб — «кубос» и записывал первые буквы этих слов. Его книгу «Арифметика» позже перевели на арабский, и она стала известна учёным Востока.', 'In the 3rd century, the Greek mathematician <b>Diophantus</b> of Alexandria was among the first to use short symbols for an unknown and its powers. He called the square of the unknown “dynamis” and the cube “kubos”, and wrote the first letters of these words. His book “Arithmetica” was later translated into Arabic and became known to scholars in the East.'),
      L('Al-Xorazmiy esa noma’lumni «shay», kvadratini «mol», sonni «dirham» deb atagan — bu xuddi bugungi birhadlar turlariga mos keladi: x, x<sup>2</sup> va son. «Koeffitsiyent» so‘zini esa XVI asrda Fransua Viyet kiritgan; lotincha «birgalikda ta’sir qiluvchi» degan ma’noni bildiradi.', 'Аль-Хорезми называл неизвестное «шай», его квадрат — «маль», а число — «дирхам». Это точно соответствует нынешним видам одночленов: x, x<sup>2</sup> и число. А слово «коэффициент» ввёл в XVI веке Франсуа Виет; по-латыни оно означает «содействующий».', 'Al-Khwarizmi called the unknown “shay”, its square “mal” and a plain number “dirham” — which matches today’s kinds of monomials: x, x<sup>2</sup> and a number. The word “coefficient” was introduced in the 16th century by François Viète; in Latin it means “acting together”.')
    ] },
    { kind: 'rule', h: L('Birhadlar ustida amallar', 'Действия с одночленами', 'Operations on monomials'), p: [
      L('<b>Ko‘paytirish.</b> Koeffitsiyentlar ko‘paytiriladi, bir xil harflarning ko‘rsatkichlari qo‘shiladi: 3a<sup>2</sup>b · 2ab<sup>3</sup> = (3 · 2) · a<sup>2+1</sup> · b<sup>1+3</sup> = 6a<sup>3</sup>b<sup>4</sup>. Bu ko‘paytirishning o‘rin almashtirish va guruhlash xossalari hamda a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup> qoidasidan kelib chiqadi.', '<b>Умножение.</b> Коэффициенты перемножаются, показатели одинаковых букв складываются: 3a<sup>2</sup>b · 2ab<sup>3</sup> = (3 · 2) · a<sup>2+1</sup> · b<sup>1+3</sup> = 6a<sup>3</sup>b<sup>4</sup>. Это следует из переместительного и сочетательного законов умножения и правила a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup>.', '<b>Multiplying.</b> Multiply the coefficients and add the exponents of matching letters: 3a<sup>2</sup>b · 2ab<sup>3</sup> = (3 · 2) · a<sup>2+1</sup> · b<sup>1+3</sup> = 6a<sup>3</sup>b<sup>4</sup>. This follows from the commutative and associative laws of multiplication and the rule a<sup>m</sup> · a<sup>n</sup> = a<sup>m+n</sup>.'),
      L('<b>Darajaga ko‘tarish.</b> Koeffitsiyent darajaga ko‘tariladi, har bir harfning ko‘rsatkichi daraja ko‘rsatkichiga ko‘paytiriladi: (−2x<sup>3</sup>y)<sup>2</sup> = 4x<sup>6</sup>y<sup>2</sup>.', '<b>Возведение в степень.</b> Коэффициент возводится в степень, показатель каждой буквы умножается на показатель степени: (−2x<sup>3</sup>y)<sup>2</sup> = 4x<sup>6</sup>y<sup>2</sup>.', '<b>Raising to a power.</b> Raise the coefficient to the power and multiply each letter’s exponent by it: (−2x<sup>3</sup>y)<sup>2</sup> = 4x<sup>6</sup>y<sup>2</sup>.'),
      L('<b>Bo‘lish.</b> Koeffitsiyentlar bo‘linadi, ko‘rsatkichlar ayiriladi: 12x<sup>5</sup>y<sup>3</sup> : 4x<sup>2</sup>y = 3x<sup>3</sup>y<sup>2</sup>. Natija birhad bo‘lishi uchun bo‘luvchidagi har bir harf bo‘linuvchida ham kamida shuncha darajada bo‘lishi kerak.', '<b>Деление.</b> Коэффициенты делятся, показатели вычитаются: 12x<sup>5</sup>y<sup>3</sup> : 4x<sup>2</sup>y = 3x<sup>3</sup>y<sup>2</sup>. Чтобы результат был одночленом, каждая буква делителя должна входить в делимое не в меньшей степени.', '<b>Dividing.</b> Divide the coefficients and subtract the exponents: 12x<sup>5</sup>y<sup>3</sup> : 4x<sup>2</sup>y = 3x<sup>3</sup>y<sup>2</sup>. For the result to be a monomial, each letter of the divisor must appear in the dividend with at least the same power.')
    ] },
    { kind: 'steps', h: L('Standart shaklga keltirish', 'Приведение к стандартному виду', 'Putting a monomial in standard form'), list: [
      L('1. Barcha son ko‘paytuvchilarni topib, ularni ko‘paytiring — bu koeffitsiyent.', '1. Найдите все числовые множители и перемножьте их — это коэффициент.', '1. Find all the numerical factors and multiply them — that is the coefficient.'),
      L('2. Ishorani aniqlang: manfiy ko‘paytuvchilar soni juft bo‘lsa «+», toq bo‘lsa «−».', '2. Определите знак: чётное число отрицательных множителей — «+», нечётное — «−».', '2. Work out the sign: an even number of negative factors gives “+”, an odd number gives “−”.'),
      L('3. Har bir harf uchun barcha ko‘rsatkichlarni qo‘shing.', '3. Для каждой буквы сложите все её показатели.', '3. For each letter, add all its exponents.'),
      L('4. Koeffitsiyentni oldinga, harflarni alifbo tartibida yozing.', '4. Запишите коэффициент впереди, а буквы — в алфавитном порядке.', '4. Write the coefficient first, then the letters in alphabetical order.')
    ], after: [
      L('Masalan: −2x · 5y<sup>2</sup> · (−x<sup>3</sup>) → son: (−2) · 5 · (−1) = 10; x: 1 + 3 = 4; y: 2. Javob: 10x<sup>4</sup>y<sup>2</sup>, darajasi 6.', 'Например: −2x · 5y<sup>2</sup> · (−x<sup>3</sup>) → число: (−2) · 5 · (−1) = 10; x: 1 + 3 = 4; y: 2. Ответ: 10x<sup>4</sup>y<sup>2</sup>, степень 6.', 'For example: −2x · 5y<sup>2</sup> · (−x<sup>3</sup>) → number: (−2) · 5 · (−1) = 10; x: 1 + 3 = 4; y: 2. Answer: 10x<sup>4</sup>y<sup>2</sup>, degree 6.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Standart shaklga keltiring: 0,5a · 4ab<sup>2</sup> · b.', 'Приведите к стандартному виду: 0,5a · 4ab<sup>2</sup> · b.', 'Put in standard form: 0.5a · 4ab<sup>2</sup> · b.'), s: L('Son: 0,5 · 4 = 2. a: 1 + 1 = 2. b: 2 + 1 = 3. Javob: <b>2a<sup>2</sup>b<sup>3</sup></b>, koeffitsiyent 2, daraja 5.', 'Число: 0,5 · 4 = 2. a: 1 + 1 = 2. b: 2 + 1 = 3. Ответ: <b>2a<sup>2</sup>b<sup>3</sup></b>, коэффициент 2, степень 5.', 'Number: 0.5 · 4 = 2. a: 1 + 1 = 2. b: 2 + 1 = 3. Answer: <b>2a<sup>2</sup>b<sup>3</sup></b>, coefficient 2, degree 5.') },
      { q: L('Ko‘paytiring: −3x<sup>2</sup>y · 4xy<sup>5</sup>.', 'Умножьте: −3x<sup>2</sup>y · 4xy<sup>5</sup>.', 'Multiply: −3x<sup>2</sup>y · 4xy<sup>5</sup>.'), s: L('(−3) · 4 = −12; x<sup>2+1</sup> = x<sup>3</sup>; y<sup>1+5</sup> = y<sup>6</sup>. Javob: <b>−12x<sup>3</sup>y<sup>6</sup></b>.', '(−3) · 4 = −12; x<sup>2+1</sup> = x<sup>3</sup>; y<sup>1+5</sup> = y<sup>6</sup>. Ответ: <b>−12x<sup>3</sup>y<sup>6</sup></b>.', '(−3) · 4 = −12; x<sup>2+1</sup> = x<sup>3</sup>; y<sup>1+5</sup> = y<sup>6</sup>. Answer: <b>−12x<sup>3</sup>y<sup>6</sup></b>.') },
      { q: L('Darajaga ko‘taring: (−3a<sup>2</sup>b<sup>3</sup>)<sup>3</sup>.', 'Возведите в степень: (−3a<sup>2</sup>b<sup>3</sup>)<sup>3</sup>.', 'Raise to the power: (−3a<sup>2</sup>b<sup>3</sup>)<sup>3</sup>.'), s: L('(−3)<sup>3</sup> = −27; (a<sup>2</sup>)<sup>3</sup> = a<sup>6</sup>; (b<sup>3</sup>)<sup>3</sup> = b<sup>9</sup>. Javob: <b>−27a<sup>6</sup>b<sup>9</sup></b>.', '(−3)<sup>3</sup> = −27; (a<sup>2</sup>)<sup>3</sup> = a<sup>6</sup>; (b<sup>3</sup>)<sup>3</sup> = b<sup>9</sup>. Ответ: <b>−27a<sup>6</sup>b<sup>9</sup></b>.', '(−3)<sup>3</sup> = −27; (a<sup>2</sup>)<sup>3</sup> = a<sup>6</sup>; (b<sup>3</sup>)<sup>3</sup> = b<sup>9</sup>. Answer: <b>−27a<sup>6</sup>b<sup>9</sup></b>.') },
      { q: L('Bo‘ling: 24m<sup>6</sup>n<sup>4</sup> : (−8m<sup>2</sup>n<sup>4</sup>).', 'Разделите: 24m<sup>6</sup>n<sup>4</sup> : (−8m<sup>2</sup>n<sup>4</sup>).', 'Divide: 24m<sup>6</sup>n<sup>4</sup> : (−8m<sup>2</sup>n<sup>4</sup>).'), s: L('24 : (−8) = −3; m<sup>6−2</sup> = m<sup>4</sup>; n<sup>4−4</sup> = n<sup>0</sup> = 1 (n qisqarib ketadi). Javob: <b>−3m<sup>4</sup></b>.', '24 : (−8) = −3; m<sup>6−2</sup> = m<sup>4</sup>; n<sup>4−4</sup> = 1 (n сокращается). Ответ: <b>−3m<sup>4</sup></b>.', '24 : (−8) = −3; m<sup>6−2</sup> = m<sup>4</sup>; n<sup>4−4</sup> = 1 (n cancels). Answer: <b>−3m<sup>4</sup></b>.') },
      { q: L('Kubning qirrasi 2a. Uning hajmi va to‘liq sirti qanday birhad bilan ifodalanadi?', 'Ребро куба 2a. Какими одночленами выражаются его объём и площадь поверхности?', 'A cube has edge 2a. Which monomials give its volume and total surface area?'), s: L('V = (2a)<sup>3</sup> = <b>8a<sup>3</sup></b>. Sirt: 6 ta yoq, har biri (2a)<sup>2</sup> = 4a<sup>2</sup>, jami <b>24a<sup>2</sup></b>.', 'V = (2a)<sup>3</sup> = <b>8a<sup>3</sup></b>. Поверхность: 6 граней по (2a)<sup>2</sup> = 4a<sup>2</sup>, всего <b>24a<sup>2</sup></b>.', 'V = (2a)<sup>3</sup> = <b>8a<sup>3</sup></b>. Surface: 6 faces of (2a)<sup>2</sup> = 4a<sup>2</sup> each, total <b>24a<sup>2</sup></b>.') }
    ] },
    { kind: 'table', h: L('Birhadlarni tahlil qilamiz', 'Разбираем одночлены', 'Analysing monomials'), table: { head: [L('Birhad', 'Одночлен', 'Monomial'), L('Standart shakl', 'Стандартный вид', 'Standard form'), L('Koeffitsiyent', 'Коэффициент', 'Coefficient'), L('Daraja', 'Степень', 'Degree')], rows: [
      ['2x · 3x', '6x<sup>2</sup>', '6', '2'],
      ['−a · b · a', '−a<sup>2</sup>b', '−1', '3'],
      ['5xy · (−2y<sup>2</sup>)', '−10xy<sup>3</sup>', '−10', '4'],
      ['m<sup>2</sup> · 0,1 · n · 10', 'm<sup>2</sup>n', '1', '3'],
      ['(−x<sup>2</sup>)<sup>3</sup>', '−x<sup>6</sup>', '−1', '6'],
      ['−7', '−7', '−7', '0']
    ] }, after: [
      L('Jadvaldan ko‘rinadiki, koeffitsiyent 1 yoki −1 bo‘lsa, u yozilmaydi, faqat ishora qoladi.', 'Из таблицы видно: если коэффициент равен 1 или −1, его не пишут, остаётся только знак.', 'The table shows that when the coefficient is 1 or −1 it is not written; only the sign remains.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Koeffitsiyentlarni qo‘shish.</b> 3a · 2a = 5a<sup>2</sup> emas, 6a<sup>2</sup>. Ko‘paytirishda sonlar ham ko‘paytiriladi.', '<b>Складывать коэффициенты.</b> 3a · 2a = 6a<sup>2</sup>, а не 5a<sup>2</sup>. При умножении числа тоже перемножаются.', '<b>Adding coefficients.</b> 3a · 2a = 6a<sup>2</sup>, not 5a<sup>2</sup>. When multiplying, numbers are multiplied too.'),
      L('<b>Koeffitsiyentni darajaga ko‘tarmaslik.</b> (3x)<sup>2</sup> = 3x<sup>2</sup> — xato; to‘g‘risi 9x<sup>2</sup>.', '<b>Не возвести коэффициент в степень.</b> (3x)<sup>2</sup> = 3x<sup>2</sup> — ошибка; верно 9x<sup>2</sup>.', '<b>Not raising the coefficient.</b> (3x)<sup>2</sup> = 3x<sup>2</sup> is wrong; it is 9x<sup>2</sup>.'),
      L('<b>Darajani noto‘g‘ri hisoblash.</b> 4x<sup>2</sup>y<sup>3</sup> ning darajasi 2 · 3 = 6 emas, 2 + 3 = 5. Koeffitsiyent darajaga ta’sir qilmaydi.', '<b>Неверно найти степень.</b> Степень 4x<sup>2</sup>y<sup>3</sup> — 2 + 3 = 5, а не 6. Коэффициент на степень не влияет.', '<b>Wrong degree.</b> The degree of 4x<sup>2</sup>y<sup>3</sup> is 2 + 3 = 5, not 6. The coefficient does not affect the degree.'),
      L('<b>Yashirin birni unutish.</b> x · x<sup>3</sup> = x<sup>3</sup> emas, x<sup>4</sup>: x = x<sup>1</sup>.', '<b>Забыть скрытую единицу.</b> x · x<sup>3</sup> = x<sup>4</sup>, а не x<sup>3</sup>: x = x<sup>1</sup>.', '<b>Forgetting the hidden 1.</b> x · x<sup>3</sup> = x<sup>4</sup>, not x<sup>3</sup>: x = x<sup>1</sup>.'),
      L('<b>Manfiy ishorani yo‘qotish.</b> (−a)<sup>3</sup> = −a<sup>3</sup>, lekin (−a)<sup>4</sup> = a<sup>4</sup>.', '<b>Потерять минус.</b> (−a)<sup>3</sup> = −a<sup>3</sup>, но (−a)<sup>4</sup> = a<sup>4</sup>.', '<b>Losing the minus.</b> (−a)<sup>3</sup> = −a<sup>3</sup>, but (−a)<sup>4</sup> = a<sup>4</sup>.')
    ] },
    { kind: 'life', h: L('Birhadlar hayotda', 'Одночлены в жизни', 'Monomials in real life'), p: [
      L('Ko‘p fizik formulalar aslida birhaddir. Kinetik energiya E = 0,5mv<sup>2</sup> — koeffitsiyenti 0,5, darajasi 3. Erkin tushishda bosib o‘tilgan yo‘l s = 5t<sup>2</sup> (metr, sekund). Masalan, tosh 3 sekund tushsa, 5 · 9 = 45 metr yo‘l bosadi.', 'Многие физические формулы на самом деле одночлены. Кинетическая энергия E = 0,5mv<sup>2</sup> — коэффициент 0,5, степень 3. Путь при свободном падении s = 5t<sup>2</sup> (метры, секунды). Камень, падающий 3 секунды, пролетит 5 · 9 = 45 метров.', 'Many physics formulas are really monomials. Kinetic energy E = 0.5mv<sup>2</sup> has coefficient 0.5 and degree 3. The distance fallen in free fall is s = 5t<sup>2</sup> (metres, seconds). A stone falling for 3 seconds drops 5 · 9 = 45 metres.'),
      L('Masshtab bilan ishlashda ham birhad yordam beradi: xonaning chizmasini 2 marta kattalashtirsak, uzunliklar 2 marta, yuz 2<sup>2</sup> = 4 marta, hajm esa 2<sup>3</sup> = 8 marta oshadi. Shuning uchun katta tarvuz kichigidan ancha og‘ir: diametri 2 marta katta bo‘lsa, og‘irligi taxminan 8 marta ko‘p.', 'При работе с масштабом тоже помогают одночлены: если увеличить чертёж комнаты в 2 раза, длины вырастут в 2 раза, площадь — в 2<sup>2</sup> = 4 раза, а объём — в 2<sup>3</sup> = 8 раз. Поэтому большой арбуз намного тяжелее маленького: при вдвое большем диаметре он весит примерно в 8 раз больше.', 'Monomials also help with scale: if a room plan is enlarged 2 times, lengths grow 2 times, area grows 2<sup>2</sup> = 4 times and volume 2<sup>3</sup> = 8 times. That is why a big watermelon is so much heavier than a small one: with twice the diameter it weighs about 8 times as much.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«Monom» (birhad) so‘zi yunoncha «monos» — bitta va «nomos» — qism so‘zlaridan olingan.', 'Слово «моном» (одночлен) происходит от греческих «монос» — один и «номос» — часть.', 'The word “monomial” comes from the Greek “monos” (one) and “nomos” (part).'),
      L('Fil sichqondan taxminan 100 marta uzun bo‘lsa, uning hajmi va og‘irligi 100<sup>3</sup> = 1 000 000 marta katta bo‘ladi — shuning uchun filning oyoqlari ustunga o‘xshash yo‘g‘on.', 'Если слон примерно в 100 раз длиннее мыши, его объём и вес больше в 100<sup>3</sup> = 1 000 000 раз — поэтому ноги слона толстые, как колонны.', 'If an elephant is about 100 times longer than a mouse, its volume and weight are 100<sup>3</sup> = 1 000 000 times greater — which is why an elephant’s legs are as thick as pillars.'),
      L('Pifagorchilar 1 dan n gacha toq sonlar yig‘indisi n<sup>2</sup> ekanini bilishgan: 1 + 3 + 5 + 7 = 16 = 4<sup>2</sup>.', 'Пифагорейцы знали, что сумма первых n нечётных чисел равна n<sup>2</sup>: 1 + 3 + 5 + 7 = 16 = 4<sup>2</sup>.', 'The Pythagoreans knew that the sum of the first n odd numbers is n<sup>2</sup>: 1 + 3 + 5 + 7 = 16 = 4<sup>2</sup>.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. Standart shaklga keltiring: −4a<sup>3</sup> · 0,25ab · (−b).', '1. Приведите к стандартному виду: −4a<sup>3</sup> · 0,25ab · (−b).', '1. Put in standard form: −4a<sup>3</sup> · 0.25ab · (−b).'),
      L('2. (2x<sup>2</sup>y)<sup>4</sup> ning koeffitsiyenti va darajasini toping.', '2. Найдите коэффициент и степень (2x<sup>2</sup>y)<sup>4</sup>.', '2. Find the coefficient and degree of (2x<sup>2</sup>y)<sup>4</sup>.'),
      L('3. Qaysi birhadni 3ab<sup>2</sup> ga ko‘paytirsak, 15a<sup>3</sup>b<sup>5</sup> chiqadi?', '3. На какой одночлен нужно умножить 3ab<sup>2</sup>, чтобы получить 15a<sup>3</sup>b<sup>5</sup>?', '3. Which monomial times 3ab<sup>2</sup> gives 15a<sup>3</sup>b<sup>5</sup>?')
    ], after: [
      L('Javoblar: 1) a<sup>4</sup>b<sup>2</sup>; 2) 16x<sup>8</sup>y<sup>4</sup> — koeffitsiyent 16, daraja 12; 3) 15a<sup>3</sup>b<sup>5</sup> : 3ab<sup>2</sup> = 5a<sup>2</sup>b<sup>3</sup>.', 'Ответы: 1) a<sup>4</sup>b<sup>2</sup>; 2) 16x<sup>8</sup>y<sup>4</sup> — коэффициент 16, степень 12; 3) 15a<sup>3</sup>b<sup>5</sup> : 3ab<sup>2</sup> = 5a<sup>2</sup>b<sup>3</sup>.', 'Answers: 1) a<sup>4</sup>b<sup>2</sup>; 2) 16x<sup>8</sup>y<sup>4</sup> — coefficient 16, degree 12; 3) 15a<sup>3</sup>b<sup>5</sup> : 3ab<sup>2</sup> = 5a<sup>2</sup>b<sup>3</sup>.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Birhad — sonlar va harflar darajalarining ko‘paytmasi.', 'Одночлен — произведение чисел и степеней букв.', 'A monomial is a product of numbers and powers of letters.'),
      L('Standart shakl: oldin bitta son (koeffitsiyent), so‘ng har bir harf bir marta.', 'Стандартный вид: сначала одно число (коэффициент), затем каждая буква один раз.', 'Standard form: one number (the coefficient) first, then each letter once.'),
      L('Birhadning darajasi — harflar ko‘rsatkichlari yig‘indisi.', 'Степень одночлена — сумма показателей букв.', 'The degree of a monomial is the sum of the exponents of its letters.'),
      L('Ko‘paytirishda koeffitsiyentlar ko‘paytiriladi, ko‘rsatkichlar qo‘shiladi.', 'При умножении коэффициенты перемножаются, показатели складываются.', 'When multiplying, coefficients multiply and exponents add.'),
      L('Darajaga ko‘tarishda koeffitsiyent ham darajaga ko‘tariladi.', 'При возведении в степень коэффициент тоже возводится в степень.', 'When raising to a power, the coefficient is raised too.'),
      L('Bo‘lishda koeffitsiyentlar bo‘linadi, ko‘rsatkichlar ayiriladi.', 'При делении коэффициенты делятся, показатели вычитаются.', 'When dividing, coefficients divide and exponents subtract.')
    ] }
  ] });

  // ---------- t4. Ko‘phadlar ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Birhadlardan ko‘phadga', 'От одночленов к многочлену', 'From monomials to polynomials'), p: [
      L('Bozordan 3 kg olma (har kilosi x so‘m), 2 kg nok (har kilosi y so‘m) va 5 000 so‘mlik non oldingiz. Jami xarajat: 3x + 2y + 5 000. Bu ifoda uchta birhad yig‘indisidan iborat — u <b>ko‘phad</b> deyiladi. Hayotdagi deyarli har bir hisob-kitob shunday yig‘indilarga olib keladi.', 'Вы купили на базаре 3 кг яблок (x сум за кило), 2 кг груш (y сум за кило) и хлеб за 5 000 сум. Всего: 3x + 2y + 5 000. Это выражение — сумма трёх одночленов, оно называется <b>многочленом</b>. Почти любой подсчёт в жизни приводит к таким суммам.', 'At the market you bought 3 kg of apples (x sum per kilo), 2 kg of pears (y sum per kilo) and bread for 5 000 sum. Total: 3x + 2y + 5 000. This expression is a sum of three monomials, and it is called a <b>polynomial</b>. Almost every real-life calculation leads to sums like this.'),
      L('Bu mavzuda ko‘phadni standart shaklga keltirishni, o‘xshash hadlarni ixchamlashni va ko‘phadlarni qo‘shish-ayirishni o‘rganamiz. Eng muhim ko‘nikma — qavslarni to‘g‘ri ochish va ishoralarda adashmaslik.', 'В этой теме мы научимся приводить многочлен к стандартному виду, приводить подобные члены, складывать и вычитать многочлены. Самый важный навык — правильно раскрывать скобки и не путаться в знаках.', 'In this topic we learn to put a polynomial in standard form, collect like terms, and add and subtract polynomials. The key skill is opening brackets correctly without mixing up the signs.')
    ] },
    { kind: 'def', h: L('Ko‘phad va uning hadlari', 'Многочлен и его члены', 'A polynomial and its terms'), p: [
      L('<b>Ko‘phad</b> — birhadlar yig‘indisi. Unga kiruvchi birhadlar ko‘phadning <b>hadlari</b> deyiladi. Masalan, 4x<sup>2</sup> − 3x + 7 ko‘phadining hadlari: 4x<sup>2</sup>, −3x va 7. Ayirishni manfiy hadni qo‘shish deb tushunamiz: −3x — bu «+ (−3x)». Ikki hadli ko‘phad <b>ikkihad</b>, uch hadli — <b>uchhad</b> deyiladi.', '<b>Многочлен</b> — сумма одночленов. Входящие в него одночлены называют <b>членами</b> многочлена. Например, члены многочлена 4x<sup>2</sup> − 3x + 7: 4x<sup>2</sup>, −3x и 7. Вычитание понимаем как прибавление отрицательного члена: −3x — это «+ (−3x)». Многочлен из двух членов — <b>двучлен</b>, из трёх — <b>трёхчлен</b>.', 'A <b>polynomial</b> is a sum of monomials. The monomials in it are its <b>terms</b>. For example, the terms of 4x<sup>2</sup> − 3x + 7 are 4x<sup>2</sup>, −3x and 7. We treat subtraction as adding a negative term: −3x is “+ (−3x)”. A polynomial with two terms is a <b>binomial</b>, with three — a <b>trinomial</b>.'),
      L('Harf qismi bir xil hadlar <b>o‘xshash hadlar</b> deyiladi: 5ab va −2ab o‘xshash, lekin 5a<sup>2</sup>b va 5ab<sup>2</sup> o‘xshash emas. O‘xshash hadlarni qo‘shish <b>ixchamlash</b> deyiladi: koeffitsiyentlar qo‘shiladi, harf qismi o‘zgarmaydi. Barcha hadlari standart shakldagi birhad bo‘lib, ular orasida o‘xshashlari bo‘lmagan ko‘phad <b>standart shakldagi ko‘phad</b> deyiladi. Hadlarining eng katta darajasi — <b>ko‘phadning darajasi</b>.', 'Члены с одинаковой буквенной частью называются <b>подобными</b>: 5ab и −2ab подобны, а 5a<sup>2</sup>b и 5ab<sup>2</sup> — нет. Сложение подобных называют <b>приведением подобных</b>: коэффициенты складываются, буквенная часть не меняется. Многочлен, все члены которого — одночлены стандартного вида и среди них нет подобных, называется <b>многочленом стандартного вида</b>. Наибольшая из степеней его членов — <b>степень многочлена</b>.', 'Terms with the same letter part are <b>like terms</b>: 5ab and −2ab are alike, but 5a<sup>2</sup>b and 5ab<sup>2</sup> are not. Adding like terms is called <b>collecting like terms</b>: add the coefficients and keep the letter part. A polynomial whose terms are monomials in standard form with no like terms among them is a <b>polynomial in standard form</b>. The highest degree of its terms is the <b>degree of the polynomial</b>.')
    ] },
    { kind: 'history', h: L('Umar Xayyom va tenglamalar', 'Омар Хайям и уравнения', 'Omar Khayyam and equations'), p: [
      L('Ko‘pchilik <b>Umar Xayyomni</b> (1048–1131) ruboiylari orqali taniydi, lekin u buyuk matematik va astronom ham bo‘lgan. Samarqandda yozgan algebra risolasida u uchinchi darajali ko‘phadli tenglamalarni turlarga ajratgan — 25 dan ortiq tur — va ularni geometrik usulda, aylana va parabolalar kesishishi yordamida yechgan. U ko‘phadning darajasi qanchalik muhim ekanini birinchilardan bo‘lib aniq ko‘rsatgan.', 'Многие знают <b>Омара Хайяма</b> (1048–1131) по его рубаи, но он был и великим математиком и астрономом. В трактате по алгебре, написанном в Самарканде, он разделил уравнения третьей степени на типы — более 25 — и решал их геометрически, с помощью пересечения окружностей и парабол. Он одним из первых ясно показал, как важна степень многочлена.', 'Many people know <b>Omar Khayyam</b> (1048–1131) for his rubaiyat, but he was also a great mathematician and astronomer. In an algebra treatise written in Samarkand, he sorted cubic equations into more than 25 types and solved them geometrically, using intersecting circles and parabolas. He was among the first to show clearly how important the degree of a polynomial is.'),
      L('Xayyom shuningdek Jaloliy taqvimini tuzishda qatnashgan: bu taqvim yilni 365,2424 kun deb hisoblagan, bugungi Grigoriy taqvimidan ham aniqroq bo‘lgan.', 'Хайям также участвовал в создании календаря Джалали: в нём год считался равным 365,2424 дня — точнее даже современного григорианского календаря.', 'Khayyam also helped create the Jalali calendar, which took the year to be 365.2424 days — more accurate even than today’s Gregorian calendar.')
    ] },
    { kind: 'rule', h: L('Qavslarni ochish va qo‘shish-ayirish', 'Раскрытие скобок, сложение и вычитание', 'Opening brackets, adding and subtracting'), p: [
      L('<b>Qo‘shish.</b> Agar qavs oldida «+» turgan bo‘lsa, qavsni tashlab yuboramiz, ichidagi ishoralar saqlanadi: (3x<sup>2</sup> + 2x) + (x<sup>2</sup> − 4x) = 3x<sup>2</sup> + 2x + x<sup>2</sup> − 4x = 4x<sup>2</sup> − 2x.', '<b>Сложение.</b> Если перед скобкой стоит «+», скобки опускаем, знаки внутри сохраняются: (3x<sup>2</sup> + 2x) + (x<sup>2</sup> − 4x) = 3x<sup>2</sup> + 2x + x<sup>2</sup> − 4x = 4x<sup>2</sup> − 2x.', '<b>Adding.</b> If there is “+” in front of a bracket, drop the bracket and keep the signs inside: (3x<sup>2</sup> + 2x) + (x<sup>2</sup> − 4x) = 3x<sup>2</sup> + 2x + x<sup>2</sup> − 4x = 4x<sup>2</sup> − 2x.'),
      L('<b>Ayirish.</b> Agar qavs oldida «−» turgan bo‘lsa, qavs ichidagi <i>har bir</i> hadning ishorasi qarama-qarshisiga o‘zgaradi: (3x<sup>2</sup> + 2x) − (x<sup>2</sup> − 4x) = 3x<sup>2</sup> + 2x − x<sup>2</sup> + 4x = 2x<sup>2</sup> + 6x. Sababi: ayirish — qarama-qarshi sonni qo‘shish, −(x<sup>2</sup> − 4x) = (−1) · (x<sup>2</sup> − 4x).', '<b>Вычитание.</b> Если перед скобкой стоит «−», знак <i>каждого</i> члена в скобках меняется на противоположный: (3x<sup>2</sup> + 2x) − (x<sup>2</sup> − 4x) = 3x<sup>2</sup> + 2x − x<sup>2</sup> + 4x = 2x<sup>2</sup> + 6x. Причина: вычитание — это прибавление противоположного, −(x<sup>2</sup> − 4x) = (−1) · (x<sup>2</sup> − 4x).', '<b>Subtracting.</b> If there is “−” in front of a bracket, the sign of <i>every</i> term inside flips: (3x<sup>2</sup> + 2x) − (x<sup>2</sup> − 4x) = 3x<sup>2</sup> + 2x − x<sup>2</sup> + 4x = 2x<sup>2</sup> + 6x. Reason: subtracting means adding the opposite, −(x<sup>2</sup> − 4x) = (−1) · (x<sup>2</sup> − 4x).'),
      L('Ikki ko‘phad yig‘indisi va ayirmasi yana ko‘phad bo‘ladi. Javobni doim standart shaklda, daraja kamayishi tartibida yozish odat: avval x<sup>2</sup>, keyin x, oxirida son.', 'Сумма и разность двух многочленов — снова многочлен. Ответ принято записывать в стандартном виде, по убыванию степеней: сначала x<sup>2</sup>, потом x, в конце число.', 'The sum and difference of two polynomials is again a polynomial. It is customary to write the answer in standard form with descending powers: x<sup>2</sup> first, then x, then the number.')
    ] },
    { kind: 'steps', h: L('Algoritm', 'Алгоритм', 'Algorithm'), list: [
      L('1. Qavslarni oching: «+» oldida — ishoralar saqlanadi, «−» oldida — hammasi o‘zgaradi.', '1. Раскройте скобки: перед «+» — знаки сохраняются, перед «−» — все меняются.', '1. Open the brackets: after “+” the signs stay, after “−” they all flip.'),
      L('2. O‘xshash hadlarni bir xil rangli qalam yoki chiziq bilan belgilang.', '2. Отметьте подобные члены одинаковым цветом или подчёркиванием.', '2. Mark like terms with the same colour or underlining.'),
      L('3. Har bir guruhning koeffitsiyentlarini qo‘shing.', '3. Сложите коэффициенты каждой группы.', '3. Add the coefficients in each group.'),
      L('4. Natijani daraja kamayishi tartibida yozing; nolga teng hadlarni tashlab yuboring.', '4. Запишите результат по убыванию степеней; нулевые члены отбросьте.', '4. Write the result in descending powers; drop terms that become zero.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Ixchamlang: 5ab − 2ab + ab − 7.', 'Приведите подобные: 5ab − 2ab + ab − 7.', 'Collect like terms: 5ab − 2ab + ab − 7.'), s: L('ab li hadlar: 5 − 2 + 1 = 4. Son o‘xshash hadi yo‘q. Javob: <b>4ab − 7</b>.', 'Члены с ab: 5 − 2 + 1 = 4. У числа подобных нет. Ответ: <b>4ab − 7</b>.', 'Terms in ab: 5 − 2 + 1 = 4. The number has no like term. Answer: <b>4ab − 7</b>.') },
      { q: L('Standart shaklga keltiring: 3x<sup>2</sup> − 5x + 2 − x<sup>2</sup> + 8x − 6 va darajasini toping.', 'Приведите к стандартному виду: 3x<sup>2</sup> − 5x + 2 − x<sup>2</sup> + 8x − 6 и найдите степень.', 'Put in standard form: 3x<sup>2</sup> − 5x + 2 − x<sup>2</sup> + 8x − 6, and give its degree.'), s: L('x<sup>2</sup>: 3 − 1 = 2; x: −5 + 8 = 3; son: 2 − 6 = −4. Javob: <b>2x<sup>2</sup> + 3x − 4</b>, darajasi 2.', 'x<sup>2</sup>: 3 − 1 = 2; x: −5 + 8 = 3; число: 2 − 6 = −4. Ответ: <b>2x<sup>2</sup> + 3x − 4</b>, степень 2.', 'x<sup>2</sup>: 3 − 1 = 2; x: −5 + 8 = 3; number: 2 − 6 = −4. Answer: <b>2x<sup>2</sup> + 3x − 4</b>, degree 2.') },
      { q: L('Ayiring: (4a<sup>2</sup> − 3ab + b<sup>2</sup>) − (a<sup>2</sup> − 5ab − 2b<sup>2</sup>).', 'Вычтите: (4a<sup>2</sup> − 3ab + b<sup>2</sup>) − (a<sup>2</sup> − 5ab − 2b<sup>2</sup>).', 'Subtract: (4a<sup>2</sup> − 3ab + b<sup>2</sup>) − (a<sup>2</sup> − 5ab − 2b<sup>2</sup>).'), s: L('Qavsni ochamiz: 4a<sup>2</sup> − 3ab + b<sup>2</sup> − a<sup>2</sup> + 5ab + 2b<sup>2</sup>. Ixchamlaymiz: <b>3a<sup>2</sup> + 2ab + 3b<sup>2</sup></b>.', 'Раскрываем скобки: 4a<sup>2</sup> − 3ab + b<sup>2</sup> − a<sup>2</sup> + 5ab + 2b<sup>2</sup>. Приводим: <b>3a<sup>2</sup> + 2ab + 3b<sup>2</sup></b>.', 'Open the brackets: 4a<sup>2</sup> − 3ab + b<sup>2</sup> − a<sup>2</sup> + 5ab + 2b<sup>2</sup>. Collect: <b>3a<sup>2</sup> + 2ab + 3b<sup>2</sup></b>.') },
      { q: L('Isbotlang: ketma-ket uchta natural sonning yig‘indisi 3 ga bo‘linadi.', 'Докажите: сумма трёх последовательных натуральных чисел делится на 3.', 'Prove that the sum of three consecutive natural numbers is divisible by 3.'), s: L('Sonlar: n, n + 1, n + 2. Yig‘indi: n + (n + 1) + (n + 2) = 3n + 3 = <b>3(n + 1)</b> — 3 ga karrali. Ko‘phadlar bilan bunday isbotlar juda oson!', 'Числа: n, n + 1, n + 2. Сумма: n + (n + 1) + (n + 2) = 3n + 3 = <b>3(n + 1)</b> — кратна 3. С многочленами такие доказательства очень просты!', 'The numbers are n, n + 1, n + 2. Sum: n + (n + 1) + (n + 2) = 3n + 3 = <b>3(n + 1)</b>, a multiple of 3. Polynomials make proofs like this easy!') }
    ] },
    { kind: 'table', h: L('O‘xshashmi yoki yo‘q?', 'Подобные или нет?', 'Alike or not?'), table: { head: [L('Hadlar', 'Члены', 'Terms'), L('O‘xshashmi?', 'Подобные?', 'Alike?'), L('Sabab', 'Причина', 'Reason')], rows: [
      ['3x<sup>2</sup>y; −7x<sup>2</sup>y', L('ha', 'да', 'yes'), L('harf qismi bir xil', 'одинаковая буквенная часть', 'same letter part')],
      ['2ab; 5ba', L('ha', 'да', 'yes'), L('ab = ba', 'ab = ba', 'ab = ba')],
      ['4x<sup>2</sup>; 4x', L('yo‘q', 'нет', 'no'), L('darajalar turli', 'разные степени', 'different powers')],
      ['a<sup>2</sup>b; ab<sup>2</sup>', L('yo‘q', 'нет', 'no'), L('ko‘rsatkichlar boshqa harflarda', 'показатели у разных букв', 'powers on different letters')],
      ['6; −1,5', L('ha', 'да', 'yes'), L('ikkalasi ham son', 'оба числа', 'both are numbers')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Faqat birinchi hadning ishorasini o‘zgartirish.</b> −(x<sup>2</sup> − 4x) = −x<sup>2</sup> − 4x — xato! To‘g‘risi −x<sup>2</sup> + 4x.', '<b>Менять знак только первого члена.</b> −(x<sup>2</sup> − 4x) = −x<sup>2</sup> − 4x — ошибка! Верно −x<sup>2</sup> + 4x.', '<b>Flipping only the first sign.</b> −(x<sup>2</sup> − 4x) = −x<sup>2</sup> − 4x is wrong! It is −x<sup>2</sup> + 4x.'),
      L('<b>O‘xshash bo‘lmagan hadlarni qo‘shish.</b> 3x<sup>2</sup> + 2x = 5x<sup>3</sup> — mutlaqo xato; bu ifoda soddalashmaydi.', '<b>Складывать неподобные члены.</b> 3x<sup>2</sup> + 2x = 5x<sup>3</sup> — грубая ошибка; это выражение не упрощается.', '<b>Adding unlike terms.</b> 3x<sup>2</sup> + 2x = 5x<sup>3</sup> is completely wrong; this expression cannot be simplified.'),
      L('<b>Ixchamlashda daraja qo‘shish.</b> 2a + 3a = 5a<sup>2</sup> emas, 5a. Qo‘shishda harf qismi o‘zgarmaydi.', '<b>Складывать показатели при приведении.</b> 2a + 3a = 5a, а не 5a<sup>2</sup>. При сложении буквенная часть не меняется.', '<b>Adding exponents when collecting.</b> 2a + 3a = 5a, not 5a<sup>2</sup>. In addition the letter part stays the same.'),
      L('<b>Yolg‘iz harfning koeffitsiyentini unutish.</b> 4x − x = 4 emas, 3x.', '<b>Забыть коэффициент 1.</b> 4x − x = 3x, а не 4.', '<b>Forgetting the coefficient 1.</b> 4x − x = 3x, not 4.')
    ] },
    { kind: 'life', h: L('Ko‘phadlar hayotda', 'Многочлены в жизни', 'Polynomials in real life'), p: [
      L('Ota-onangiz oylik byudjetni hisoblaganda ko‘phad tuzadi: ijara + 30 · (kunlik oziq-ovqat) + 4 · (haftalik yo‘l haqi) + kommunal to‘lov. Agar kunlik xarajat x, haftalik y bo‘lsa, byudjet B = 30x + 4y + c ko‘rinishida bo‘ladi.', 'Родители, считая месячный бюджет, составляют многочлен: аренда + 30 · (еда в день) + 4 · (проезд в неделю) + коммунальные платежи. Если дневной расход x, недельный y, то бюджет B = 30x + 4y + c.', 'When your parents work out the monthly budget, they build a polynomial: rent + 30 · (food per day) + 4 · (travel per week) + utilities. If the daily cost is x and the weekly cost y, the budget is B = 30x + 4y + c.'),
      L('Ikki do‘kon narxlarini solishtirish uchun ikki ko‘phadni ayiramiz: (3x + 2y + 5 000) − (3x + 2y + 4 000) = 1 000 — farq faqat nonda. Kompyuter grafikasida egri chiziqlar va shrift harflarining konturlari ko‘phadlar yordamida chiziladi (Bezye egri chiziqlari).', 'Чтобы сравнить цены двух магазинов, вычитаем два многочлена: (3x + 2y + 5 000) − (3x + 2y + 4 000) = 1 000 — разница только в хлебе. В компьютерной графике кривые и контуры букв шрифтов рисуются с помощью многочленов (кривые Безье).', 'To compare two shops we subtract two polynomials: (3x + 2y + 5 000) − (3x + 2y + 4 000) = 1 000 — the only difference is the bread. In computer graphics, curves and the outlines of font letters are drawn with polynomials (Bézier curves).'),
      L('Qurilishda ham ko‘phad kerak: to‘g‘ri to‘rtburchak shaklidagi hovlini o‘rab olish uchun panjara uzunligi 2a + 2b, lekin darvoza uchun d metr qoldirilsa, kerakli panjara 2a + 2b − d bo‘ladi. Agar hovlining bir tomoni devorga tegib tursa, yana bitta had kamayadi: a + 2b − d. Har bir yangi shart ko‘phadga yangi had qo‘shadi yoki undan olib tashlaydi — shuning uchun hadlarni to‘g‘ri yig‘ish va ixchamlash amaliy ishda juda muhim.', 'В строительстве тоже нужен многочлен: чтобы огородить прямоугольный двор, нужна ограда длиной 2a + 2b, но если оставить d метров под ворота, понадобится 2a + 2b − d. Если одна сторона двора примыкает к стене, уходит ещё один член: a + 2b − d. Каждое новое условие добавляет член в многочлен или убирает его — поэтому умение правильно собирать и приводить члены очень важно на практике.', 'Building needs polynomials too: fencing a rectangular yard takes 2a + 2b of fence, but if d metres are left for a gate, you need 2a + 2b − d. If one side of the yard is against a wall, another term goes: a + 2b − d. Each new condition adds a term to the polynomial or removes one — which is why collecting and simplifying terms correctly matters so much in practice.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Har bir son o‘nlik yozuvda ko‘phad: 2 573 = 2 · 10<sup>3</sup> + 5 · 10<sup>2</sup> + 7 · 10 + 3.', 'Каждое число в десятичной записи — многочлен: 2 573 = 2 · 10<sup>3</sup> + 5 · 10<sup>2</sup> + 7 · 10 + 3.', 'Every number in decimal notation is a polynomial: 2 573 = 2 · 10<sup>3</sup> + 5 · 10<sup>2</sup> + 7 · 10 + 3.'),
      L('Shuning uchun raqamlari yig‘indisi 3 ga bo‘linadigan son 3 ga bo‘linadi — buni ko‘phad yordamida isbotlash mumkin.', 'Поэтому число делится на 3, если сумма его цифр делится на 3 — это доказывается с помощью многочленов.', 'That is why a number is divisible by 3 when its digit sum is — a fact proved with polynomials.'),
      L('QR-kodlardagi xatoni tuzatish tizimi (Rid–Solomon kodlari) ko‘phadlar ustida amallarga asoslangan: kod 30% gacha shikastlansa ham o‘qiladi.', 'Система исправления ошибок в QR-кодах (коды Рида–Соломона) основана на действиях с многочленами: код читается, даже если повреждено до 30%.', 'Error correction in QR codes (Reed–Solomon codes) is based on polynomial arithmetic: a code can still be read with up to 30% damaged.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. Ixchamlang: 7y − 3y<sup>2</sup> + 2y + 5y<sup>2</sup> − 9y.', '1. Приведите подобные: 7y − 3y<sup>2</sup> + 2y + 5y<sup>2</sup> − 9y.', '1. Collect like terms: 7y − 3y<sup>2</sup> + 2y + 5y<sup>2</sup> − 9y.'),
      L('2. (2x<sup>2</sup> − x + 1) − (x<sup>2</sup> + x − 3) ni toping.', '2. Найдите (2x<sup>2</sup> − x + 1) − (x<sup>2</sup> + x − 3).', '2. Find (2x<sup>2</sup> − x + 1) − (x<sup>2</sup> + x − 3).'),
      L('3. Ikki xonali son va uning raqamlarini almashtirib hosil qilingan son ayirmasi 9 ga bo‘linishini isbotlang.', '3. Докажите, что разность двузначного числа и числа, записанного теми же цифрами в обратном порядке, делится на 9.', '3. Prove that a two-digit number minus its reverse is divisible by 9.')
    ], after: [
      L('Javoblar: 1) 2y<sup>2</sup>; 2) x<sup>2</sup> − 2x + 4; 3) (10a + b) − (10b + a) = 9a − 9b = 9(a − b).', 'Ответы: 1) 2y<sup>2</sup>; 2) x<sup>2</sup> − 2x + 4; 3) (10a + b) − (10b + a) = 9a − 9b = 9(a − b).', 'Answers: 1) 2y<sup>2</sup>; 2) x<sup>2</sup> − 2x + 4; 3) (10a + b) − (10b + a) = 9a − 9b = 9(a − b).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘phad — birhadlar yig‘indisi; birhadlar uning hadlari.', 'Многочлен — сумма одночленов; одночлены — его члены.', 'A polynomial is a sum of monomials, which are its terms.'),
      L('O‘xshash hadlarning harf qismi bir xil; ularni ixchamlashda koeffitsiyentlar qo‘shiladi.', 'У подобных членов одинаковая буквенная часть; при приведении коэффициенты складываются.', 'Like terms have the same letter part; collecting them adds the coefficients.'),
      L('Ko‘phad darajasi — hadlari darajalarining eng kattasi.', 'Степень многочлена — наибольшая из степеней его членов.', 'The degree of a polynomial is the highest degree of its terms.'),
      L('«+» oldidagi qavs ishoralarni saqlaydi, «−» oldidagi qavs hammasini o‘zgartiradi.', 'Скобка после «+» сохраняет знаки, после «−» — меняет все.', 'A bracket after “+” keeps the signs; after “−” it flips them all.'),
      L('Ko‘phadlar yig‘indisi va ayirmasi yana ko‘phad bo‘ladi.', 'Сумма и разность многочленов — снова многочлен.', 'The sum and difference of polynomials is again a polynomial.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-2';

  // ---------- t5. Ko‘phadlarni ko‘paytirish va bo‘lish ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Bog‘ni kengaytiramiz', 'Расширяем сад', 'Making the garden bigger'), p: [
      L('Maktab bog‘i kvadrat shaklida, tomoni x metr. Uni bir tomondan 3 metr uzaytirib, ikkinchi tomondan 2 metr qisqartirishmoqchi. Yangi bog‘ning yuzi qancha bo‘ladi? Tomonlar (x + 3) va (x − 2), yuz esa ularning ko‘paytmasi: (x + 3)(x − 2). Bu ikki ko‘phadning ko‘paytmasi. Uni qavslarsiz, oddiy ko‘phad ko‘rinishida yozishni o‘rgansak, x ning istalgan qiymatida yuzni tez hisoblay olamiz.', 'Школьный сад квадратный, со стороной x метров. Его хотят удлинить с одной стороны на 3 метра, а с другой укоротить на 2 метра. Какой будет площадь нового сада? Стороны (x + 3) и (x − 2), площадь — их произведение: (x + 3)(x − 2). Это произведение двух многочленов. Научившись записывать его без скобок, в виде обычного многочлена, мы быстро найдём площадь при любом x.', 'The school garden is a square with side x metres. They want to make it 3 metres longer on one side and 2 metres shorter on the other. What will the new area be? The sides are (x + 3) and (x − 2), and the area is their product: (x + 3)(x − 2). This is a product of two polynomials. Once we learn to write it without brackets as an ordinary polynomial, we can quickly find the area for any x.'),
      L('Bu mavzuda birhadni ko‘phadga, ko‘phadni ko‘phadga ko‘paytirishni va ko‘phadni birhadga bo‘lishni o‘rganamiz. Barcha qoidalar bitta asosiy qonundan — <b>taqsimot qonunidan</b> kelib chiqadi: a(b + c) = ab + ac.', 'В этой теме мы научимся умножать одночлен на многочлен, многочлен на многочлен и делить многочлен на одночлен. Все правила вытекают из одного главного закона — <b>распределительного</b>: a(b + c) = ab + ac.', 'In this topic we learn to multiply a monomial by a polynomial, a polynomial by a polynomial, and to divide a polynomial by a monomial. All the rules come from one main law — the <b>distributive law</b>: a(b + c) = ab + ac.')
    ] },
    { kind: 'def', h: L('Taqsimot qonuni va uning rasmi', 'Распределительный закон и его картинка', 'The distributive law and its picture'), p: [
      L('<b>Birhadni ko‘phadga ko‘paytirish:</b> birhadni ko‘phadning har bir hadiga ko‘paytirib, natijalarni qo‘shamiz: 3x(2x<sup>2</sup> − 5x + 1) = 6x<sup>3</sup> − 15x<sup>2</sup> + 3x.', '<b>Умножение одночлена на многочлен:</b> умножаем одночлен на каждый член многочлена и складываем результаты: 3x(2x<sup>2</sup> − 5x + 1) = 6x<sup>3</sup> − 15x<sup>2</sup> + 3x.', '<b>Monomial times polynomial:</b> multiply the monomial by each term of the polynomial and add the results: 3x(2x<sup>2</sup> − 5x + 1) = 6x<sup>3</sup> − 15x<sup>2</sup> + 3x.'),
      L('Geometrik rasmda: eni a, bo‘yi (b + c) bo‘lgan to‘g‘ri to‘rtburchakni ikki bo‘lakka — a × b va a × c bo‘laklariga ajrating. Butun yuz a(b + c), bo‘laklar yuzlari yig‘indisi ab + ac. Ular teng bo‘lishi aniq.', 'На картинке: прямоугольник шириной a и длиной (b + c) разрежем на две части — a × b и a × c. Вся площадь a(b + c), сумма площадей частей ab + ac. Они, конечно, равны.', 'As a picture: take a rectangle of width a and length (b + c) and cut it into two pieces, a × b and a × c. The whole area is a(b + c), the pieces add up to ab + ac. Clearly they are equal.'),
      L('<b>Ko‘phadni ko‘phadga ko‘paytirish:</b> birinchi ko‘phadning har bir hadini ikkinchisining har bir hadiga ko‘paytirib, natijalarni qo‘shamiz: (a + b)(c + d) = ac + ad + bc + bd. Rasmda: tomonlari (a + b) va (c + d) bo‘lgan to‘g‘ri to‘rtburchak 4 ta kichik to‘rtburchakka bo‘linadi. Agar ko‘phadlarda m va n ta had bo‘lsa, ixchamlashgacha m · n ta had chiqadi.', '<b>Умножение многочлена на многочлен:</b> каждый член первого умножаем на каждый член второго и складываем: (a + b)(c + d) = ac + ad + bc + bd. На картинке: прямоугольник со сторонами (a + b) и (c + d) делится на 4 маленьких прямоугольника. Если в многочленах m и n членов, до приведения получится m · n членов.', '<b>Polynomial times polynomial:</b> multiply each term of the first by each term of the second and add: (a + b)(c + d) = ac + ad + bc + bd. As a picture: a rectangle with sides (a + b) and (c + d) splits into 4 small rectangles. If the polynomials have m and n terms, you get m · n terms before collecting.'),
      L('<b>Ko‘phadni birhadga bo‘lish:</b> har bir hadni shu birhadga bo‘lamiz: (6x<sup>3</sup> − 4x<sup>2</sup>) : 2x = 3x<sup>2</sup> − 2x.', '<b>Деление многочлена на одночлен:</b> делим каждый член на этот одночлен: (6x<sup>3</sup> − 4x<sup>2</sup>) : 2x = 3x<sup>2</sup> − 2x.', '<b>Polynomial divided by monomial:</b> divide each term by the monomial: (6x<sup>3</sup> − 4x<sup>2</sup>) : 2x = 3x<sup>2</sup> − 2x.')
    ] },
    { kind: 'history', h: L('Ko‘paytirishning «panjara» usuli', 'Умножение «решёткой»', 'Lattice multiplication'), p: [
      L('O‘rta asrlarda Sharq va Yevropada ko‘p xonali sonlarni «panjara» (to‘r) usulida ko‘paytirishgan: sonlarning raqamlari jadval ustuni va satriga yozilib, har bir katakka raqamlar ko‘paytmasi qo‘yilgan, so‘ng diagonallar bo‘yicha qo‘shilgan. Bu aslida ko‘phadlarni ko‘paytirishning o‘zi, chunki 23 = 2 · 10 + 3 va 45 = 4 · 10 + 5 ko‘phadlardir.', 'В Средние века на Востоке и в Европе многозначные числа умножали «решёткой»: цифры записывали по строкам и столбцам таблицы, в каждую клетку ставили произведение цифр, а затем складывали по диагоналям. По сути это умножение многочленов, ведь 23 = 2 · 10 + 3 и 45 = 4 · 10 + 5 — многочлены.', 'In the Middle Ages, in the East and in Europe, long numbers were multiplied with a “lattice”: the digits were written along the rows and columns of a grid, each cell got the product of two digits, and the cells were added along diagonals. This is really polynomial multiplication, since 23 = 2 · 10 + 3 and 45 = 4 · 10 + 5 are polynomials.'),
      L('Al-Xorazmiy o‘z kitobida (x + 10)(x + 10) kabi ko‘paytmalarni so‘z bilan tushuntirgan va har bir hadni har biriga ko‘paytirish kerakligini geometrik kvadratlar orqali ko‘rsatgan. Keyinchalik XV asrda Samarqanddagi Ulug‘bek maktabi olimi <b>G‘iyosiddin Koshiy</b> «Arifmetika kaliti» kitobida ko‘paytirishning bir necha usulini, jumladan panjara usulini batafsil bayon qilgan.', 'Аль-Хорезми в своей книге словами объяснял произведения вида (x + 10)(x + 10) и с помощью геометрических квадратов показывал, что каждый член нужно умножать на каждый. Позже, в XV веке, учёный школы Улугбека в Самарканде <b>Гиясиддин Каши</b> в книге «Ключ арифметики» подробно описал несколько способов умножения, включая решётку.', 'Al-Khwarizmi explained products such as (x + 10)(x + 10) in words and used geometric squares to show that every term must be multiplied by every term. Later, in the 15th century, <b>Jamshid al-Kashi</b> of Ulugh Beg’s school in Samarkand described several methods of multiplication, including the lattice, in his book “The Key to Arithmetic”.')
    ] },
    { kind: 'rule', h: L('Ishoralar va ixchamlash', 'Знаки и приведение', 'Signs and collecting'), p: [
      L('Har bir ko‘paytirishda ishoralar qoidasi ishlaydi: «+» · «+» = «+», «−» · «−» = «+», «+» · «−» = «−». Shuning uchun (x − 3)(x − 4) da oxirgi had (−3) · (−4) = +12.', 'При каждом умножении работает правило знаков: «+» · «+» = «+», «−» · «−» = «+», «+» · «−» = «−». Поэтому в (x − 3)(x − 4) последний член (−3) · (−4) = +12.', 'Every product follows the sign rule: “+” · “+” = “+”, “−” · “−” = “+”, “+” · “−” = “−”. So in (x − 3)(x − 4) the last term is (−3) · (−4) = +12.'),
      L('Foydali qisqa formula: (x + a)(x + b) = x<sup>2</sup> + (a + b)x + ab. O‘rtadagi koeffitsiyent — sonlar yig‘indisi, oxirgi had — ularning ko‘paytmasi. Masalan, (x + 3)(x − 2) = x<sup>2</sup> + x − 6, chunki 3 + (−2) = 1, 3 · (−2) = −6.', 'Полезная короткая формула: (x + a)(x + b) = x<sup>2</sup> + (a + b)x + ab. Средний коэффициент — сумма чисел, последний член — их произведение. Например, (x + 3)(x − 2) = x<sup>2</sup> + x − 6, так как 3 + (−2) = 1, 3 · (−2) = −6.', 'A useful shortcut: (x + a)(x + b) = x<sup>2</sup> + (a + b)x + ab. The middle coefficient is the sum of the numbers and the last term their product. E.g. (x + 3)(x − 2) = x<sup>2</sup> + x − 6, because 3 + (−2) = 1 and 3 · (−2) = −6.'),
      L('Ko‘paytirgandan keyin albatta o‘xshash hadlarni ixchamlang va natijani tekshiring: x = 1 ni ikkala ifodaga qo‘ying — qiymatlar teng chiqishi kerak.', 'После умножения обязательно приведите подобные и проверьте результат: подставьте x = 1 в оба выражения — значения должны совпасть.', 'After multiplying, always collect like terms and check the result: put x = 1 into both expressions — the values must match.')
    ] },
    { kind: 'steps', h: L('Ko‘phadni ko‘phadga ko‘paytirish bosqichlari', 'Шаги умножения многочленов', 'Steps for multiplying polynomials'), list: [
      L('1. Birinchi ko‘phadning birinchi hadini olib, ikkinchi ko‘phadning har bir hadiga ko‘paytiring.', '1. Возьмите первый член первого многочлена и умножьте на каждый член второго.', '1. Take the first term of the first polynomial and multiply it by each term of the second.'),
      L('2. Xuddi shuni birinchi ko‘phadning qolgan hadlari bilan takrorlang.', '2. Повторите то же с остальными членами первого многочлена.', '2. Repeat with the remaining terms of the first polynomial.'),
      L('3. Hadlar sonini sanang: m · n ta bo‘lishi kerak — hech biri tushib qolmasin.', '3. Посчитайте члены: их должно быть m · n — ни один не потерян.', '3. Count the terms: there should be m · n — none missing.'),
      L('4. O‘xshash hadlarni ixchamlab, daraja kamayishi tartibida yozing.', '4. Приведите подобные и запишите по убыванию степеней.', '4. Collect like terms and write in descending powers.'),
      L('5. Biror son qo‘yib tekshiring.', '5. Проверьте подстановкой числа.', '5. Check by substituting a number.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Ko‘paytiring: −2a(3a<sup>2</sup> − a + 4).', 'Умножьте: −2a(3a<sup>2</sup> − a + 4).', 'Multiply: −2a(3a<sup>2</sup> − a + 4).'), s: L('−2a · 3a<sup>2</sup> = −6a<sup>3</sup>; −2a · (−a) = +2a<sup>2</sup>; −2a · 4 = −8a. Javob: <b>−6a<sup>3</sup> + 2a<sup>2</sup> − 8a</b>.', '−2a · 3a<sup>2</sup> = −6a<sup>3</sup>; −2a · (−a) = +2a<sup>2</sup>; −2a · 4 = −8a. Ответ: <b>−6a<sup>3</sup> + 2a<sup>2</sup> − 8a</b>.', '−2a · 3a<sup>2</sup> = −6a<sup>3</sup>; −2a · (−a) = +2a<sup>2</sup>; −2a · 4 = −8a. Answer: <b>−6a<sup>3</sup> + 2a<sup>2</sup> − 8a</b>.') },
      { q: L('Bog‘ masalasi: (x + 3)(x − 2) ni ko‘phad ko‘rinishida yozing va x = 10 da hisoblang.', 'Задача о саде: запишите (x + 3)(x − 2) в виде многочлена и вычислите при x = 10.', 'Garden problem: write (x + 3)(x − 2) as a polynomial and evaluate at x = 10.'), s: L('x · x − 2x + 3x − 6 = <b>x<sup>2</sup> + x − 6</b>. x = 10 da: 100 + 10 − 6 = 104 m<sup>2</sup>. Tekshiruv: 13 · 8 = 104 ✓. Eski bog‘ 100 m<sup>2</sup> edi, yangisi 4 m<sup>2</sup> katta.', 'x · x − 2x + 3x − 6 = <b>x<sup>2</sup> + x − 6</b>. При x = 10: 100 + 10 − 6 = 104 м<sup>2</sup>. Проверка: 13 · 8 = 104 ✓. Старый сад был 100 м<sup>2</sup>, новый на 4 м<sup>2</sup> больше.', 'x · x − 2x + 3x − 6 = <b>x<sup>2</sup> + x − 6</b>. At x = 10: 100 + 10 − 6 = 104 m<sup>2</sup>. Check: 13 · 8 = 104 ✓. The old garden was 100 m<sup>2</sup>; the new one is 4 m<sup>2</sup> larger.') },
      { q: L('Ko‘paytiring: (2x − 1)(x<sup>2</sup> + 3x − 4).', 'Умножьте: (2x − 1)(x<sup>2</sup> + 3x − 4).', 'Multiply: (2x − 1)(x<sup>2</sup> + 3x − 4).'), s: L('2x · (x<sup>2</sup> + 3x − 4) = 2x<sup>3</sup> + 6x<sup>2</sup> − 8x; −1 · (x<sup>2</sup> + 3x − 4) = −x<sup>2</sup> − 3x + 4. Qo‘shamiz: <b>2x<sup>3</sup> + 5x<sup>2</sup> − 11x + 4</b>. 2 · 3 = 6 ta had bo‘ldi, ixchamlashdan so‘ng 4 ta qoldi.', '2x · (x<sup>2</sup> + 3x − 4) = 2x<sup>3</sup> + 6x<sup>2</sup> − 8x; −1 · (x<sup>2</sup> + 3x − 4) = −x<sup>2</sup> − 3x + 4. Складываем: <b>2x<sup>3</sup> + 5x<sup>2</sup> − 11x + 4</b>. Было 2 · 3 = 6 членов, после приведения осталось 4.', '2x · (x<sup>2</sup> + 3x − 4) = 2x<sup>3</sup> + 6x<sup>2</sup> − 8x; −1 · (x<sup>2</sup> + 3x − 4) = −x<sup>2</sup> − 3x + 4. Add: <b>2x<sup>3</sup> + 5x<sup>2</sup> − 11x + 4</b>. There were 2 · 3 = 6 terms; 4 remain after collecting.') },
      { q: L('Bo‘ling: (12a<sup>4</sup>b − 8a<sup>3</sup>b<sup>2</sup> + 4a<sup>2</sup>b) : 4a<sup>2</sup>b.', 'Разделите: (12a<sup>4</sup>b − 8a<sup>3</sup>b<sup>2</sup> + 4a<sup>2</sup>b) : 4a<sup>2</sup>b.', 'Divide: (12a<sup>4</sup>b − 8a<sup>3</sup>b<sup>2</sup> + 4a<sup>2</sup>b) : 4a<sup>2</sup>b.'), s: L('Har bir hadni bo‘lamiz: 3a<sup>2</sup> − 2ab + 1. Oxirgi had 4a<sup>2</sup>b : 4a<sup>2</sup>b = 1 — uni tashlab ketmang! Javob: <b>3a<sup>2</sup> − 2ab + 1</b>.', 'Делим каждый член: 3a<sup>2</sup> − 2ab + 1. Последний член 4a<sup>2</sup>b : 4a<sup>2</sup>b = 1 — не потеряйте его! Ответ: <b>3a<sup>2</sup> − 2ab + 1</b>.', 'Divide each term: 3a<sup>2</sup> − 2ab + 1. The last term is 4a<sup>2</sup>b : 4a<sup>2</sup>b = 1 — don’t drop it! Answer: <b>3a<sup>2</sup> − 2ab + 1</b>.') }
    ] },
    { kind: 'table', h: L('Ko‘paytirish jadvali usuli', 'Метод таблицы', 'The grid method'), p: [
      L('(2x + 3)(x − 5) ni jadval yordamida ko‘paytiramiz: satrga birinchi ko‘phad hadlarini, ustunga ikkinchisinikini yozamiz, kataklarga ko‘paytmalarni qo‘yamiz. Bu xuddi to‘g‘ri to‘rtburchakni bo‘laklarga ajratishga o‘xshaydi.', 'Умножим (2x + 3)(x − 5) с помощью таблицы: по строкам — члены первого многочлена, по столбцам — второго, в клетках — произведения. Это как разрезать прямоугольник на части.', 'Let us multiply (2x + 3)(x − 5) with a grid: terms of the first polynomial down the side, of the second across the top, products in the cells. It is like cutting a rectangle into pieces.')
    ], table: { head: ['×', 'x', '−5'], rows: [
      ['2x', '2x<sup>2</sup>', '−10x'],
      ['3', '3x', '−15']
    ] }, after: [
      L('Kataklarni qo‘shamiz: 2x<sup>2</sup> − 10x + 3x − 15 = <b>2x<sup>2</sup> − 7x − 15</b>. Jadval usuli hech bir hadni unutmaslikka yordam beradi.', 'Складываем клетки: 2x<sup>2</sup> − 10x + 3x − 15 = <b>2x<sup>2</sup> − 7x − 15</b>. Таблица помогает не забыть ни одного члена.', 'Add the cells: 2x<sup>2</sup> − 10x + 3x − 15 = <b>2x<sup>2</sup> − 7x − 15</b>. The grid makes sure no term is forgotten.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Faqat birinchi hadga ko‘paytirish.</b> 3(x + 4) = 3x + 4 — xato; to‘g‘risi 3x + 12.', '<b>Умножить только первый член.</b> 3(x + 4) = 3x + 4 — ошибка; верно 3x + 12.', '<b>Multiplying only the first term.</b> 3(x + 4) = 3x + 4 is wrong; it is 3x + 12.'),
      L('<b>«Yarim» ko‘paytirish.</b> (x + 3)(x + 2) = x<sup>2</sup> + 6 — o‘rtadagi hadlar yo‘qolgan. To‘g‘risi x<sup>2</sup> + 5x + 6.', '<b>«Половинное» умножение.</b> (x + 3)(x + 2) = x<sup>2</sup> + 6 — потеряны средние члены. Верно x<sup>2</sup> + 5x + 6.', '<b>“Half” multiplying.</b> (x + 3)(x + 2) = x<sup>2</sup> + 6 loses the middle terms. The answer is x<sup>2</sup> + 5x + 6.'),
      L('<b>Ishora xatosi.</b> (x − 3)(x − 4) da oxirgi had −12 emas, +12.', '<b>Ошибка в знаке.</b> В (x − 3)(x − 4) последний член +12, а не −12.', '<b>Sign error.</b> In (x − 3)(x − 4) the last term is +12, not −12.'),
      L('<b>Bo‘lishda hadni yo‘qotish.</b> (4x<sup>2</sup> + 2x) : 2x = 2x — xato; 2x : 2x = 1, javob 2x + 1.', '<b>Потерять член при делении.</b> (4x<sup>2</sup> + 2x) : 2x = 2x — ошибка; 2x : 2x = 1, ответ 2x + 1.', '<b>Losing a term when dividing.</b> (4x<sup>2</sup> + 2x) : 2x = 2x is wrong; 2x : 2x = 1, so the answer is 2x + 1.')
    ] },
    { kind: 'life', h: L('Ko‘paytirish hayotda', 'Умножение в жизни', 'Multiplication in real life'), p: [
      L('<b>Rom uchun shisha.</b> Rasm a × b sm, atrofida har tomondan 3 sm ramka. Ramka bilan birga o‘lcham (a + 6)(b + 6) = ab + 6a + 6b + 36. Ramkaning o‘zining yuzi: 6a + 6b + 36. Usta bu formula bilan istalgan rasm uchun materialni tez hisoblaydi.', '<b>Стекло для рамки.</b> Картина a × b см, вокруг рамка по 3 см с каждой стороны. Вместе с рамкой (a + 6)(b + 6) = ab + 6a + 6b + 36. Площадь самой рамки: 6a + 6b + 36. Мастер по этой формуле быстро считает материал для любой картины.', '<b>Picture frames.</b> A picture is a × b cm with a 3 cm frame on every side. With the frame the size is (a + 6)(b + 6) = ab + 6a + 6b + 36. The frame alone has area 6a + 6b + 36. A framer uses this formula to work out material for any picture.'),
      L('<b>Tez hisob.</b> 23 · 45 = (20 + 3)(40 + 5) = 800 + 100 + 120 + 15 = 1035. Bozorda kalkulyatorsiz hisoblashda aynan shu usul ishlatiladi. <b>Do‘kon daromadi.</b> Narxni x so‘mga oshirsak, sotuv esa kamaysa, daromad (p + x)(n − kx) ko‘paytma bilan ifodalanadi — iqtisodchilar uni ochib, eng foydali narxni qidiradi.', '<b>Быстрый счёт.</b> 23 · 45 = (20 + 3)(40 + 5) = 800 + 100 + 120 + 15 = 1035. На базаре без калькулятора считают именно так. <b>Выручка магазина.</b> Если поднять цену на x сум, а продажи упадут, выручка выражается произведением (p + x)(n − kx) — экономисты раскрывают его и ищут самую выгодную цену.', '<b>Quick maths.</b> 23 · 45 = (20 + 3)(40 + 5) = 800 + 100 + 120 + 15 = 1035. That is exactly how people calculate at the market without a calculator. <b>Shop revenue.</b> If a price rises by x sum while sales fall, revenue is the product (p + x)(n − kx) — economists expand it to look for the most profitable price.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Kompyuterlar juda katta sonlarni ko‘paytirishda ham ko‘phadlar g‘oyasidan foydalanadi. 1960-yilda yosh sovet matematigi Anatoliy Karatsuba 4 ta ko‘paytirish o‘rniga 3 tasi yetishini ko‘rsatgan.', 'Компьютеры при умножении очень больших чисел тоже используют идею многочленов. В 1960 году молодой советский математик Анатолий Карацуба показал, что вместо 4 умножений достаточно 3.', 'Computers use the polynomial idea to multiply huge numbers. In 1960 the young Soviet mathematician Anatoly Karatsuba showed that 3 multiplications are enough instead of 4.'),
      L('(x − 1)(x + 1) = x<sup>2</sup> − 1, (x − 1)(x<sup>2</sup> + x + 1) = x<sup>3</sup> − 1 — ko‘paytmada ko‘p hadlar «yo‘q bo‘lib ketadi». Bu qisqa ko‘paytirish formulalarining boshlanishi.', '(x − 1)(x + 1) = x<sup>2</sup> − 1, (x − 1)(x<sup>2</sup> + x + 1) = x<sup>3</sup> − 1 — в произведении многие члены «исчезают». Это начало формул сокращённого умножения.', '(x − 1)(x + 1) = x<sup>2</sup> − 1 and (x − 1)(x<sup>2</sup> + x + 1) = x<sup>3</sup> − 1 — many terms “vanish” in the product. This is where special products begin.'),
      L('11 · 11 = 121, 111 · 111 = 12 321, 1111 · 1111 = 1 234 321 — bu chiroyli naqsh ham ko‘phadlar ko‘paytmasining natijasi.', '11 · 11 = 121, 111 · 111 = 12 321, 1111 · 1111 = 1 234 321 — этот красивый узор тоже результат умножения многочленов.', '11 · 11 = 121, 111 · 111 = 12 321, 1111 · 1111 = 1 234 321 — this pretty pattern is also a result of multiplying polynomials.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. (x − 5)(x + 7) ni ko‘phad ko‘rinishida yozing.', '1. Запишите (x − 5)(x + 7) в виде многочлена.', '1. Write (x − 5)(x + 7) as a polynomial.'),
      L('2. (3a + b)(a − 2b) ni ko‘paytiring.', '2. Умножьте (3a + b)(a − 2b).', '2. Multiply (3a + b)(a − 2b).'),
      L('3. (15x<sup>3</sup> − 10x<sup>2</sup> + 5x) : 5x ni toping.', '3. Найдите (15x<sup>3</sup> − 10x<sup>2</sup> + 5x) : 5x.', '3. Find (15x<sup>3</sup> − 10x<sup>2</sup> + 5x) : 5x.'),
      L('4. Isbotlang: (n + 1)(n + 2) − n(n + 3) = 2 istalgan n uchun.', '4. Докажите: (n + 1)(n + 2) − n(n + 3) = 2 при любом n.', '4. Prove that (n + 1)(n + 2) − n(n + 3) = 2 for every n.')
    ], after: [
      L('Javoblar: 1) x<sup>2</sup> + 2x − 35; 2) 3a<sup>2</sup> − 5ab − 2b<sup>2</sup>; 3) 3x<sup>2</sup> − 2x + 1; 4) n<sup>2</sup> + 3n + 2 − n<sup>2</sup> − 3n = 2.', 'Ответы: 1) x<sup>2</sup> + 2x − 35; 2) 3a<sup>2</sup> − 5ab − 2b<sup>2</sup>; 3) 3x<sup>2</sup> − 2x + 1; 4) n<sup>2</sup> + 3n + 2 − n<sup>2</sup> − 3n = 2.', 'Answers: 1) x<sup>2</sup> + 2x − 35; 2) 3a<sup>2</sup> − 5ab − 2b<sup>2</sup>; 3) 3x<sup>2</sup> − 2x + 1; 4) n<sup>2</sup> + 3n + 2 − n<sup>2</sup> − 3n = 2.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Hamma qoidalar taqsimot qonunidan kelib chiqadi: a(b + c) = ab + ac.', 'Все правила следуют из распределительного закона: a(b + c) = ab + ac.', 'All the rules come from the distributive law: a(b + c) = ab + ac.'),
      L('Birhadni ko‘phadga ko‘paytirishda birhad har bir hadga ko‘paytiriladi.', 'При умножении одночлена на многочлен одночлен умножается на каждый член.', 'A monomial times a polynomial: multiply the monomial by every term.'),
      L('Ko‘phadni ko‘phadga ko‘paytirishda har bir had har biriga ko‘paytiriladi (m · n ta had).', 'При умножении многочленов каждый член умножается на каждый (m · n членов).', 'Polynomial times polynomial: every term times every term (m · n terms).'),
      L('(x + a)(x + b) = x<sup>2</sup> + (a + b)x + ab.', '(x + a)(x + b) = x<sup>2</sup> + (a + b)x + ab.', '(x + a)(x + b) = x<sup>2</sup> + (a + b)x + ab.'),
      L('Ko‘phadni birhadga bo‘lishda har bir had bo‘linadi.', 'При делении многочлена на одночлен делится каждый член.', 'Dividing by a monomial: divide every term.'),
      L('Natijani ixchamlang va son qo‘yib tekshiring.', 'Приведите подобные и проверьте подстановкой.', 'Collect like terms and check by substitution.')
    ] }
  ] });

  // ---------- t6. Ko‘paytuvchilarga ajratish ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Teskari yo‘l', 'Обратный путь', 'Going backwards'), p: [
      L('Oldingi mavzuda ko‘paytmani yig‘indiga aylantirdik: 2x(x + 3) = 2x<sup>2</sup> + 6x. Endi teskari ishni o‘rganamiz: yig‘indini ko‘paytmaga aylantirish. Bu <b>ko‘paytuvchilarga ajratish</b> deyiladi. Xuddi 12 sonini 2 · 2 · 3 ko‘rinishida yozganimizdek, ko‘phadni ham sodda ko‘phadlar ko‘paytmasi shaklida yozamiz.', 'В прошлой теме мы превращали произведение в сумму: 2x(x + 3) = 2x<sup>2</sup> + 6x. Теперь научимся обратному: превращать сумму в произведение. Это называется <b>разложением на множители</b>. Как число 12 мы записываем в виде 2 · 2 · 3, так и многочлен запишем произведением более простых многочленов.', 'In the last topic we turned products into sums: 2x(x + 3) = 2x<sup>2</sup> + 6x. Now we learn the reverse: turning a sum into a product. This is called <b>factorising</b>. Just as we write 12 as 2 · 2 · 3, we write a polynomial as a product of simpler polynomials.'),
      L('Nega kerak? Ko‘paytma bilan ishlash ancha qulay: kasrlarni qisqartirish, tenglamalarni yechish va tez hisoblash ko‘paytuvchilarga ajratishsiz deyarli mumkin emas. Masalan, 37 · 18 + 37 · 82 = 37 · (18 + 82) = 3 700 — og‘zaki bir soniyada!', 'Зачем? С произведением работать гораздо удобнее: сокращение дробей, решение уравнений и быстрый счёт почти невозможны без разложения на множители. Например, 37 · 18 + 37 · 82 = 37 · (18 + 82) = 3 700 — устно за секунду!', 'Why? Products are much easier to work with: simplifying fractions, solving equations and quick mental maths are nearly impossible without factorising. For example, 37 · 18 + 37 · 82 = 37 · (18 + 82) = 3 700 — in one second, in your head!')
    ] },
    { kind: 'def', h: L('Ikki asosiy usul', 'Два основных способа', 'Two main methods'), p: [
      L('<b>Ko‘paytuvchilarga ajratish</b> — ko‘phadni ikki yoki undan ortiq ko‘phad (birhad) ko‘paytmasi ko‘rinishida yozish.', '<b>Разложение на множители</b> — запись многочлена в виде произведения двух или более многочленов (одночленов).', '<b>Factorising</b> means writing a polynomial as a product of two or more polynomials (or monomials).'),
      L('<b>1. Umumiy ko‘paytuvchini qavsdan chiqarish.</b> Agar barcha hadlarda bir xil ko‘paytuvchi bo‘lsa, uni qavs oldiga chiqaramiz: ab + ac = a(b + c). Umumiy ko‘paytuvchi sifatida koeffitsiyentlarning EKUB i va barcha hadlarda qatnashgan harflarning eng kichik darajasi olinadi: 12x<sup>3</sup>y − 18x<sup>2</sup>y<sup>2</sup> = 6x<sup>2</sup>y(2x − 3y).', '<b>1. Вынесение общего множителя за скобки.</b> Если во всех членах есть одинаковый множитель, выносим его: ab + ac = a(b + c). Общим множителем берут НОД коэффициентов и буквы, входящие во все члены, в наименьшей степени: 12x<sup>3</sup>y − 18x<sup>2</sup>y<sup>2</sup> = 6x<sup>2</sup>y(2x − 3y).', '<b>1. Taking out a common factor.</b> If every term shares a factor, take it outside the bracket: ab + ac = a(b + c). Use the HCF of the coefficients and the letters present in every term, each to its smallest power: 12x<sup>3</sup>y − 18x<sup>2</sup>y<sup>2</sup> = 6x<sup>2</sup>y(2x − 3y).'),
      L('<b>2. Guruhlash usuli.</b> Hadlarni guruhlarga ajratib, har bir guruhdan umumiy ko‘paytuvchini chiqaramiz; agar qavslar ichida bir xil ifoda qolsa, uni ham chiqaramiz: ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3).', '<b>2. Способ группировки.</b> Разбиваем члены на группы и из каждой выносим общий множитель; если в скобках осталось одно и то же, выносим и его: ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3).', '<b>2. Grouping.</b> Split the terms into groups and take the common factor out of each; if the same bracket is left in each group, take that out too: ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3).')
    ] },
    { kind: 'history', h: L('Yevklid, EKUB va ko‘paytuvchilar', 'Евклид, НОД и множители', 'Euclid, HCF and factors'), p: [
      L('Sonlarni ko‘paytuvchilarga ajratish g‘oyasi juda qadimiy. Miloddan avvalgi III asrda <b>Yevklid</b> «Negizlar» kitobida har bir natural son tub sonlar ko‘paytmasiga yagona tarzda ajralishini asoslagan va ikki sonning eng katta umumiy bo‘luvchisini topish algoritmini bergan. Bu algoritm 2 300 yildan beri ishlatiladi va hozir ham kompyuterlarda qo‘llaniladi.', 'Идея раскладывать числа на множители очень древняя. В III веке до н. э. <b>Евклид</b> в «Началах» обосновал, что натуральное число единственным образом раскладывается на простые множители, и дал алгоритм нахождения наибольшего общего делителя. Этим алгоритмом пользуются уже 2 300 лет, в том числе в компьютерах.', 'The idea of breaking numbers into factors is very old. In the 3rd century BC, <b>Euclid</b> in his “Elements” showed that every natural number breaks into prime factors in only one way, and gave an algorithm for the greatest common divisor. That algorithm has been used for 2 300 years and still runs in computers today.'),
      L('Ko‘phadlarni ko‘paytuvchilarga ajratish esa Uyg‘onish davrida, harfli yozuv paydo bo‘lgach, keng tarqaldi. <b>Abu Rayhon Beruniy</b> ham o‘z asarlarida murakkab hisoblarni soddalashtirish uchun umumiy ko‘paytuvchini ajratish usulidan mohirlik bilan foydalangan.', 'Разложение многочленов на множители широко распространилось в эпоху Возрождения, когда появилась буквенная запись. <b>Абу Райхан Беруни</b> в своих трудах тоже мастерски выделял общий множитель, чтобы упрощать сложные вычисления.', 'Factorising polynomials spread widely in the Renaissance, once letter notation appeared. <b>Abu Rayhan Biruni</b> also skilfully pulled out common factors in his works to simplify long calculations.')
    ] },
    { kind: 'rule', h: L('Umumiy ko‘paytuvchini qanday topamiz?', 'Как найти общий множитель?', 'How to find the common factor'), p: [
      L('Son qismi: barcha koeffitsiyentlarning EKUBi. Harf qismi: <i>har bir</i> hadda uchraydigan harflar, eng kichik ko‘rsatkich bilan. Masalan, 15a<sup>4</sup>b<sup>2</sup> − 10a<sup>2</sup>b<sup>3</sup> + 5a<sup>3</sup>b: EKUB(15, 10, 5) = 5; a ning eng kichik darajasi 2; b niki 1. Umumiy ko‘paytuvchi 5a<sup>2</sup>b. Natija: 5a<sup>2</sup>b(3a<sup>2</sup>b − 2b<sup>2</sup> + a).', 'Числовая часть: НОД всех коэффициентов. Буквенная часть: буквы, входящие в <i>каждый</i> член, с наименьшим показателем. Например, 15a<sup>4</sup>b<sup>2</sup> − 10a<sup>2</sup>b<sup>3</sup> + 5a<sup>3</sup>b: НОД(15, 10, 5) = 5; наименьшая степень a — 2; b — 1. Общий множитель 5a<sup>2</sup>b. Итог: 5a<sup>2</sup>b(3a<sup>2</sup>b − 2b<sup>2</sup> + a).', 'Number part: the HCF of all the coefficients. Letter part: the letters found in <i>every</i> term, each with its smallest exponent. For example, 15a<sup>4</sup>b<sup>2</sup> − 10a<sup>2</sup>b<sup>3</sup> + 5a<sup>3</sup>b: HCF(15, 10, 5) = 5; smallest power of a is 2, of b is 1. Common factor 5a<sup>2</sup>b. Result: 5a<sup>2</sup>b(3a<sup>2</sup>b − 2b<sup>2</sup> + a).'),
      L('Qavs ichidagi hadlar sonini tekshiring: u dastlabki ko‘phaddagi hadlar soniga teng bo‘lishi shart. Agar ko‘paytuvchi biror hadga to‘liq teng bo‘lsa, qavs ichida 1 qoladi. Qavs ichida yana umumiy ko‘paytuvchi qolmagan bo‘lishi kerak.', 'Проверьте число членов в скобках: оно должно совпадать с числом членов исходного многочлена. Если множитель полностью совпал с членом, в скобках остаётся 1. Внутри скобок общего множителя больше быть не должно.', 'Check the number of terms in the bracket: it must equal the number of terms in the original polynomial. If the factor equals a whole term, a 1 is left in the bracket. No common factor should remain inside.'),
      L('Tekshiruv doim oson: qavsni qaytadan ochib ko‘ring — dastlabki ko‘phad chiqishi kerak.', 'Проверка всегда проста: раскройте скобки обратно — должен получиться исходный многочлен.', 'Checking is always easy: expand the bracket again — you must get the original polynomial.')
    ] },
    { kind: 'steps', h: L('Guruhlash usuli bosqichlari', 'Шаги способа группировки', 'Steps for grouping'), list: [
      L('1. Avval barcha hadlar uchun umumiy ko‘paytuvchi bormi — tekshiring va chiqaring.', '1. Сначала проверьте, есть ли общий множитель у всех членов, и вынесите его.', '1. First check whether all terms share a factor, and take it out.'),
      L('2. Hadlarni juft-juft (yoki uchtalab) guruhlang.', '2. Сгруппируйте члены парами (или по три).', '2. Group the terms in pairs (or threes).'),
      L('3. Har bir guruhdan umumiy ko‘paytuvchini chiqaring; qavslar bir xil chiqishiga harakat qiling.', '3. Из каждой группы вынесите общий множитель; добейтесь одинаковых скобок.', '3. Take the common factor out of each group, aiming for identical brackets.'),
      L('4. Bir xil qavsni umumiy ko‘paytuvchi sifatida chiqaring.', '4. Вынесите одинаковую скобку как общий множитель.', '4. Take the identical bracket out as a common factor.'),
      L('5. Qavslar har xil chiqsa — boshqacha guruhlab ko‘ring yoki ishorani o‘zgartiring: b − a = −(a − b).', '5. Если скобки разные — сгруппируйте иначе или смените знак: b − a = −(a − b).', '5. If the brackets differ, try another grouping or flip a sign: b − a = −(a − b).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Ko‘paytuvchilarga ajrating: 4x<sup>3</sup> − 6x<sup>2</sup>.', 'Разложите на множители: 4x<sup>3</sup> − 6x<sup>2</sup>.', 'Factorise: 4x<sup>3</sup> − 6x<sup>2</sup>.'), s: L('EKUB(4, 6) = 2, x ning eng kichik darajasi 2. Javob: <b>2x<sup>2</sup>(2x − 3)</b>. Tekshiruv: 2x<sup>2</sup> · 2x − 2x<sup>2</sup> · 3 = 4x<sup>3</sup> − 6x<sup>2</sup> ✓.', 'НОД(4, 6) = 2, наименьшая степень x — 2. Ответ: <b>2x<sup>2</sup>(2x − 3)</b>. Проверка: 2x<sup>2</sup> · 2x − 2x<sup>2</sup> · 3 = 4x<sup>3</sup> − 6x<sup>2</sup> ✓.', 'HCF(4, 6) = 2, smallest power of x is 2. Answer: <b>2x<sup>2</sup>(2x − 3)</b>. Check: 2x<sup>2</sup> · 2x − 2x<sup>2</sup> · 3 = 4x<sup>3</sup> − 6x<sup>2</sup> ✓.') },
      { q: L('Ajrating: 3a(x − 2) + 5b(x − 2).', 'Разложите: 3a(x − 2) + 5b(x − 2).', 'Factorise: 3a(x − 2) + 5b(x − 2).'), s: L('Umumiy ko‘paytuvchi — butun qavs (x − 2). Javob: <b>(x − 2)(3a + 5b)</b>.', 'Общий множитель — целая скобка (x − 2). Ответ: <b>(x − 2)(3a + 5b)</b>.', 'The common factor is the whole bracket (x − 2). Answer: <b>(x − 2)(3a + 5b)</b>.') },
      { q: L('Guruhlab ajrating: x<sup>3</sup> − 2x<sup>2</sup> + 3x − 6.', 'Разложите группировкой: x<sup>3</sup> − 2x<sup>2</sup> + 3x − 6.', 'Factorise by grouping: x<sup>3</sup> − 2x<sup>2</sup> + 3x − 6.'), s: L('(x<sup>3</sup> − 2x<sup>2</sup>) + (3x − 6) = x<sup>2</sup>(x − 2) + 3(x − 2) = <b>(x − 2)(x<sup>2</sup> + 3)</b>.', '(x<sup>3</sup> − 2x<sup>2</sup>) + (3x − 6) = x<sup>2</sup>(x − 2) + 3(x − 2) = <b>(x − 2)(x<sup>2</sup> + 3)</b>.', '(x<sup>3</sup> − 2x<sup>2</sup>) + (3x − 6) = x<sup>2</sup>(x − 2) + 3(x − 2) = <b>(x − 2)(x<sup>2</sup> + 3)</b>.') },
      { q: L('Ajrating: ab − 3a − 2b + 6 (ishoraga e’tibor!).', 'Разложите: ab − 3a − 2b + 6 (внимание на знак!).', 'Factorise: ab − 3a − 2b + 6 (watch the sign!).'), s: L('(ab − 3a) + (−2b + 6) = a(b − 3) − 2(b − 3) = <b>(b − 3)(a − 2)</b>. Ikkinchi guruhdan −2 chiqarilgani uchun qavs ichida ishoralar o‘zgardi.', '(ab − 3a) + (−2b + 6) = a(b − 3) − 2(b − 3) = <b>(b − 3)(a − 2)</b>. Из второй группы вынесли −2, поэтому знаки в скобке поменялись.', '(ab − 3a) + (−2b + 6) = a(b − 3) − 2(b − 3) = <b>(b − 3)(a − 2)</b>. Taking −2 out of the second group flipped the signs inside.') },
      { q: L('Og‘zaki hisoblang: 4,7 · 63 + 4,7 · 37.', 'Вычислите устно: 4,7 · 63 + 4,7 · 37.', 'Calculate mentally: 4.7 · 63 + 4.7 · 37.'), s: L('4,7 · (63 + 37) = 4,7 · 100 = <b>470</b>.', '4,7 · (63 + 37) = 4,7 · 100 = <b>470</b>.', '4.7 · (63 + 37) = 4.7 · 100 = <b>470</b>.') }
    ] },
    { kind: 'table', h: L('Qaysi usulni tanlash kerak?', 'Какой способ выбрать?', 'Which method to choose?'), p: [
      L('Ko‘phadga qarab, qaysi usul mos kelishini tez aniqlashni o‘rganing. Jadvalda tipik holatlar keltirilgan.', 'Научитесь быстро определять по виду многочлена, какой способ подходит. В таблице — типичные случаи.', 'Learn to tell quickly from the look of a polynomial which method fits. The table shows typical cases.')
    ], table: { head: [L('Ko‘phad', 'Многочлен', 'Polynomial'), L('Usul', 'Способ', 'Method'), L('Natija', 'Результат', 'Result')], rows: [
      ['7x + 14', L('umumiy ko‘paytuvchi', 'общий множитель', 'common factor'), '7(x + 2)'],
      ['a<sup>3</sup> − a<sup>2</sup>', L('umumiy ko‘paytuvchi', 'общий множитель', 'common factor'), 'a<sup>2</sup>(a − 1)'],
      ['m(n + 1) − 2(n + 1)', L('umumiy qavs', 'общая скобка', 'common bracket'), '(n + 1)(m − 2)'],
      ['ax − bx + ay − by', L('guruhlash', 'группировка', 'grouping'), '(a − b)(x + y)'],
      ['x<sup>2</sup> + 3x + 2x + 6', L('guruhlash', 'группировка', 'grouping'), '(x + 3)(x + 2)']
    ] }, after: [
      L('Qoida: avval doim umumiy ko‘paytuvchini qidiring, so‘ng to‘rt hadli ko‘phadlarda guruhlashni sinab ko‘ring. Keyingi bobda uchinchi usul — qisqa ko‘paytirish formulalarini ham o‘rganamiz.', 'Правило: сначала всегда ищите общий множитель, затем для многочленов из четырёх членов пробуйте группировку. В следующей главе узнаем третий способ — формулы сокращённого умножения.', 'Rule of thumb: always look for a common factor first, then try grouping for four-term polynomials. In the next chapter we learn a third method — special product formulas.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>1 ni yo‘qotish.</b> 5x<sup>2</sup> + x = x(5x) — xato; x ni chiqarganda o‘rnida 1 qoladi: x(5x + 1).', '<b>Потерять 1.</b> 5x<sup>2</sup> + x = x(5x) — ошибка; на месте вынесенного x остаётся 1: x(5x + 1).', '<b>Losing the 1.</b> 5x<sup>2</sup> + x = x(5x) is wrong; where x was taken out a 1 remains: x(5x + 1).'),
      L('<b>To‘liq chiqarmaslik.</b> 6x<sup>2</sup> + 9x = 3(2x<sup>2</sup> + 3x) — to‘g‘ri, lekin tugallanmagan; x ham umumiy: 3x(2x + 3).', '<b>Вынести не полностью.</b> 6x<sup>2</sup> + 9x = 3(2x<sup>2</sup> + 3x) — верно, но не до конца; x тоже общий: 3x(2x + 3).', '<b>Not taking out everything.</b> 6x<sup>2</sup> + 9x = 3(2x<sup>2</sup> + 3x) is true but unfinished; x is common too: 3x(2x + 3).'),
      L('<b>Manfiy ko‘paytuvchida ishorani unutish.</b> −4a − 8 = −4(a − 2) — xato; to‘g‘risi −4(a + 2).', '<b>Забыть знак при отрицательном множителе.</b> −4a − 8 = −4(a − 2) — ошибка; верно −4(a + 2).', '<b>Forgetting signs with a negative factor.</b> −4a − 8 = −4(a − 2) is wrong; it is −4(a + 2).'),
      L('<b>Yig‘indini javob deb qoldirish.</b> a(x + y) + 3(x + y) hali ko‘paytma emas — oxirgi qadamda (x + y) ni chiqarish kerak.', '<b>Оставить сумму как ответ.</b> a(x + y) + 3(x + y) — ещё не произведение; на последнем шаге нужно вынести (x + y).', '<b>Stopping at a sum.</b> a(x + y) + 3(x + y) is not yet a product; the last step is to take out (x + y).')
    ] },
    { kind: 'life', h: L('Ajratish hayotda', 'Разложение в жизни', 'Factorising in real life'), p: [
      L('<b>Do‘kondagi hisob.</b> Siz 4 ta daftarni 2 300 so‘mdan va yana 6 tasini ham 2 300 so‘mdan oldingiz. Kassir 2 300 · 4 + 2 300 · 6 emas, 2 300 · 10 = 23 000 deb hisoblaydi — bu umumiy ko‘paytuvchini chiqarish.', '<b>Счёт в магазине.</b> Вы купили 4 тетради по 2 300 сум и ещё 6 тетрадей по 2 300 сум. Кассир считает не 2 300 · 4 + 2 300 · 6, а 2 300 · 10 = 23 000 — это вынесение общего множителя.', '<b>At the shop.</b> You bought 4 notebooks at 2 300 sum and another 6 at 2 300 sum. The cashier does not compute 2 300 · 4 + 2 300 · 6 but 2 300 · 10 = 23 000 — that is taking out a common factor.'),
      L('<b>Yer uchastkasi.</b> Uch qo‘shni dalaning eni bir xil — 40 m, bo‘ylari 120, 85 va 95 m. Umumiy yuz 40 · 120 + 40 · 85 + 40 · 95 = 40 · 300 = 12 000 m<sup>2</sup>. <b>Kriptografiya.</b> Internetdagi xavfsiz to‘lovlar juda katta sonni tub ko‘paytuvchilarga ajratish qiyinligiga asoslangan (RSA tizimi). Ya’ni ko‘paytirish oson, ajratish esa juda qiyin — shu farq sizning bank kartangizni himoya qiladi.', '<b>Земельный участок.</b> Три соседних поля одинаковой ширины 40 м и длиной 120, 85 и 95 м. Общая площадь 40 · 120 + 40 · 85 + 40 · 95 = 40 · 300 = 12 000 м<sup>2</sup>. <b>Криптография.</b> Безопасные платежи в интернете основаны на том, что очень большое число трудно разложить на простые множители (система RSA). Умножать легко, раскладывать — очень трудно, и эта разница защищает вашу банковскую карту.', '<b>Farmland.</b> Three neighbouring fields are all 40 m wide and 120, 85 and 95 m long. Total area: 40 · 120 + 40 · 85 + 40 · 95 = 40 · 300 = 12 000 m<sup>2</sup>. <b>Cryptography.</b> Secure online payments rely on how hard it is to break a huge number into prime factors (the RSA system). Multiplying is easy, factorising is very hard — and that gap protects your bank card.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('RSA-250 deb atalgan 250 xonali sonni ko‘paytuvchilarga ajratish uchun 2020-yilda yuzlab kompyuterlar jami 2 700 yil (bitta yadro hisobida) ishlagan.', 'Чтобы разложить на множители 250-значное число RSA-250, в 2020 году сотни компьютеров работали в сумме около 2 700 лет (в пересчёте на одно ядро).', 'Factorising the 250-digit number RSA-250 in 2020 took hundreds of computers about 2 700 core-years of work in total.'),
      L('x<sup>2</sup> + 1 ni butun koeffitsiyentli ko‘paytuvchilarga ajratib bo‘lmaydi — xuddi tub son kabi «tub ko‘phad».', 'x<sup>2</sup> + 1 нельзя разложить на множители с целыми коэффициентами — это как простое число, «неприводимый многочлен».', 'x<sup>2</sup> + 1 cannot be factorised with integer coefficients — it is like a prime number, an “irreducible polynomial”.'),
      L('Guruhlash usulida hadlarni turli tartibda guruhlash mumkin, lekin oxirgi javob doim bir xil chiqadi (ko‘paytuvchilar tartibi farq qilishi mumkin).', 'В способе группировки члены можно группировать по-разному, но итог всегда одинаков (может отличаться лишь порядок множителей).', 'With grouping you can pair the terms in different ways, but the final answer is always the same (only the order of factors may differ).')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. Ajrating: 9a<sup>2</sup>b − 12ab<sup>2</sup>.', '1. Разложите: 9a<sup>2</sup>b − 12ab<sup>2</sup>.', '1. Factorise: 9a<sup>2</sup>b − 12ab<sup>2</sup>.'),
      L('2. Ajrating: 2x(y − 4) − (y − 4).', '2. Разложите: 2x(y − 4) − (y − 4).', '2. Factorise: 2x(y − 4) − (y − 4).'),
      L('3. Guruhlab ajrating: xy + 5x + 2y + 10.', '3. Разложите группировкой: xy + 5x + 2y + 10.', '3. Factorise by grouping: xy + 5x + 2y + 10.'),
      L('4. Isbotlang: 7<sup>9</sup> + 7<sup>8</sup> soni 8 ga bo‘linadi.', '4. Докажите: 7<sup>9</sup> + 7<sup>8</sup> делится на 8.', '4. Prove that 7<sup>9</sup> + 7<sup>8</sup> is divisible by 8.')
    ], after: [
      L('Javoblar: 1) 3ab(3a − 4b); 2) (y − 4)(2x − 1); 3) x(y + 5) + 2(y + 5) = (y + 5)(x + 2); 4) 7<sup>8</sup>(7 + 1) = 8 · 7<sup>8</sup>.', 'Ответы: 1) 3ab(3a − 4b); 2) (y − 4)(2x − 1); 3) x(y + 5) + 2(y + 5) = (y + 5)(x + 2); 4) 7<sup>8</sup>(7 + 1) = 8 · 7<sup>8</sup>.', 'Answers: 1) 3ab(3a − 4b); 2) (y − 4)(2x − 1); 3) x(y + 5) + 2(y + 5) = (y + 5)(x + 2); 4) 7<sup>8</sup>(7 + 1) = 8 · 7<sup>8</sup>.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘paytuvchilarga ajratish — yig‘indini ko‘paytmaga aylantirish, ko‘paytirishga teskari amal.', 'Разложение на множители — превращение суммы в произведение, действие, обратное умножению.', 'Factorising turns a sum into a product — the reverse of expanding.'),
      L('Umumiy ko‘paytuvchi: koeffitsiyentlar EKUBi va har bir hadda bor harflarning eng kichik darajasi.', 'Общий множитель: НОД коэффициентов и общие буквы в наименьшей степени.', 'Common factor: the HCF of the coefficients and shared letters to their smallest power.'),
      L('Guruhlash: hadlarni guruhlab, bir xil qavs hosil qilib, uni chiqaramiz.', 'Группировка: группируем члены, получаем одинаковую скобку и выносим её.', 'Grouping: group terms, create an identical bracket and take it out.'),
      L('Qavs ichida hadlar soni dastlabki hadlar soniga teng bo‘lishi kerak; 1 ni unutmang.', 'В скобках столько же членов, сколько было в начале; не забывайте 1.', 'The bracket has as many terms as the original; don’t forget the 1.'),
      L('Javobni qavsni ochish orqali tekshiring.', 'Проверяйте ответ раскрытием скобок.', 'Check by expanding the brackets again.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-2';

  // ---------- t7. Yig‘indi va ayirmaning kvadrati ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('51<sup>2</sup> ni bir soniyada', '51<sup>2</sup> за одну секунду', '51<sup>2</sup> in one second'), p: [
      L('Do‘stingizdan 51<sup>2</sup> ni hisoblashni so‘rang. U ustun bilan ko‘paytira boshlaydi. Siz esa darhol aytasiz: 2 601. Sir nimada? 51 = 50 + 1, va (50 + 1)<sup>2</sup> = 2 500 + 100 + 1. Bu hiyla <b>yig‘indining kvadrati formulasiga</b> asoslangan. Bunday formulalar «qisqa ko‘paytirish formulalari» deyiladi, chunki ular ko‘phadlarni uzoq ko‘paytirishdan qutqaradi.', 'Попросите друга вычислить 51<sup>2</sup>. Он начнёт умножать столбиком, а вы сразу скажете: 2 601. В чём секрет? 51 = 50 + 1, а (50 + 1)<sup>2</sup> = 2 500 + 100 + 1. Этот трюк основан на <b>формуле квадрата суммы</b>. Такие формулы называют «формулами сокращённого умножения», потому что они избавляют от долгого умножения многочленов.', 'Ask a friend to work out 51<sup>2</sup>. They start long multiplication, but you answer at once: 2 601. The secret? 51 = 50 + 1, and (50 + 1)<sup>2</sup> = 2 500 + 100 + 1. This trick is based on the <b>square of a sum formula</b>. Such formulas are called “special products” because they save you from long polynomial multiplication.'),
      L('Bu mavzuda ikki muhim formulani o‘rganamiz, ularni geometrik rasm orqali tushunamiz va ham ochish, ham ko‘paytuvchilarga ajratish uchun ishlatamiz. Bu formulalar 8–11-sinflarda deyarli har darsda kerak bo‘ladi.', 'В этой теме мы изучим две важные формулы, поймём их через геометрическую картинку и будем применять и для раскрытия скобок, и для разложения на множители. Эти формулы нужны почти на каждом уроке в 8–11 классах.', 'In this topic we learn two important formulas, understand them through a geometric picture, and use them both to expand and to factorise. You will need these formulas in almost every lesson from grade 8 to grade 11.')
    ] },
    { kind: 'def', h: L('Ikki formula', 'Две формулы', 'Two formulas'), p: [
      L('<b>Yig‘indining kvadrati:</b> (a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. So‘z bilan: birinchi sonning kvadrati, plus ikkalasining ikkilangan ko‘paytmasi, plus ikkinchisining kvadrati.', '<b>Квадрат суммы:</b> (a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. Словами: квадрат первого, плюс удвоенное произведение первого на второе, плюс квадрат второго.', '<b>Square of a sum:</b> (a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. In words: the first squared, plus twice the product of the two, plus the second squared.'),
      L('<b>Ayirmaning kvadrati:</b> (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>. Farq faqat o‘rtadagi hadning ishorasida; oxirgi had doim musbat, chunki kvadrat manfiy bo‘lmaydi.', '<b>Квадрат разности:</b> (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>. Отличие только в знаке среднего члена; последний член всегда положителен, ведь квадрат не бывает отрицательным.', '<b>Square of a difference:</b> (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>. Only the sign of the middle term changes; the last term is always positive, because a square is never negative.'),
      L('Isbot oddiy ko‘paytirish: (a + b)<sup>2</sup> = (a + b)(a + b) = a<sup>2</sup> + ab + ba + b<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. O‘ng tomondagi uchhad <b>to‘la kvadrat</b> deyiladi.', 'Доказательство — обычное умножение: (a + b)<sup>2</sup> = (a + b)(a + b) = a<sup>2</sup> + ab + ba + b<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. Трёхчлен справа называют <b>полным квадратом</b>.', 'The proof is plain multiplication: (a + b)<sup>2</sup> = (a + b)(a + b) = a<sup>2</sup> + ab + ba + b<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. The trinomial on the right is called a <b>perfect square</b>.')
    ] },
    { kind: 'rule', h: L('Geometrik rasm', 'Геометрическая картинка', 'The geometric picture'), p: [
      L('Tomoni (a + b) bo‘lgan katta kvadrat chizing. Har bir tomonda a uzunlikni belgilab, chiziqlar o‘tkazing. Kvadrat to‘rt bo‘lakka bo‘linadi: chap yuqori burchakda tomoni a bo‘lgan kvadrat (yuzi a<sup>2</sup>), o‘ng pastda tomoni b bo‘lgan kvadrat (yuzi b<sup>2</sup>), qolgan ikki burchakda esa tomonlari a va b bo‘lgan ikkita bir xil to‘g‘ri to‘rtburchak (har birining yuzi ab).', 'Нарисуйте большой квадрат со стороной (a + b). Отметьте на сторонах длину a и проведите линии. Квадрат делится на четыре части: в левом верхнем углу — квадрат со стороной a (площадь a<sup>2</sup>), в правом нижнем — квадрат со стороной b (площадь b<sup>2</sup>), а в двух других углах — два одинаковых прямоугольника со сторонами a и b (площадь каждого ab).', 'Draw a big square with side (a + b). Mark length a on the sides and draw lines across. The square splits into four parts: in the top-left corner a square of side a (area a<sup>2</sup>), in the bottom-right a square of side b (area b<sup>2</sup>), and in the other two corners two identical rectangles with sides a and b (area ab each).'),
      L('Butun yuz: a<sup>2</sup> + ab + ab + b<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. Mana nega o‘rtada «2ab» bor — bu ikkita to‘g‘ri to‘rtburchak! Agar kimdir (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> desa, u ana shu ikki bo‘lakni unutgan.', 'Вся площадь: a<sup>2</sup> + ab + ab + b<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. Вот откуда «2ab» в середине — это два прямоугольника! Кто пишет (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>, тот забыл эти две части.', 'The whole area: a<sup>2</sup> + ab + ab + b<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>. That is where the “2ab” comes from — the two rectangles! Anyone who writes (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> has forgotten those two pieces.'),
      L('Ayirma uchun: tomoni a bo‘lgan kvadratdan eni b bo‘lgan ikki tasmani kesib tashlaymiz (2ab), lekin burchakdagi b<sup>2</sup> kvadrat ikki marta kesilgani uchun uni bir marta qaytaramiz: a<sup>2</sup> − 2ab + b<sup>2</sup>.', 'Для разности: от квадрата со стороной a отрезаем две полосы шириной b (2ab), но угловой квадрат b<sup>2</sup> отрезан дважды, поэтому один раз возвращаем его: a<sup>2</sup> − 2ab + b<sup>2</sup>.', 'For the difference: from a square of side a cut off two strips of width b (2ab), but the corner square b<sup>2</sup> was cut twice, so add it back once: a<sup>2</sup> − 2ab + b<sup>2</sup>.')
    ] },
    { kind: 'history', h: L('Yevklid va al-Xorazmiyning kvadratlari', 'Квадраты Евклида и аль-Хорезми', 'The squares of Euclid and al-Khwarizmi'), p: [
      L('Bu formula 2 300 yildan ortiq vaqt oldin ma’lum bo‘lgan. <b>Yevklid</b> «Negizlar» kitobining II kitobida uni harflarsiz, faqat geometrik shakl bilan isbotlagan: «agar kesma ixtiyoriy ikki qismga bo‘linsa, butun kesmadagi kvadrat ikki qismdagi kvadratlar va qismlar hosil qilgan to‘g‘ri to‘rtburchakning ikki karrasiga teng».', 'Эта формула известна более 2 300 лет. <b>Евклид</b> во II книге «Начал» доказал её без букв, только геометрически: «если отрезок разделён на две части, то квадрат на всём отрезке равен квадратам на частях вместе с удвоенным прямоугольником, построенным на частях».', 'This formula has been known for over 2 300 years. <b>Euclid</b>, in Book II of the “Elements”, proved it without letters, purely with shapes: if a line is cut into two parts, the square on the whole equals the squares on the parts plus twice the rectangle formed by the parts.'),
      L('<b>Al-Xorazmiy</b> esa aynan shu rasmdan foydalanib, kvadrat tenglamalarni yechgan: x<sup>2</sup> + 10x = 39 tenglamasida u kvadratga to‘rtta to‘g‘ri to‘rtburchak va burchaklarga kichik kvadratlar qo‘shib, katta to‘la kvadrat hosil qilgan va x = 3 ni topgan. Bu usul hozir «to‘la kvadratni ajratish» deyiladi va 8-sinfda o‘rganiladi.', '<b>Аль-Хорезми</b> использовал именно эту картинку для решения квадратных уравнений: в уравнении x<sup>2</sup> + 10x = 39 он достраивал квадрат прямоугольниками и маленькими угловыми квадратами до большого полного квадрата и находил x = 3. Этот приём сейчас называют «выделением полного квадрата», его изучают в 8 классе.', '<b>Al-Khwarizmi</b> used exactly this picture to solve quadratic equations: for x<sup>2</sup> + 10x = 39 he added rectangles and small corner squares to the square to build a big perfect square, and found x = 3. Today this is called “completing the square” and is studied in grade 8.')
    ] },
    { kind: 'steps', h: L('Formulani qo‘llash tartibi', 'Как применять формулу', 'How to apply the formula'), list: [
      L('1. Qavs ichidagi birinchi hadni a, ikkinchisini b deb belgilang (ishorasiz).', '1. Обозначьте первый член в скобках через a, второй — через b (без знака).', '1. Call the first term in the bracket a and the second b (without the sign).'),
      L('2. a<sup>2</sup> ni toping — koeffitsiyentni ham kvadratga ko‘taring: (3x)<sup>2</sup> = 9x<sup>2</sup>.', '2. Найдите a<sup>2</sup> — коэффициент тоже возведите в квадрат: (3x)<sup>2</sup> = 9x<sup>2</sup>.', '2. Find a<sup>2</sup> — square the coefficient too: (3x)<sup>2</sup> = 9x<sup>2</sup>.'),
      L('3. 2ab ni toping; ishorasi qavsdagi ishora bilan bir xil.', '3. Найдите 2ab; его знак такой же, как в скобке.', '3. Find 2ab; its sign matches the sign in the bracket.'),
      L('4. b<sup>2</sup> ni toping — u doim «+».', '4. Найдите b<sup>2</sup> — он всегда со знаком «+».', '4. Find b<sup>2</sup> — it always has “+”.'),
      L('5. Teskari yo‘nalishda: uchhadda ikki had to‘la kvadrat bo‘lsa va uchinchisi ularning asoslari ko‘paytmasining ikki karrasi bo‘lsa — u (a ± b)<sup>2</sup>.', '5. В обратную сторону: если в трёхчлене два члена — квадраты, а третий — удвоенное произведение их оснований, то это (a ± b)<sup>2</sup>.', '5. Backwards: if two terms of a trinomial are squares and the third is twice the product of their roots, it is (a ± b)<sup>2</sup>.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Qavsni oching: (x − 5)<sup>2</sup>.', 'Раскройте скобки: (x − 5)<sup>2</sup>.', 'Expand: (x − 5)<sup>2</sup>.'), s: L('a = x, b = 5: x<sup>2</sup> − 2 · x · 5 + 25 = <b>x<sup>2</sup> − 10x + 25</b>.', 'a = x, b = 5: x<sup>2</sup> − 2 · x · 5 + 25 = <b>x<sup>2</sup> − 10x + 25</b>.', 'a = x, b = 5: x<sup>2</sup> − 2 · x · 5 + 25 = <b>x<sup>2</sup> − 10x + 25</b>.') },
      { q: L('Qavsni oching: (3a + 2b)<sup>2</sup>.', 'Раскройте скобки: (3a + 2b)<sup>2</sup>.', 'Expand: (3a + 2b)<sup>2</sup>.'), s: L('(3a)<sup>2</sup> + 2 · 3a · 2b + (2b)<sup>2</sup> = <b>9a<sup>2</sup> + 12ab + 4b<sup>2</sup></b>.', '(3a)<sup>2</sup> + 2 · 3a · 2b + (2b)<sup>2</sup> = <b>9a<sup>2</sup> + 12ab + 4b<sup>2</sup></b>.', '(3a)<sup>2</sup> + 2 · 3a · 2b + (2b)<sup>2</sup> = <b>9a<sup>2</sup> + 12ab + 4b<sup>2</sup></b>.') },
      { q: L('Og‘zaki hisoblang: 99<sup>2</sup>.', 'Вычислите устно: 99<sup>2</sup>.', 'Work out mentally: 99<sup>2</sup>.'), s: L('(100 − 1)<sup>2</sup> = 10 000 − 200 + 1 = <b>9 801</b>.', '(100 − 1)<sup>2</sup> = 10 000 − 200 + 1 = <b>9 801</b>.', '(100 − 1)<sup>2</sup> = 10 000 − 200 + 1 = <b>9 801</b>.') },
      { q: L('Ko‘paytuvchilarga ajrating: 4x<sup>2</sup> − 12x + 9.', 'Разложите на множители: 4x<sup>2</sup> − 12x + 9.', 'Factorise: 4x<sup>2</sup> − 12x + 9.'), s: L('4x<sup>2</sup> = (2x)<sup>2</sup>, 9 = 3<sup>2</sup>, 2 · 2x · 3 = 12x — ishora «−». Demak, <b>(2x − 3)<sup>2</sup></b>.', '4x<sup>2</sup> = (2x)<sup>2</sup>, 9 = 3<sup>2</sup>, 2 · 2x · 3 = 12x — знак «−». Значит, <b>(2x − 3)<sup>2</sup></b>.', '4x<sup>2</sup> = (2x)<sup>2</sup>, 9 = 3<sup>2</sup>, 2 · 2x · 3 = 12x with a “−”. So it is <b>(2x − 3)<sup>2</sup></b>.') },
      { q: L('Isbotlang: x<sup>2</sup> − 6x + 10 istalgan x da musbat.', 'Докажите: x<sup>2</sup> − 6x + 10 положительно при любом x.', 'Prove that x<sup>2</sup> − 6x + 10 is positive for every x.'), s: L('x<sup>2</sup> − 6x + 9 + 1 = (x − 3)<sup>2</sup> + 1. Kvadrat ≥ 0, unga 1 qo‘shilsa ≥ 1 &gt; 0. <b>Isbotlandi</b>; eng kichik qiymat 1 (x = 3 da).', 'x<sup>2</sup> − 6x + 9 + 1 = (x − 3)<sup>2</sup> + 1. Квадрат ≥ 0, плюс 1 даёт ≥ 1 &gt; 0. <b>Доказано</b>; наименьшее значение 1 (при x = 3).', 'x<sup>2</sup> − 6x + 9 + 1 = (x − 3)<sup>2</sup> + 1. A square is ≥ 0, so adding 1 gives ≥ 1 &gt; 0. <b>Proved</b>; the smallest value is 1 (at x = 3).') }
    ] },
    { kind: 'table', h: L('5 bilan tugaydigan sonlar kvadrati', 'Квадраты чисел, оканчивающихся на 5', 'Squares of numbers ending in 5'), p: [
      L('(10n + 5)<sup>2</sup> = 100n<sup>2</sup> + 100n + 25 = 100 · n(n + 1) + 25. Qoida: o‘nliklar sonini keyingi songa ko‘paytiring va oxiriga 25 yozing.', '(10n + 5)<sup>2</sup> = 100n<sup>2</sup> + 100n + 25 = 100 · n(n + 1) + 25. Правило: число десятков умножьте на следующее число и допишите 25.', '(10n + 5)<sup>2</sup> = 100n<sup>2</sup> + 100n + 25 = 100 · n(n + 1) + 25. Rule: multiply the tens digit by the next number and write 25 after it.')
    ], table: { head: [L('Son', 'Число', 'Number'), 'n(n + 1)', L('Kvadrat', 'Квадрат', 'Square')], rows: [
      ['25', '2 · 3 = 6', '625'],
      ['35', '3 · 4 = 12', '1 225'],
      ['65', '6 · 7 = 42', '4 225'],
      ['85', '8 · 9 = 72', '7 225'],
      ['105', '10 · 11 = 110', '11 025']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>O‘rta hadni unutish.</b> (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> — eng mashhur xato. Tekshiring: (3 + 4)<sup>2</sup> = 49, lekin 9 + 16 = 25.', '<b>Забыть средний член.</b> (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> — самая знаменитая ошибка. Проверьте: (3 + 4)<sup>2</sup> = 49, а 9 + 16 = 25.', '<b>Forgetting the middle term.</b> (a + b)<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> is the most famous mistake. Check: (3 + 4)<sup>2</sup> = 49, but 9 + 16 = 25.'),
      L('<b>2 ni unutish.</b> (x + 3)<sup>2</sup> = x<sup>2</sup> + 3x + 9 — xato; o‘rta had 6x.', '<b>Забыть двойку.</b> (x + 3)<sup>2</sup> = x<sup>2</sup> + 3x + 9 — ошибка; средний член 6x.', '<b>Forgetting the 2.</b> (x + 3)<sup>2</sup> = x<sup>2</sup> + 3x + 9 is wrong; the middle term is 6x.'),
      L('<b>Oxirgi hadga minus qo‘yish.</b> (x − 4)<sup>2</sup> = x<sup>2</sup> − 8x − 16 — xato; (−4)<sup>2</sup> = +16.', '<b>Поставить минус у последнего члена.</b> (x − 4)<sup>2</sup> = x<sup>2</sup> − 8x − 16 — ошибка; (−4)<sup>2</sup> = +16.', '<b>Putting a minus on the last term.</b> (x − 4)<sup>2</sup> = x<sup>2</sup> − 8x − 16 is wrong; (−4)<sup>2</sup> = +16.'),
      L('<b>Koeffitsiyentni kvadratga ko‘tarmaslik.</b> (2x + 1)<sup>2</sup> = 2x<sup>2</sup> + 4x + 1 — xato; to‘g‘risi 4x<sup>2</sup> + 4x + 1.', '<b>Не возвести коэффициент в квадрат.</b> (2x + 1)<sup>2</sup> = 2x<sup>2</sup> + 4x + 1 — ошибка; верно 4x<sup>2</sup> + 4x + 1.', '<b>Not squaring the coefficient.</b> (2x + 1)<sup>2</sup> = 2x<sup>2</sup> + 4x + 1 is wrong; it is 4x<sup>2</sup> + 4x + 1.')
    ] },
    { kind: 'life', h: L('Formulalar hayotda', 'Формулы в жизни', 'The formulas in real life'), p: [
      L('<b>Gilam va pol.</b> Tomoni a metr bo‘lgan kvadrat xonaga gilam olindi, lekin devor yonida har tomondan b metrdan bo‘sh joy qoldirish kerak. Gilam tomoni (a − 2b), yuzi (a − 2b)<sup>2</sup> = a<sup>2</sup> − 4ab + 4b<sup>2</sup>. Do‘konda shu formula bilan narxni tez hisoblash mumkin.', '<b>Ковёр и пол.</b> Для квадратной комнаты со стороной a метров купили ковёр, но у стен нужно оставить по b метров с каждой стороны. Сторона ковра (a − 2b), площадь (a − 2b)<sup>2</sup> = a<sup>2</sup> − 4ab + 4b<sup>2</sup>. В магазине по этой формуле быстро считают цену.', '<b>Carpets.</b> A square room has side a metres, and a carpet must leave b metres free along every wall. The carpet side is (a − 2b) and its area (a − 2b)<sup>2</sup> = a<sup>2</sup> − 4ab + 4b<sup>2</sup>. A shop can price it quickly with this formula.'),
      L('<b>Genetika.</b> Biologiyada Xardi–Vaynberg qonuni (p + q)<sup>2</sup> = p<sup>2</sup> + 2pq + q<sup>2</sup> ko‘rinishida yoziladi: u populyatsiyada genlar qanday taqsimlanishini ko‘rsatadi. Masalan, ko‘z rangi genlari aynan shu formula bo‘yicha avloddan-avlodga o‘tadi. <b>Og‘zaki hisob.</b> Sotuvchi 102 · 102 ni (100 + 2)<sup>2</sup> = 10 404 deb tez topadi.', '<b>Генетика.</b> В биологии закон Харди–Вайнберга записывается как (p + q)<sup>2</sup> = p<sup>2</sup> + 2pq + q<sup>2</sup>: он показывает, как распределяются гены в популяции. Например, гены цвета глаз передаются из поколения в поколение именно по этой формуле. <b>Устный счёт.</b> Продавец быстро находит 102 · 102 = (100 + 2)<sup>2</sup> = 10 404.', '<b>Genetics.</b> In biology the Hardy–Weinberg law is written (p + q)<sup>2</sup> = p<sup>2</sup> + 2pq + q<sup>2</sup>: it shows how genes are shared out in a population — eye-colour genes, for instance, pass between generations by this very formula. <b>Mental maths.</b> A seller finds 102 · 102 = (100 + 2)<sup>2</sup> = 10 404 in a flash.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Formuladan kelib chiqadi: ketma-ket ikki son kvadratlari farqi ularning yig‘indisiga teng: 26<sup>2</sup> − 25<sup>2</sup> = 26 + 25 = 51.', 'Из формулы следует: разность квадратов двух соседних чисел равна их сумме: 26<sup>2</sup> − 25<sup>2</sup> = 26 + 25 = 51.', 'It follows that the difference of the squares of two consecutive numbers equals their sum: 26<sup>2</sup> − 25<sup>2</sup> = 26 + 25 = 51.'),
      L('(a + b)<sup>2</sup> ≥ 4ab har doim to‘g‘ri, chunki (a − b)<sup>2</sup> ≥ 0. Shuning uchun perimetri bir xil bo‘lgan to‘g‘ri to‘rtburchaklar ichida eng katta yuzga kvadrat ega.', 'Всегда (a + b)<sup>2</sup> ≥ 4ab, ведь (a − b)<sup>2</sup> ≥ 0. Поэтому среди прямоугольников с одинаковым периметром наибольшую площадь имеет квадрат.', '(a + b)<sup>2</sup> ≥ 4ab always holds, because (a − b)<sup>2</sup> ≥ 0. That is why, among rectangles with the same perimeter, the square has the largest area.'),
      L('Hind matematigi Braxmagupta (VII asr) kvadratlar bilan ishlaydigan ko‘plab ayniyatlarni topgan va ulardan astronomik hisoblarda foydalangan.', 'Индийский математик Брахмагупта (VII век) нашёл много тождеств с квадратами и использовал их в астрономических расчётах.', 'The Indian mathematician Brahmagupta (7th century) found many identities involving squares and used them in astronomical calculations.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. (y + 7)<sup>2</sup> ni oching.', '1. Раскройте (y + 7)<sup>2</sup>.', '1. Expand (y + 7)<sup>2</sup>.'),
      L('2. (5m − 2n)<sup>2</sup> ni oching.', '2. Раскройте (5m − 2n)<sup>2</sup>.', '2. Expand (5m − 2n)<sup>2</sup>.'),
      L('3. Og‘zaki: 71<sup>2</sup> va 49<sup>2</sup>.', '3. Устно: 71<sup>2</sup> и 49<sup>2</sup>.', '3. Mentally: 71<sup>2</sup> and 49<sup>2</sup>.'),
      L('4. x<sup>2</sup> + 14x + 49 ni kvadrat ko‘rinishida yozing.', '4. Запишите x<sup>2</sup> + 14x + 49 в виде квадрата.', '4. Write x<sup>2</sup> + 14x + 49 as a square.')
    ], after: [
      L('Javoblar: 1) y<sup>2</sup> + 14y + 49; 2) 25m<sup>2</sup> − 20mn + 4n<sup>2</sup>; 3) 4 900 + 140 + 1 = 5 041 va 2 500 − 100 + 1 = 2 401; 4) (x + 7)<sup>2</sup>.', 'Ответы: 1) y<sup>2</sup> + 14y + 49; 2) 25m<sup>2</sup> − 20mn + 4n<sup>2</sup>; 3) 4 900 + 140 + 1 = 5 041 и 2 500 − 100 + 1 = 2 401; 4) (x + 7)<sup>2</sup>.', 'Answers: 1) y<sup>2</sup> + 14y + 49; 2) 25m<sup>2</sup> − 20mn + 4n<sup>2</sup>; 3) 4 900 + 140 + 1 = 5 041 and 2 500 − 100 + 1 = 2 401; 4) (x + 7)<sup>2</sup>.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('(a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>; (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>.', '(a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>; (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>.', '(a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>; (a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>.'),
      L('Rasmda: katta kvadrat = ikki kvadrat + ikki to‘g‘ri to‘rtburchak.', 'На картинке: большой квадрат = два квадрата + два прямоугольника.', 'As a picture: big square = two squares + two rectangles.'),
      L('O‘rta had — ikkilangan ko‘paytma; uni unutmang.', 'Средний член — удвоенное произведение; не забывайте его.', 'The middle term is twice the product — don’t forget it.'),
      L('Oxirgi had har doim musbat.', 'Последний член всегда положителен.', 'The last term is always positive.'),
      L('Formulalar ochish, ajratish va og‘zaki hisob uchun ishlatiladi.', 'Формулы служат для раскрытия скобок, разложения и устного счёта.', 'The formulas are used for expanding, factorising and mental maths.')
    ] }
  ] });

  // ---------- t8. Kvadratlar ayirmasi ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('47 · 53 ni og‘zaki', '47 · 53 устно', '47 · 53 in your head'), p: [
      L('47 ni 53 ga ko‘paytirish kerak. Diqqat qiling: ikkala son 50 dan bir xil masofada — biri 3 ta kam, biri 3 ta ko‘p. Shunda 47 · 53 = (50 − 3)(50 + 3) = 50<sup>2</sup> − 3<sup>2</sup> = 2 500 − 9 = 2 491. Hisob bir necha soniyada tugadi! Bu <b>kvadratlar ayirmasi formulasi</b> sharofati.', 'Нужно умножить 47 на 53. Заметьте: оба числа на одинаковом расстоянии от 50 — одно меньше на 3, другое больше на 3. Тогда 47 · 53 = (50 − 3)(50 + 3) = 50<sup>2</sup> − 3<sup>2</sup> = 2 500 − 9 = 2 491. Готово за несколько секунд! Это заслуга <b>формулы разности квадратов</b>.', 'You need 47 times 53. Notice that both numbers are the same distance from 50 — one is 3 less, one 3 more. So 47 · 53 = (50 − 3)(50 + 3) = 50<sup>2</sup> − 3<sup>2</sup> = 2 500 − 9 = 2 491. Done in seconds! That is the <b>difference of squares formula</b> at work.'),
      L('Bu formula — barcha qisqa ko‘paytirish formulalari ichida eng ko‘p ishlatiladigani. U kasrlarni qisqartirishda, tenglamalarni yechishda va hatto Pifagor teoremasi bilan ishlashda kerak bo‘ladi. Bu mavzuda uni isbotlaymiz, geometrik ma’nosini ko‘ramiz va ikki tomonga ishlatishni o‘rganamiz.', 'Эта формула — самая употребительная из всех формул сокращённого умножения. Она нужна при сокращении дробей, решении уравнений и даже при работе с теоремой Пифагора. В этой теме мы её докажем, увидим её геометрический смысл и научимся применять в обе стороны.', 'This is the most widely used of all the special product formulas. It is needed for simplifying fractions, solving equations and even working with Pythagoras’ theorem. In this topic we prove it, see its geometric meaning and learn to use it in both directions.')
    ] },
    { kind: 'def', h: L('Formula', 'Формула', 'The formula'), p: [
      L('<b>Ikki son yig‘indisining ularning ayirmasiga ko‘paytmasi ular kvadratlarining ayirmasiga teng:</b> (a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup>.', '<b>Произведение суммы двух чисел на их разность равно разности их квадратов:</b> (a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup>.', '<b>The sum of two numbers times their difference equals the difference of their squares:</b> (a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup>.'),
      L('Isbot: (a − b)(a + b) = a<sup>2</sup> + ab − ba − b<sup>2</sup> = a<sup>2</sup> − b<sup>2</sup>. O‘rtadagi ikki had (+ab va −ab) bir-birini yo‘q qiladi — shuning uchun javob shunchalik qisqa.', 'Доказательство: (a − b)(a + b) = a<sup>2</sup> + ab − ba − b<sup>2</sup> = a<sup>2</sup> − b<sup>2</sup>. Два средних члена (+ab и −ab) уничтожают друг друга — поэтому ответ такой короткий.', 'Proof: (a − b)(a + b) = a<sup>2</sup> + ab − ba − b<sup>2</sup> = a<sup>2</sup> − b<sup>2</sup>. The two middle terms (+ab and −ab) cancel — that is why the answer is so short.'),
      L('Teskari o‘qilsa, ko‘paytuvchilarga ajratish formulasi chiqadi: <b>a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)</b>. Ikki kvadratning ayirmasini ko‘rsangiz — uni darhol ikki qavs ko‘paytmasiga aylantirish mumkin.', 'Если прочитать наоборот, получится формула разложения: <b>a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)</b>. Увидели разность двух квадратов — сразу превращайте её в произведение двух скобок.', 'Read backwards, it is a factorising formula: <b>a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)</b>. Whenever you see a difference of two squares, turn it into a product of two brackets straight away.')
    ] },
    { kind: 'rule', h: L('Geometrik ma’no', 'Геометрический смысл', 'Geometric meaning'), p: [
      L('Tomoni a bo‘lgan kvadrat olib, uning burchagidan tomoni b bo‘lgan kichik kvadratni kesib tashlang. Qolgan «L» shaklli bo‘lakning yuzi a<sup>2</sup> − b<sup>2</sup>. Endi bu bo‘lakni ikki to‘g‘ri to‘rtburchakka kesing: biri a × (a − b), ikkinchisi b × (a − b). Ikkinchisini burib, birinchisining yoniga qo‘ysangiz, eni (a − b), bo‘yi (a + b) bo‘lgan bitta katta to‘g‘ri to‘rtburchak hosil bo‘ladi. Yuz o‘zgarmadi: a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b).', 'Возьмите квадрат со стороной a и вырежьте из угла маленький квадрат со стороной b. Площадь оставшейся «Г»-образной фигуры a<sup>2</sup> − b<sup>2</sup>. Разрежьте её на два прямоугольника: a × (a − b) и b × (a − b). Повернув второй и приложив к первому, получим один большой прямоугольник шириной (a − b) и длиной (a + b). Площадь не изменилась: a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b).', 'Take a square of side a and cut a small square of side b from one corner. The remaining L-shape has area a<sup>2</sup> − b<sup>2</sup>. Cut it into two rectangles: a × (a − b) and b × (a − b). Turn the second and lay it next to the first, and you get one long rectangle of width (a − b) and length (a + b). The area has not changed: a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b).'),
      L('Bu rasm formulani yodlashni osonlashtiradi: «kvadratdan kvadrat kesildi — qolgani to‘g‘ri to‘rtburchakka aylandi».', 'Эта картинка помогает запомнить формулу: «из квадрата вырезали квадрат — остаток превратился в прямоугольник».', 'The picture makes the formula easy to remember: “cut a square out of a square — the rest becomes a rectangle”.')
    ] },
    { kind: 'history', h: L('Bobil jadvallari va Beruniy', 'Вавилонские таблицы и Беруни', 'Babylonian tables and Biruni'), p: [
      L('Qadimgi Bobil kotiblari (miloddan avvalgi 1800-yillar) ko‘paytirish uchun kvadratlar jadvalidan foydalanishgan. Ularning usuli: ab = ((a + b)<sup>2</sup> − (a − b)<sup>2</sup>) : 4. Bu formula kvadratlar ayirmasi g‘oyasining o‘zi. Shunday qilib, faqat kvadratlar jadvaliga ega bo‘lib, istalgan ikki sonni ko‘paytirish mumkin bo‘lgan.', 'Древние вавилонские писцы (около 1800 г. до н. э.) пользовались для умножения таблицами квадратов. Их способ: ab = ((a + b)<sup>2</sup> − (a − b)<sup>2</sup>) : 4. Эта формула — та же идея разности квадратов. Так, имея только таблицу квадратов, можно было перемножить любые два числа.', 'Ancient Babylonian scribes (around 1800 BC) used tables of squares for multiplication. Their method: ab = ((a + b)<sup>2</sup> − (a − b)<sup>2</sup>) : 4 — the very idea of a difference of squares. With just a table of squares they could multiply any two numbers.'),
      L('XI asrda <b>Abu Rayhon Beruniy</b> Yer radiusini o‘lchashda tog‘ cho‘qqisidan ufqqacha bo‘lgan masofani hisoblagan. Bunday hisoblarda to‘g‘ri burchakli uchburchak tomonlari kvadratlarining ayirmasi ishlatiladi: (R + h)<sup>2</sup> − R<sup>2</sup>. Beruniy natijasi zamonaviy qiymatdan 1–2% gina farq qilgan.', 'В XI веке <b>Абу Райхан Беруни</b>, измеряя радиус Земли, вычислял расстояние от вершины горы до горизонта. В таких расчётах используется разность квадратов сторон прямоугольного треугольника: (R + h)<sup>2</sup> − R<sup>2</sup>. Результат Беруни отличался от современного всего на 1–2%.', 'In the 11th century, <b>Abu Rayhan Biruni</b> measured the Earth’s radius by working out the distance from a mountain top to the horizon. Such calculations use a difference of squares of the sides of a right triangle: (R + h)<sup>2</sup> − R<sup>2</sup>. His result was only 1–2% away from the modern value.')
    ] },
    { kind: 'steps', h: L('Formulani tanib olish', 'Как узнать формулу', 'Spotting the formula'), list: [
      L('1. Ko‘paytmada ikki qavs bormi, ularning hadlari bir xil, faqat bittasida «+», ikkinchisida «−»? → a<sup>2</sup> − b<sup>2</sup>.', '1. В произведении две скобки с одинаковыми членами, но в одной «+», в другой «−»? → a<sup>2</sup> − b<sup>2</sup>.', '1. Two brackets with the same terms, one with “+” and one with “−”? → a<sup>2</sup> − b<sup>2</sup>.'),
      L('2. Ikki hadli ifodada ikkala had to‘la kvadratmi va orasida «−»mi? → (a − b)(a + b).', '2. В двучлене оба члена — полные квадраты и между ними «−»? → (a − b)(a + b).', '2. A binomial whose two terms are both perfect squares with “−” between them? → (a − b)(a + b).'),
      L('3. a va b ni aniqlang: 16x<sup>2</sup> = (4x)<sup>2</sup>, 25y<sup>4</sup> = (5y<sup>2</sup>)<sup>2</sup>.', '3. Найдите a и b: 16x<sup>2</sup> = (4x)<sup>2</sup>, 25y<sup>4</sup> = (5y<sup>2</sup>)<sup>2</sup>.', '3. Identify a and b: 16x<sup>2</sup> = (4x)<sup>2</sup>, 25y<sup>4</sup> = (5y<sup>2</sup>)<sup>2</sup>.'),
      L('4. Avval umumiy ko‘paytuvchini chiqaring: 3x<sup>2</sup> − 12 = 3(x<sup>2</sup> − 4) = 3(x − 2)(x + 2).', '4. Сначала вынесите общий множитель: 3x<sup>2</sup> − 12 = 3(x<sup>2</sup> − 4) = 3(x − 2)(x + 2).', '4. Take out any common factor first: 3x<sup>2</sup> − 12 = 3(x<sup>2</sup> − 4) = 3(x − 2)(x + 2).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Ko‘paytiring: (2x − 5)(2x + 5).', 'Умножьте: (2x − 5)(2x + 5).', 'Multiply: (2x − 5)(2x + 5).'), s: L('a = 2x, b = 5: (2x)<sup>2</sup> − 5<sup>2</sup> = <b>4x<sup>2</sup> − 25</b>.', 'a = 2x, b = 5: (2x)<sup>2</sup> − 5<sup>2</sup> = <b>4x<sup>2</sup> − 25</b>.', 'a = 2x, b = 5: (2x)<sup>2</sup> − 5<sup>2</sup> = <b>4x<sup>2</sup> − 25</b>.') },
      { q: L('Ajrating: x<sup>2</sup> − 49.', 'Разложите: x<sup>2</sup> − 49.', 'Factorise: x<sup>2</sup> − 49.'), s: L('49 = 7<sup>2</sup>. Javob: <b>(x − 7)(x + 7)</b>.', '49 = 7<sup>2</sup>. Ответ: <b>(x − 7)(x + 7)</b>.', '49 = 7<sup>2</sup>. Answer: <b>(x − 7)(x + 7)</b>.') },
      { q: L('Hisoblang: 67<sup>2</sup> − 33<sup>2</sup>.', 'Вычислите: 67<sup>2</sup> − 33<sup>2</sup>.', 'Calculate: 67<sup>2</sup> − 33<sup>2</sup>.'), s: L('(67 − 33)(67 + 33) = 34 · 100 = <b>3 400</b>. Kvadratlarni alohida hisoblash shart emas!', '(67 − 33)(67 + 33) = 34 · 100 = <b>3 400</b>. Квадраты отдельно считать не нужно!', '(67 − 33)(67 + 33) = 34 · 100 = <b>3 400</b>. No need to square anything!') },
      { q: L('Ajrating: a<sup>4</sup> − 16.', 'Разложите: a<sup>4</sup> − 16.', 'Factorise: a<sup>4</sup> − 16.'), s: L('(a<sup>2</sup>)<sup>2</sup> − 4<sup>2</sup> = (a<sup>2</sup> − 4)(a<sup>2</sup> + 4) = <b>(a − 2)(a + 2)(a<sup>2</sup> + 4)</b>. Formula ikki marta ishlatildi; a<sup>2</sup> + 4 boshqa ajralmaydi.', '(a<sup>2</sup>)<sup>2</sup> − 4<sup>2</sup> = (a<sup>2</sup> − 4)(a<sup>2</sup> + 4) = <b>(a − 2)(a + 2)(a<sup>2</sup> + 4)</b>. Формула применена дважды; a<sup>2</sup> + 4 дальше не раскладывается.', '(a<sup>2</sup>)<sup>2</sup> − 4<sup>2</sup> = (a<sup>2</sup> − 4)(a<sup>2</sup> + 4) = <b>(a − 2)(a + 2)(a<sup>2</sup> + 4)</b>. The formula was used twice; a<sup>2</sup> + 4 does not factorise further.') },
      { q: L('Tenglamani yeching: x<sup>2</sup> − 81 = 0.', 'Решите уравнение: x<sup>2</sup> − 81 = 0.', 'Solve: x<sup>2</sup> − 81 = 0.'), s: L('(x − 9)(x + 9) = 0. Ko‘paytma nolga teng bo‘lsa, ko‘paytuvchilardan biri nol: <b>x = 9 yoki x = −9</b>.', '(x − 9)(x + 9) = 0. Произведение равно нулю, если один из множителей ноль: <b>x = 9 или x = −9</b>.', '(x − 9)(x + 9) = 0. A product is zero when one factor is zero: <b>x = 9 or x = −9</b>.') }
    ] },
    { kind: 'table', h: L('Tez hisob jadvali', 'Таблица быстрого счёта', 'Quick-maths table'), table: { head: [L('Ko‘paytma', 'Произведение', 'Product'), L('Formula', 'Формула', 'Formula'), L('Javob', 'Ответ', 'Answer')], rows: [
      ['19 · 21', '20<sup>2</sup> − 1<sup>2</sup>', '399'],
      ['38 · 42', '40<sup>2</sup> − 2<sup>2</sup>', '1 596'],
      ['95 · 105', '100<sup>2</sup> − 5<sup>2</sup>', '9 975'],
      ['63 · 57', '60<sup>2</sup> − 3<sup>2</sup>', '3 591'],
      ['7,2 · 6,8', '7<sup>2</sup> − 0,2<sup>2</sup>', '48,96']
    ] }, after: [
      L('Qoida: ikki son o‘rtasidagi «yumaloq» sonni toping, uning kvadratidan yarim farqning kvadratini ayiring.', 'Правило: найдите «круглое» число посередине и вычтите из его квадрата квадрат половины разности.', 'Rule: find the round number halfway between them, and subtract the square of half the difference from its square.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Kvadratlar yig‘indisini ajratishga urinish.</b> x<sup>2</sup> + 9 ≠ (x − 3)(x + 3). Formula faqat <i>ayirma</i> uchun!', '<b>Пытаться разложить сумму квадратов.</b> x<sup>2</sup> + 9 ≠ (x − 3)(x + 3). Формула только для <i>разности</i>!', '<b>Trying to factorise a sum of squares.</b> x<sup>2</sup> + 9 ≠ (x − 3)(x + 3). The formula is for a <i>difference</i> only!'),
      L('<b>(a − b)(a + b) ni (a − b)<sup>2</sup> bilan chalkashtirish.</b> (x − 4)(x + 4) = x<sup>2</sup> − 16, (x − 4)<sup>2</sup> esa x<sup>2</sup> − 8x + 16.', '<b>Путать (a − b)(a + b) с (a − b)<sup>2</sup>.</b> (x − 4)(x + 4) = x<sup>2</sup> − 16, а (x − 4)<sup>2</sup> = x<sup>2</sup> − 8x + 16.', '<b>Confusing (a − b)(a + b) with (a − b)<sup>2</sup>.</b> (x − 4)(x + 4) = x<sup>2</sup> − 16, but (x − 4)<sup>2</sup> = x<sup>2</sup> − 8x + 16.'),
      L('<b>Koeffitsiyentni kvadratga ko‘tarmaslik.</b> (3x − 1)(3x + 1) = 3x<sup>2</sup> − 1 — xato; 9x<sup>2</sup> − 1.', '<b>Не возвести коэффициент в квадрат.</b> (3x − 1)(3x + 1) = 3x<sup>2</sup> − 1 — ошибка; 9x<sup>2</sup> − 1.', '<b>Not squaring the coefficient.</b> (3x − 1)(3x + 1) = 3x<sup>2</sup> − 1 is wrong; it is 9x<sup>2</sup> − 1.'),
      L('<b>Oxirigacha ajratmaslik.</b> x<sup>4</sup> − 1 = (x<sup>2</sup> − 1)(x<sup>2</sup> + 1) — tugallanmagan; x<sup>2</sup> − 1 yana ajraladi.', '<b>Не разложить до конца.</b> x<sup>4</sup> − 1 = (x<sup>2</sup> − 1)(x<sup>2</sup> + 1) — не закончено; x<sup>2</sup> − 1 раскладывается дальше.', '<b>Stopping too early.</b> x<sup>4</sup> − 1 = (x<sup>2</sup> − 1)(x<sup>2</sup> + 1) is unfinished; x<sup>2</sup> − 1 factorises further.')
    ] },
    { kind: 'life', h: L('Formula hayotda', 'Формула в жизни', 'The formula in real life'), p: [
      L('<b>Hovuz atrofidagi yo‘lak.</b> Kvadrat hovuz tomoni 8 m, uning atrofida kvadrat shaklidagi maydon tomoni 12 m. Yo‘lakka qancha plitka kerak? 12<sup>2</sup> − 8<sup>2</sup> = (12 − 8)(12 + 8) = 4 · 20 = 80 m<sup>2</sup>. Usta bunday hisobni o‘lchov joyida, qog‘ozsiz bajaradi.', '<b>Дорожка вокруг бассейна.</b> Квадратный бассейн со стороной 8 м, вокруг — квадратная площадка со стороной 12 м. Сколько плитки нужно на дорожку? 12<sup>2</sup> − 8<sup>2</sup> = (12 − 8)(12 + 8) = 4 · 20 = 80 м<sup>2</sup>. Мастер делает такой расчёт прямо на месте, без бумаги.', '<b>A path round a pool.</b> A square pool has side 8 m, and the square area around it has side 12 m. How much tiling does the path need? 12<sup>2</sup> − 8<sup>2</sup> = (12 − 8)(12 + 8) = 4 · 20 = 80 m<sup>2</sup>. A builder does this on site without paper.'),
      L('<b>Quvurlar.</b> Quvur devorining kesim yuzi tashqi va ichki doiralar yuzlari ayirmasi: π(R<sup>2</sup> − r<sup>2</sup>) = π(R − r)(R + r). Muhandislar shu formula bilan metall sarfini hisoblaydi. <b>Sport.</b> Stadion yugurish yo‘lakchasining yuzi ham ikki doira yuzlari ayirmasi orqali topiladi.', '<b>Трубы.</b> Площадь сечения стенки трубы — разность площадей внешнего и внутреннего кругов: π(R<sup>2</sup> − r<sup>2</sup>) = π(R − r)(R + r). Инженеры так считают расход металла. <b>Спорт.</b> Площадь беговой дорожки стадиона тоже находят через разность площадей кругов.', '<b>Pipes.</b> The cross-section of a pipe wall is the difference of the outer and inner circles: π(R<sup>2</sup> − r<sup>2</sup>) = π(R − r)(R + r). Engineers use it to work out how much metal is needed. <b>Sport.</b> The area of a running track is also found as a difference of circle areas.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Istalgan toq sonni ikki ketma-ket son kvadratlari ayirmasi sifatida yozish mumkin: 2n + 1 = (n + 1)<sup>2</sup> − n<sup>2</sup>. Masalan, 15 = 8<sup>2</sup> − 7<sup>2</sup>.', 'Любое нечётное число — разность квадратов двух соседних чисел: 2n + 1 = (n + 1)<sup>2</sup> − n<sup>2</sup>. Например, 15 = 8<sup>2</sup> − 7<sup>2</sup>.', 'Any odd number is a difference of squares of two consecutive numbers: 2n + 1 = (n + 1)<sup>2</sup> − n<sup>2</sup>. For example, 15 = 8<sup>2</sup> − 7<sup>2</sup>.'),
      L('Fransuz matematigi Pyer Ferma (XVII asr) katta sonlarni ko‘paytuvchilarga ajratishning kvadratlar ayirmasiga asoslangan usulini o‘ylab topgan — u hozir ham «Ferma usuli» deb ataladi.', 'Французский математик Пьер Ферма (XVII век) придумал способ разложения больших чисел, основанный на разности квадратов — его до сих пор называют «методом Ферма».', 'The French mathematician Pierre de Fermat (17th century) invented a method of factorising large numbers based on the difference of squares — it is still called “Fermat’s method”.'),
      L('2 ga bo‘lganda 2 qoldiq beradigan sonlarni (ya’ni 4k + 2 ko‘rinishidagi sonlarni) hech qachon ikki butun son kvadratlari ayirmasi sifatida yozib bo‘lmaydi: 2, 6, 10, …', 'Числа вида 4k + 2 (2, 6, 10, …) никогда нельзя записать как разность квадратов двух целых чисел.', 'Numbers of the form 4k + 2 (2, 6, 10, …) can never be written as a difference of two whole-number squares.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. (a<sup>2</sup> − 3)(a<sup>2</sup> + 3) ni ko‘paytiring.', '1. Умножьте (a<sup>2</sup> − 3)(a<sup>2</sup> + 3).', '1. Multiply (a<sup>2</sup> − 3)(a<sup>2</sup> + 3).'),
      L('2. 100 − 9y<sup>2</sup> ni ajrating.', '2. Разложите 100 − 9y<sup>2</sup>.', '2. Factorise 100 − 9y<sup>2</sup>.'),
      L('3. Og‘zaki: 29 · 31 va 102 · 98.', '3. Устно: 29 · 31 и 102 · 98.', '3. Mentally: 29 · 31 and 102 · 98.'),
      L('4. 2x<sup>3</sup> − 50x ni to‘liq ajrating.', '4. Полностью разложите 2x<sup>3</sup> − 50x.', '4. Fully factorise 2x<sup>3</sup> − 50x.')
    ], after: [
      L('Javoblar: 1) a<sup>4</sup> − 9; 2) (10 − 3y)(10 + 3y); 3) 900 − 1 = 899 va 10 000 − 4 = 9 996; 4) 2x(x − 5)(x + 5).', 'Ответы: 1) a<sup>4</sup> − 9; 2) (10 − 3y)(10 + 3y); 3) 900 − 1 = 899 и 10 000 − 4 = 9 996; 4) 2x(x − 5)(x + 5).', 'Answers: 1) a<sup>4</sup> − 9; 2) (10 − 3y)(10 + 3y); 3) 900 − 1 = 899 and 10 000 − 4 = 9 996; 4) 2x(x − 5)(x + 5).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('(a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup> — o‘rta hadlar bir-birini yo‘q qiladi.', '(a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup> — средние члены взаимно уничтожаются.', '(a − b)(a + b) = a<sup>2</sup> − b<sup>2</sup> — the middle terms cancel.'),
      L('Teskari: a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b) — ajratish formulasi.', 'Наоборот: a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b) — формула разложения.', 'Backwards: a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b) — a factorising formula.'),
      L('Rasmda: kvadratdan kvadrat kesilsa, qolgani (a − b) × (a + b) to‘g‘ri to‘rtburchakka aylanadi.', 'На картинке: если из квадрата вырезать квадрат, остаток складывается в прямоугольник (a − b) × (a + b).', 'Picture: cut a square out of a square, and the rest rearranges into an (a − b) × (a + b) rectangle.'),
      L('Kvadratlar yig‘indisi a<sup>2</sup> + b<sup>2</sup> bu usulda ajralmaydi.', 'Сумма квадратов a<sup>2</sup> + b<sup>2</sup> так не раскладывается.', 'A sum of squares a<sup>2</sup> + b<sup>2</sup> does not factorise this way.'),
      L('Formula og‘zaki hisob, kasr qisqartirish va tenglama yechishda yordam beradi.', 'Формула помогает в устном счёте, сокращении дробей и решении уравнений.', 'The formula helps with mental maths, simplifying fractions and solving equations.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-2';

  // ---------- t9. Kublar ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Kvadratdan kubga', 'От квадрата к кубу', 'From square to cube'), p: [
      L('Oldingi mavzularda tekislikdagi kvadratni bo‘laklarga ajratdik. Endi uch o‘lchamga o‘tamiz. Qirrasi (a + b) bo‘lgan kubni tasavvur qiling — masalan, kichik kubiklardan yig‘ilgan Rubik kubigi. Uni har bir yo‘nalishda a va b qismlarga kessak, 8 ta bo‘lak hosil bo‘ladi. Ularning hajmlari yig‘indisi (a + b)<sup>3</sup> formulasini beradi.', 'В прошлых темах мы разрезали на части квадрат на плоскости. Теперь перейдём в три измерения. Представьте куб с ребром (a + b) — например, кубик Рубика из маленьких кубиков. Разрезав его по каждому направлению на части a и b, получим 8 кусков. Сумма их объёмов даёт формулу (a + b)<sup>3</sup>.', 'In earlier topics we cut a flat square into pieces. Now we move into three dimensions. Imagine a cube with edge (a + b) — like a Rubik’s cube made of small cubes. Cutting it into parts a and b in every direction gives 8 pieces. Adding their volumes gives the formula for (a + b)<sup>3</sup>.'),
      L('Bu mavzuda yig‘indi va ayirmaning kubi formulalarini hamda kublar yig‘indisi va ayirmasini ko‘paytuvchilarga ajratish formulalarini o‘rganamiz. Shu bilan qisqa ko‘paytirish formulalarining to‘liq to‘plami — yettita formula — tayyor bo‘ladi.', 'В этой теме мы изучим формулы куба суммы и разности, а также формулы разложения суммы и разности кубов. На этом полный набор формул сокращённого умножения — семь формул — будет готов.', 'In this topic we learn the formulas for the cube of a sum and difference, and for factorising a sum and a difference of cubes. That completes the full set of seven special product formulas.')
    ] },
    { kind: 'def', h: L('To‘rtta yangi formula', 'Четыре новые формулы', 'Four new formulas'), list: [
      L('<b>Yig‘indining kubi:</b> (a + b)<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>.', '<b>Куб суммы:</b> (a + b)<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>.', '<b>Cube of a sum:</b> (a + b)<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>.'),
      L('<b>Ayirmaning kubi:</b> (a − b)<sup>3</sup> = a<sup>3</sup> − 3a<sup>2</sup>b + 3ab<sup>2</sup> − b<sup>3</sup> (ishoralar navbatlashadi).', '<b>Куб разности:</b> (a − b)<sup>3</sup> = a<sup>3</sup> − 3a<sup>2</sup>b + 3ab<sup>2</sup> − b<sup>3</sup> (знаки чередуются).', '<b>Cube of a difference:</b> (a − b)<sup>3</sup> = a<sup>3</sup> − 3a<sup>2</sup>b + 3ab<sup>2</sup> − b<sup>3</sup> (signs alternate).'),
      L('<b>Kublar yig‘indisi:</b> a<sup>3</sup> + b<sup>3</sup> = (a + b)(a<sup>2</sup> − ab + b<sup>2</sup>).', '<b>Сумма кубов:</b> a<sup>3</sup> + b<sup>3</sup> = (a + b)(a<sup>2</sup> − ab + b<sup>2</sup>).', '<b>Sum of cubes:</b> a<sup>3</sup> + b<sup>3</sup> = (a + b)(a<sup>2</sup> − ab + b<sup>2</sup>).'),
      L('<b>Kublar ayirmasi:</b> a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>).', '<b>Разность кубов:</b> a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>).', '<b>Difference of cubes:</b> a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>).')
    ], after: [
      L('Ikkinchi qavsdagi a<sup>2</sup> ∓ ab + b<sup>2</sup> ifoda <b>to‘liqmas kvadrat</b> deyiladi: u to‘la kvadratga o‘xshaydi, lekin o‘rtadagi hadda 2 yo‘q. Ishoralarni yodlash uchun: birinchi qavsdagi ishora asl ishora bilan bir xil, ikkinchi qavsdagi ab oldidagi ishora — qarama-qarshi, oxirgi had doim «+».', 'Выражение a<sup>2</sup> ∓ ab + b<sup>2</sup> во второй скобке называют <b>неполным квадратом</b>: оно похоже на полный квадрат, но в среднем члене нет двойки. Чтобы запомнить знаки: в первой скобке знак тот же, что и в исходном выражении, перед ab во второй скобке — противоположный, последний член всегда «+».', 'The expression a<sup>2</sup> ∓ ab + b<sup>2</sup> in the second bracket is called an <b>incomplete square</b>: it looks like a perfect square but lacks the 2 in the middle term. To remember the signs: the first bracket keeps the original sign, the sign before ab in the second bracket is the opposite, and the last term is always “+”.')
    ] },
    { kind: 'rule', h: L('Nega shunday? Isbot va rasm', 'Почему так? Доказательство и картинка', 'Why? Proof and picture'), p: [
      L('(a + b)<sup>3</sup> = (a + b)<sup>2</sup>(a + b) = (a<sup>2</sup> + 2ab + b<sup>2</sup>)(a + b) = a<sup>3</sup> + a<sup>2</sup>b + 2a<sup>2</sup>b + 2ab<sup>2</sup> + ab<sup>2</sup> + b<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>.', '(a + b)<sup>3</sup> = (a + b)<sup>2</sup>(a + b) = (a<sup>2</sup> + 2ab + b<sup>2</sup>)(a + b) = a<sup>3</sup> + a<sup>2</sup>b + 2a<sup>2</sup>b + 2ab<sup>2</sup> + ab<sup>2</sup> + b<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>.', '(a + b)<sup>3</sup> = (a + b)<sup>2</sup>(a + b) = (a<sup>2</sup> + 2ab + b<sup>2</sup>)(a + b) = a<sup>3</sup> + a<sup>2</sup>b + 2a<sup>2</sup>b + 2ab<sup>2</sup> + ab<sup>2</sup> + b<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>.'),
      L('Kubik rasmda 8 bo‘lak: bitta katta kub a × a × a (a<sup>3</sup>), bitta kichik kub b × b × b (b<sup>3</sup>), uchta «yassi taxtacha» a × a × b (3a<sup>2</sup>b) va uchta «uzun brus» a × b × b (3ab<sup>2</sup>). 1 + 1 + 3 + 3 = 8 — hamma bo‘lak hisobga olindi.', 'На картинке с кубом 8 кусков: один большой куб a × a × a (a<sup>3</sup>), один маленький b × b × b (b<sup>3</sup>), три «плитки» a × a × b (3a<sup>2</sup>b) и три «бруска» a × b × b (3ab<sup>2</sup>). 1 + 1 + 3 + 3 = 8 — все куски учтены.', 'The cube picture has 8 pieces: one big cube a × a × a (a<sup>3</sup>), one small cube b × b × b (b<sup>3</sup>), three “slabs” a × a × b (3a<sup>2</sup>b) and three “rods” a × b × b (3ab<sup>2</sup>). 1 + 1 + 3 + 3 = 8 — every piece is counted.'),
      L('Kublar ayirmasini tekshirish uchun o‘ng tomonni ko‘paytiramiz: (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>) = a<sup>3</sup> + a<sup>2</sup>b + ab<sup>2</sup> − a<sup>2</sup>b − ab<sup>2</sup> − b<sup>3</sup> = a<sup>3</sup> − b<sup>3</sup>. To‘rtta had yo‘q bo‘lib ketdi!', 'Чтобы проверить разность кубов, перемножим правую часть: (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>) = a<sup>3</sup> + a<sup>2</sup>b + ab<sup>2</sup> − a<sup>2</sup>b − ab<sup>2</sup> − b<sup>3</sup> = a<sup>3</sup> − b<sup>3</sup>. Четыре члена исчезли!', 'To check the difference of cubes, multiply out the right side: (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>) = a<sup>3</sup> + a<sup>2</sup>b + ab<sup>2</sup> − a<sup>2</sup>b − ab<sup>2</sup> − b<sup>3</sup> = a<sup>3</sup> − b<sup>3</sup>. Four terms vanished!')
    ] },
    { kind: 'history', h: L('Paskal uchburchagi va Umar Xayyom', 'Треугольник Паскаля и Омар Хайям', 'Pascal’s triangle and Omar Khayyam'), p: [
      L('(a + b)<sup>2</sup> koeffitsiyentlari 1, 2, 1; (a + b)<sup>3</sup> niki 1, 3, 3, 1. Keyingi daraja uchun 1, 4, 6, 4, 1. Bu sonlarni uchburchak shaklida yozsak, har bir son ustidagi ikki sonning yig‘indisiga teng bo‘ladi. Yevropada bu jadval fransuz olimi <b>Blez Paskal</b> nomi bilan ataladi — u 1654-yilda uni batafsil o‘rgangan.', 'Коэффициенты (a + b)<sup>2</sup> — 1, 2, 1; (a + b)<sup>3</sup> — 1, 3, 3, 1. Для следующей степени — 1, 4, 6, 4, 1. Если записать эти числа треугольником, каждое равно сумме двух чисел над ним. В Европе эту таблицу называют именем французского учёного <b>Блеза Паскаля</b> — он подробно изучил её в 1654 году.', 'The coefficients of (a + b)<sup>2</sup> are 1, 2, 1; of (a + b)<sup>3</sup>, 1, 3, 3, 1; of the next power, 1, 4, 6, 4, 1. Written as a triangle, each number is the sum of the two above it. In Europe the table bears the name of the French scholar <b>Blaise Pascal</b>, who studied it in detail in 1654.'),
      L('Lekin bu uchburchak Paskaldan ancha oldin ma’lum edi. XI asrda <b>Umar Xayyom</b> istalgan natural darajadagi ikkihadni ochish usulini bilgan (uning bu haqdagi risolasi bizgacha yetib kelmagan, lekin keyingi olimlar unga havola qilgan). Eronda bu jadval hozir ham «Xayyom uchburchagi», Xitoyda esa XIII asr olimi nomi bilan «Yan Xuey uchburchagi» deyiladi.', 'Но этот треугольник был известен задолго до Паскаля. В XI веке <b>Омар Хайям</b> знал способ возводить двучлен в любую натуральную степень (его трактат об этом не сохранился, но на него ссылались более поздние учёные). В Иране таблицу до сих пор называют «треугольником Хайяма», а в Китае — «треугольником Ян Хуэя», по имени учёного XIII века.', 'But the triangle was known long before Pascal. In the 11th century <b>Omar Khayyam</b> knew how to raise a binomial to any natural power (his treatise on it is lost, but later scholars referred to it). In Iran the table is still called “Khayyam’s triangle”, and in China “Yang Hui’s triangle”, after a 13th-century scholar.')
    ] },
    { kind: 'steps', h: L('Kublar yig‘indisi/ayirmasini ajratish', 'Разложение суммы/разности кубов', 'Factorising sums and differences of cubes'), list: [
      L('1. Har bir hadni kub ko‘rinishida yozing: 8x<sup>3</sup> = (2x)<sup>3</sup>, 27 = 3<sup>3</sup>, 125 = 5<sup>3</sup>.', '1. Запишите каждый член как куб: 8x<sup>3</sup> = (2x)<sup>3</sup>, 27 = 3<sup>3</sup>, 125 = 5<sup>3</sup>.', '1. Write each term as a cube: 8x<sup>3</sup> = (2x)<sup>3</sup>, 27 = 3<sup>3</sup>, 125 = 5<sup>3</sup>.'),
      L('2. a va b ni aniqlang.', '2. Определите a и b.', '2. Identify a and b.'),
      L('3. Birinchi qavs: (a ± b) — asl ishora.', '3. Первая скобка: (a ± b) — исходный знак.', '3. First bracket: (a ± b) — the original sign.'),
      L('4. Ikkinchi qavs: a<sup>2</sup> ∓ ab + b<sup>2</sup> — ab oldida qarama-qarshi ishora.', '4. Вторая скобка: a<sup>2</sup> ∓ ab + b<sup>2</sup> — перед ab противоположный знак.', '4. Second bracket: a<sup>2</sup> ∓ ab + b<sup>2</sup> — the opposite sign before ab.'),
      L('5. Ikkinchi qavsni boshqa ajratishga urinmang — u butun sonlarda ajralmaydi.', '5. Вторую скобку дальше не раскладывайте — в целых числах она не раскладывается.', '5. Don’t try to factorise the second bracket — it does not factorise over whole numbers.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Oching: (x + 2)<sup>3</sup>.', 'Раскройте: (x + 2)<sup>3</sup>.', 'Expand: (x + 2)<sup>3</sup>.'), s: L('x<sup>3</sup> + 3 · x<sup>2</sup> · 2 + 3 · x · 4 + 8 = <b>x<sup>3</sup> + 6x<sup>2</sup> + 12x + 8</b>.', 'x<sup>3</sup> + 3 · x<sup>2</sup> · 2 + 3 · x · 4 + 8 = <b>x<sup>3</sup> + 6x<sup>2</sup> + 12x + 8</b>.', 'x<sup>3</sup> + 3 · x<sup>2</sup> · 2 + 3 · x · 4 + 8 = <b>x<sup>3</sup> + 6x<sup>2</sup> + 12x + 8</b>.') },
      { q: L('Oching: (2a − 1)<sup>3</sup>.', 'Раскройте: (2a − 1)<sup>3</sup>.', 'Expand: (2a − 1)<sup>3</sup>.'), s: L('(2a)<sup>3</sup> − 3 · 4a<sup>2</sup> · 1 + 3 · 2a · 1 − 1 = <b>8a<sup>3</sup> − 12a<sup>2</sup> + 6a − 1</b>.', '(2a)<sup>3</sup> − 3 · 4a<sup>2</sup> · 1 + 3 · 2a · 1 − 1 = <b>8a<sup>3</sup> − 12a<sup>2</sup> + 6a − 1</b>.', '(2a)<sup>3</sup> − 3 · 4a<sup>2</sup> · 1 + 3 · 2a · 1 − 1 = <b>8a<sup>3</sup> − 12a<sup>2</sup> + 6a − 1</b>.') },
      { q: L('Ajrating: x<sup>3</sup> − 8.', 'Разложите: x<sup>3</sup> − 8.', 'Factorise: x<sup>3</sup> − 8.'), s: L('8 = 2<sup>3</sup>, a = x, b = 2: <b>(x − 2)(x<sup>2</sup> + 2x + 4)</b>.', '8 = 2<sup>3</sup>, a = x, b = 2: <b>(x − 2)(x<sup>2</sup> + 2x + 4)</b>.', '8 = 2<sup>3</sup>, a = x, b = 2: <b>(x − 2)(x<sup>2</sup> + 2x + 4)</b>.') },
      { q: L('Ajrating: 27m<sup>3</sup> + 64.', 'Разложите: 27m<sup>3</sup> + 64.', 'Factorise: 27m<sup>3</sup> + 64.'), s: L('(3m)<sup>3</sup> + 4<sup>3</sup> = (3m + 4)(9m<sup>2</sup> − 12m + 16). Javob: <b>(3m + 4)(9m<sup>2</sup> − 12m + 16)</b>.', '(3m)<sup>3</sup> + 4<sup>3</sup> = (3m + 4)(9m<sup>2</sup> − 12m + 16). Ответ: <b>(3m + 4)(9m<sup>2</sup> − 12m + 16)</b>.', '(3m)<sup>3</sup> + 4<sup>3</sup> = (3m + 4)(9m<sup>2</sup> − 12m + 16). Answer: <b>(3m + 4)(9m<sup>2</sup> − 12m + 16)</b>.') },
      { q: L('Og‘zaki: 11<sup>3</sup>.', 'Устно: 11<sup>3</sup>.', 'Mentally: 11<sup>3</sup>.'), s: L('(10 + 1)<sup>3</sup> = 1000 + 300 + 30 + 1 = <b>1 331</b>. Raqamlar 1, 3, 3, 1 — Paskal uchburchagi satri!', '(10 + 1)<sup>3</sup> = 1000 + 300 + 30 + 1 = <b>1 331</b>. Цифры 1, 3, 3, 1 — строка треугольника Паскаля!', '(10 + 1)<sup>3</sup> = 1000 + 300 + 30 + 1 = <b>1 331</b>. The digits 1, 3, 3, 1 are a row of Pascal’s triangle!') }
    ] },
    { kind: 'table', h: L('Yettita formula — bitta jadvalda', 'Семь формул в одной таблице', 'All seven formulas in one table'), table: { head: [L('Nomi', 'Название', 'Name'), L('Formula', 'Формула', 'Formula')], rows: [
      [L('Yig‘indi kvadrati', 'Квадрат суммы', 'Square of a sum'), '(a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup>'],
      [L('Ayirma kvadrati', 'Квадрат разности', 'Square of a difference'), '(a − b)<sup>2</sup> = a<sup>2</sup> − 2ab + b<sup>2</sup>'],
      [L('Kvadratlar ayirmasi', 'Разность квадратов', 'Difference of squares'), 'a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)'],
      [L('Yig‘indi kubi', 'Куб суммы', 'Cube of a sum'), '(a + b)<sup>3</sup> = a<sup>3</sup> + 3a<sup>2</sup>b + 3ab<sup>2</sup> + b<sup>3</sup>'],
      [L('Ayirma kubi', 'Куб разности', 'Cube of a difference'), '(a − b)<sup>3</sup> = a<sup>3</sup> − 3a<sup>2</sup>b + 3ab<sup>2</sup> − b<sup>3</sup>'],
      [L('Kublar yig‘indisi', 'Сумма кубов', 'Sum of cubes'), 'a<sup>3</sup> + b<sup>3</sup> = (a + b)(a<sup>2</sup> − ab + b<sup>2</sup>)'],
      [L('Kublar ayirmasi', 'Разность кубов', 'Difference of cubes'), 'a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + ab + b<sup>2</sup>)']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>(a + b)<sup>3</sup> = a<sup>3</sup> + b<sup>3</sup></b> — xato! Rasmda 8 bo‘lak bor, bu esa faqat 2 tasini oladi.', '<b>(a + b)<sup>3</sup> = a<sup>3</sup> + b<sup>3</sup></b> — ошибка! На картинке 8 кусков, а здесь учтены только 2.', '<b>(a + b)<sup>3</sup> = a<sup>3</sup> + b<sup>3</sup></b> is wrong! The picture has 8 pieces; this counts only 2.'),
      L('<b>Koeffitsiyent 3 ni 2 bilan almashtirish.</b> (x + 1)<sup>3</sup> = x<sup>3</sup> + 2x<sup>2</sup> + 2x + 1 — xato; 3 bo‘lishi kerak.', '<b>Писать 2 вместо 3.</b> (x + 1)<sup>3</sup> = x<sup>3</sup> + 2x<sup>2</sup> + 2x + 1 — ошибка; должно быть 3.', '<b>Writing 2 instead of 3.</b> (x + 1)<sup>3</sup> = x<sup>3</sup> + 2x<sup>2</sup> + 2x + 1 is wrong; it should be 3.'),
      L('<b>To‘liqmas kvadratda 2ab yozish.</b> a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + 2ab + b<sup>2</sup>) — xato; ab bo‘lishi kerak.', '<b>Писать 2ab в неполном квадрате.</b> a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + 2ab + b<sup>2</sup>) — ошибка; нужно ab.', '<b>Writing 2ab in the incomplete square.</b> a<sup>3</sup> − b<sup>3</sup> = (a − b)(a<sup>2</sup> + 2ab + b<sup>2</sup>) is wrong; it is ab.'),
      L('<b>Ishoralarni chalkashtirish.</b> Kublar yig‘indisida ikkinchi qavsda «−ab», ayirmasida «+ab».', '<b>Путать знаки.</b> В сумме кубов во второй скобке «−ab», в разности — «+ab».', '<b>Mixing up signs.</b> For a sum of cubes the second bracket has “−ab”; for a difference, “+ab”.')
    ] },
    { kind: 'life', h: L('Kublar hayotda', 'Кубы в жизни', 'Cubes in real life'), p: [
      L('<b>Qadoqlash.</b> Qirrasi x sm bo‘lgan kub shaklidagi qutiga har tomondan 1 sm qalinlikdagi himoya qatlami qo‘yilsa, tashqi kub qirrasi (x + 2), hajmi (x + 2)<sup>3</sup> = x<sup>3</sup> + 6x<sup>2</sup> + 12x + 8. Qatlam materiali: 6x<sup>2</sup> + 12x + 8 sm<sup>3</sup>. Zavodlar shunday hisob bilan material sarfini rejalaydi.', '<b>Упаковка.</b> Если на кубическую коробку с ребром x см нанести защитный слой толщиной 1 см с каждой стороны, внешнее ребро станет (x + 2), объём (x + 2)<sup>3</sup> = x<sup>3</sup> + 6x<sup>2</sup> + 12x + 8. Материала на слой: 6x<sup>2</sup> + 12x + 8 см<sup>3</sup>. Заводы так планируют расход материалов.', '<b>Packaging.</b> If a cube-shaped box with edge x cm gets a 1 cm protective layer on every side, the outer edge becomes (x + 2) and the volume (x + 2)<sup>3</sup> = x<sup>3</sup> + 6x<sup>2</sup> + 12x + 8. The layer needs 6x<sup>2</sup> + 12x + 8 cm<sup>3</sup> of material. Factories plan material use exactly this way.'),
      L('<b>Rubik kubigi.</b> 3 × 3 × 3 kubikda 27 ta kichik kub bor: bitta markazda, 6 tasi yoqlar markazida, 12 tasi qirralarda va 8 tasi burchaklarda. 1 + 6 + 12 + 8 = 27 — bu (1 + 2)<sup>3</sup> formulasining koeffitsiyentlari bilan bog‘liq. <b>Akvarium.</b> Ichki o‘lchami a, devor qalinligi b bo‘lsa, shisha hajmi (a + 2b)<sup>3</sup> − a<sup>3</sup>.', '<b>Кубик Рубика.</b> В кубике 3 × 3 × 3 — 27 маленьких кубов: один в центре, 6 в центрах граней, 12 на рёбрах и 8 в углах. 1 + 6 + 12 + 8 = 27 — это связано с коэффициентами формулы (1 + 2)<sup>3</sup>. <b>Аквариум.</b> При внутреннем размере a и толщине стенки b объём стекла (a + 2b)<sup>3</sup> − a<sup>3</sup>.', '<b>Rubik’s cube.</b> A 3 × 3 × 3 cube has 27 small cubes: one in the centre, 6 at face centres, 12 on edges and 8 at corners. 1 + 6 + 12 + 8 = 27, which matches the coefficients of (1 + 2)<sup>3</sup>. <b>Aquarium.</b> With inner size a and wall thickness b, the glass volume is (a + 2b)<sup>3</sup> − a<sup>3</sup>.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('1729 — «taksi soni»: u ikki xil usulda ikki kub yig‘indisi: 1<sup>3</sup> + 12<sup>3</sup> = 9<sup>3</sup> + 10<sup>3</sup>. Hind matematigi Ramanujan buni kasalxonada yotganda bir zumda payqagan.', '1729 — «число такси»: его можно двумя способами записать как сумму двух кубов: 1<sup>3</sup> + 12<sup>3</sup> = 9<sup>3</sup> + 10<sup>3</sup>. Индийский математик Рамануджан мгновенно заметил это, лёжа в больнице.', '1729 is the “taxicab number”: it is a sum of two cubes in two ways: 1<sup>3</sup> + 12<sup>3</sup> = 9<sup>3</sup> + 10<sup>3</sup>. The Indian mathematician Ramanujan spotted this instantly while lying in hospital.'),
      L('Paskal uchburchagi satrlaridagi sonlar yig‘indisi 2 ning darajalari: 1, 2, 4, 8, 16, …', 'Суммы чисел в строках треугольника Паскаля — степени двойки: 1, 2, 4, 8, 16, …', 'The row sums of Pascal’s triangle are powers of two: 1, 2, 4, 8, 16, …'),
      L('1 dan n gacha kublar yig‘indisi shu sonlar yig‘indisining kvadratiga teng: 1<sup>3</sup> + 2<sup>3</sup> + 3<sup>3</sup> = 36 = (1 + 2 + 3)<sup>2</sup>.', 'Сумма кубов от 1 до n равна квадрату суммы этих чисел: 1<sup>3</sup> + 2<sup>3</sup> + 3<sup>3</sup> = 36 = (1 + 2 + 3)<sup>2</sup>.', 'The sum of cubes from 1 to n equals the square of the sum of those numbers: 1<sup>3</sup> + 2<sup>3</sup> + 3<sup>3</sup> = 36 = (1 + 2 + 3)<sup>2</sup>.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. (y − 3)<sup>3</sup> ni oching.', '1. Раскройте (y − 3)<sup>3</sup>.', '1. Expand (y − 3)<sup>3</sup>.'),
      L('2. a<sup>3</sup> + 1 ni ajrating.', '2. Разложите a<sup>3</sup> + 1.', '2. Factorise a<sup>3</sup> + 1.'),
      L('3. 125 − 8x<sup>3</sup> ni ajrating.', '3. Разложите 125 − 8x<sup>3</sup>.', '3. Factorise 125 − 8x<sup>3</sup>.'),
      L('4. Paskal uchburchagidan foydalanib, (a + b)<sup>4</sup> koeffitsiyentlarini yozing.', '4. С помощью треугольника Паскаля запишите коэффициенты (a + b)<sup>4</sup>.', '4. Use Pascal’s triangle to write the coefficients of (a + b)<sup>4</sup>.')
    ], after: [
      L('Javoblar: 1) y<sup>3</sup> − 9y<sup>2</sup> + 27y − 27; 2) (a + 1)(a<sup>2</sup> − a + 1); 3) (5 − 2x)(25 + 10x + 4x<sup>2</sup>); 4) 1, 4, 6, 4, 1.', 'Ответы: 1) y<sup>3</sup> − 9y<sup>2</sup> + 27y − 27; 2) (a + 1)(a<sup>2</sup> − a + 1); 3) (5 − 2x)(25 + 10x + 4x<sup>2</sup>); 4) 1, 4, 6, 4, 1.', 'Answers: 1) y<sup>3</sup> − 9y<sup>2</sup> + 27y − 27; 2) (a + 1)(a<sup>2</sup> − a + 1); 3) (5 − 2x)(25 + 10x + 4x<sup>2</sup>); 4) 1, 4, 6, 4, 1.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('(a ± b)<sup>3</sup> = a<sup>3</sup> ± 3a<sup>2</sup>b + 3ab<sup>2</sup> ± b<sup>3</sup>; koeffitsiyentlar 1, 3, 3, 1.', '(a ± b)<sup>3</sup> = a<sup>3</sup> ± 3a<sup>2</sup>b + 3ab<sup>2</sup> ± b<sup>3</sup>; коэффициенты 1, 3, 3, 1.', '(a ± b)<sup>3</sup> = a<sup>3</sup> ± 3a<sup>2</sup>b + 3ab<sup>2</sup> ± b<sup>3</sup>; coefficients 1, 3, 3, 1.'),
      L('Kubni 8 bo‘lakka kesish formulaning geometrik isboti.', 'Разрезание куба на 8 частей — геометрическое доказательство формулы.', 'Cutting a cube into 8 pieces is the geometric proof.'),
      L('a<sup>3</sup> ± b<sup>3</sup> = (a ± b)(a<sup>2</sup> ∓ ab + b<sup>2</sup>).', 'a<sup>3</sup> ± b<sup>3</sup> = (a ± b)(a<sup>2</sup> ∓ ab + b<sup>2</sup>).', 'a<sup>3</sup> ± b<sup>3</sup> = (a ± b)(a<sup>2</sup> ∓ ab + b<sup>2</sup>).'),
      L('To‘liqmas kvadratda 2 yo‘q va u boshqa ajralmaydi.', 'В неполном квадрате нет двойки, и дальше он не раскладывается.', 'The incomplete square has no 2 and does not factorise further.'),
      L('Koeffitsiyentlar Paskal (Xayyom) uchburchagidan olinadi.', 'Коэффициенты берутся из треугольника Паскаля (Хайяма).', 'The coefficients come from Pascal’s (Khayyam’s) triangle.')
    ] }
  ] });

  // ---------- t10. Algebraik kasrni qisqartirish ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Kasrlar harflar bilan', 'Дроби с буквами', 'Fractions with letters'), p: [
      L('5-6-sinflarda 12/18 = 2/3 kabi kasrlarni qisqartirgansiz: surat va maxrajni bir xil songa bo‘lgansiz. Endi surat va maxrajda harfli ifodalar turadi: (x<sup>2</sup> − 9)/(x + 3). Bunday kasrlar <b>algebraik kasrlar</b> deyiladi. Ular bilan ishlash qoidalari oddiy kasrlarnikiga juda o‘xshash, faqat bitta yangi narsa bor: maxraj nolga aylanib qolmasligini kuzatish kerak.', 'В 5–6 классах вы сокращали дроби вида 12/18 = 2/3: делили числитель и знаменатель на одно число. Теперь в числителе и знаменателе стоят буквенные выражения: (x<sup>2</sup> − 9)/(x + 3). Такие дроби называются <b>алгебраическими</b>. Правила работы с ними очень похожи на правила для обычных дробей, но есть одна новая вещь: нужно следить, чтобы знаменатель не обращался в ноль.', 'In grades 5–6 you simplified fractions like 12/18 = 2/3 by dividing the top and bottom by the same number. Now the top and bottom are letter expressions: (x<sup>2</sup> − 9)/(x + 3). These are called <b>algebraic fractions</b>. The rules are very similar to those for ordinary fractions, with one new thing: we must watch that the denominator never becomes zero.'),
      L('Bu mavzuda algebraik kasrning asosiy xossasini, uni qisqartirishni va bir nechta kasrni umumiy maxrajga keltirishni o‘rganamiz. Bu yerda oldingi boblarda o‘rgangan ko‘paytuvchilarga ajratish usullari asosiy vosita bo‘ladi.', 'В этой теме мы изучим основное свойство алгебраической дроби, её сокращение и приведение нескольких дробей к общему знаменателю. Главным инструментом здесь станут способы разложения на множители из прошлых глав.', 'In this topic we learn the basic property of an algebraic fraction, how to simplify it, and how to bring several fractions to a common denominator. The factorising methods from the earlier chapters are our main tool.')
    ] },
    { kind: 'def', h: L('Algebraik kasr va ruxsat etilgan qiymatlar', 'Алгебраическая дробь и допустимые значения', 'Algebraic fractions and permitted values'), p: [
      L('<b>Algebraik kasr</b> — surati va maxraji ko‘phad bo‘lgan kasr: <sup>P</sup>/<sub>Q</sub>. Masalan, <sup>3</sup>/<sub>x</sub>, <sup>a + b</sup>/<sub>a − b</sub>, <sup>x<sup>2</sup> − 1</sup>/<sub>2x + 4</sub>.', '<b>Алгебраическая дробь</b> — дробь, числитель и знаменатель которой многочлены: <sup>P</sup>/<sub>Q</sub>. Например, <sup>3</sup>/<sub>x</sub>, <sup>a + b</sup>/<sub>a − b</sub>, <sup>x<sup>2</sup> − 1</sup>/<sub>2x + 4</sub>.', 'An <b>algebraic fraction</b> is a fraction whose top and bottom are polynomials: <sup>P</sup>/<sub>Q</sub>. For example, <sup>3</sup>/<sub>x</sub>, <sup>a + b</sup>/<sub>a − b</sub>, <sup>x<sup>2</sup> − 1</sup>/<sub>2x + 4</sub>.'),
      L('Nolga bo‘lish mumkin emas, shuning uchun maxrajni nolga aylantiradigan qiymatlar <b>ruxsat etilmagan</b>. <sup>x<sup>2</sup> − 1</sup>/<sub>2x + 4</sub> uchun 2x + 4 = 0 → x = −2. Demak, x ≠ −2. Qolgan barcha qiymatlar — kasrning <b>aniqlanish sohasi</b>.', 'На ноль делить нельзя, поэтому значения, обращающие знаменатель в ноль, <b>недопустимы</b>. Для <sup>x<sup>2</sup> − 1</sup>/<sub>2x + 4</sub>: 2x + 4 = 0 → x = −2. Значит, x ≠ −2. Все остальные значения — <b>область определения</b> дроби.', 'Division by zero is impossible, so values that make the denominator zero are <b>not permitted</b>. For <sup>x<sup>2</sup> − 1</sup>/<sub>2x + 4</sub>: 2x + 4 = 0 → x = −2. So x ≠ −2. All other values form the fraction’s <b>domain</b>.'),
      L('<b>Asosiy xossa:</b> kasrning surat va maxrajini nolga teng bo‘lmagan bir xil ifodaga ko‘paytirsak yoki bo‘lsak, kasr qiymati o‘zgarmaydi: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub> (c ≠ 0).', '<b>Основное свойство:</b> если числитель и знаменатель умножить или разделить на одно и то же ненулевое выражение, значение дроби не изменится: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub> (c ≠ 0).', '<b>Basic property:</b> multiplying or dividing the top and bottom by the same non-zero expression does not change the fraction: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub> (c ≠ 0).')
    ] },
    { kind: 'history', h: L('Kasrlar tarixi', 'История дробей', 'A history of fractions'), p: [
      L('Qadimgi Misrliklar faqat surati 1 bo‘lgan kasrlarni ishlatishgan (2/3 dan tashqari): 3/4 ni 1/2 + 1/4 deb yozishgan. Bugungi gorizontal kasr chizig‘i esa arab matematiklari ishlarida paydo bo‘lgan. XII asrda marokashlik olim al-Hassor kasr chizig‘ini muntazam ishlatgan, Yevropaga esa uni 1202-yilda Leonardo Fibonachchi olib kelgan.', 'Древние египтяне пользовались только дробями с числителем 1 (кроме 2/3): 3/4 записывали как 1/2 + 1/4. А привычная горизонтальная дробная черта появилась в трудах арабских математиков. В XII веке марокканский учёный аль-Хассар регулярно использовал дробную черту, а в Европу её в 1202 году принёс Леонардо Фибоначчи.', 'The ancient Egyptians used only fractions with 1 on top (apart from 2/3): they wrote 3/4 as 1/2 + 1/4. The familiar horizontal fraction bar appeared in the works of Arab mathematicians. In the 12th century the Moroccan scholar al-Hassar used it regularly, and in 1202 Leonardo Fibonacci brought it to Europe.'),
      L('XV asrda Samarqandda <b>G‘iyosiddin Koshiy</b> o‘nli kasrlarni batafsil tushuntirib, ular bilan amallar qoidalarini bergan — Yevropada shunga o‘xshash ish faqat 150 yil keyin, Simon Stevin tomonidan e’lon qilingan. Ulug‘bek rasadxonasidagi astronomik jadvallar ana shunday aniq kasr hisoblariga asoslangan.', 'В XV веке в Самарканде <b>Гиясиддин Каши</b> подробно описал десятичные дроби и правила действий с ними — в Европе похожая работа появилась лишь через 150 лет у Симона Стевина. Астрономические таблицы обсерватории Улугбека основаны именно на таких точных вычислениях с дробями.', 'In the 15th century in Samarkand, <b>Jamshid al-Kashi</b> described decimal fractions and the rules for working with them in detail — in Europe similar work appeared only 150 years later, by Simon Stevin. The astronomical tables of Ulugh Beg’s observatory rest on such precise fraction calculations.')
    ] },
    { kind: 'rule', h: L('Qisqartirish va umumiy maxraj', 'Сокращение и общий знаменатель', 'Simplifying and common denominators'), p: [
      L('<b>Qisqartirish:</b> surat va maxrajni ko‘paytuvchilarga ajratamiz va umumiy ko‘paytuvchiga bo‘lamiz: <sup>x<sup>2</sup> − 9</sup>/<sub>x + 3</sub> = <sup>(x − 3)(x + 3)</sup>/<sub>x + 3</sub> = x − 3 (x ≠ −3). Qisqartirish faqat <i>ko‘paytuvchilarni</i> yo‘q qiladi, qo‘shiluvchilarni emas!', '<b>Сокращение:</b> раскладываем числитель и знаменатель на множители и делим на общий множитель: <sup>x<sup>2</sup> − 9</sup>/<sub>x + 3</sub> = <sup>(x − 3)(x + 3)</sup>/<sub>x + 3</sub> = x − 3 (x ≠ −3). Сокращаются только <i>множители</i>, а не слагаемые!', '<b>Simplifying:</b> factorise top and bottom and divide by the common factor: <sup>x<sup>2</sup> − 9</sup>/<sub>x + 3</sub> = <sup>(x − 3)(x + 3)</sup>/<sub>x + 3</sub> = x − 3 (x ≠ −3). Only <i>factors</i> cancel, never terms!'),
      L('<b>Umumiy maxrajga keltirish:</b> barcha maxrajlarni ajratamiz, umumiy maxraj sifatida har bir ko‘paytuvchining eng katta darajasini olamiz. So‘ng har bir kasrni «qo‘shimcha ko‘paytuvchi»ga ko‘paytiramiz. Masalan, <sup>1</sup>/<sub>2x</sub> va <sup>1</sup>/<sub>3x<sup>2</sup></sub>: umumiy maxraj 6x<sup>2</sup>, qo‘shimcha ko‘paytuvchilar 3x va 2.', '<b>Приведение к общему знаменателю:</b> раскладываем все знаменатели и берём каждый множитель в наибольшей степени. Затем умножаем каждую дробь на «дополнительный множитель». Например, <sup>1</sup>/<sub>2x</sub> и <sup>1</sup>/<sub>3x<sup>2</sup></sub>: общий знаменатель 6x<sup>2</sup>, дополнительные множители 3x и 2.', '<b>Common denominator:</b> factorise every denominator and take each factor to its highest power. Then multiply each fraction by its “extra factor”. For example, <sup>1</sup>/<sub>2x</sub> and <sup>1</sup>/<sub>3x<sup>2</sup></sub>: the common denominator is 6x<sup>2</sup>, and the extra factors are 3x and 2.'),
      L('Foydali ishora qoidasi: b − a = −(a − b), shuning uchun <sup>a − b</sup>/<sub>b − a</sub> = −1.', 'Полезное правило знаков: b − a = −(a − b), поэтому <sup>a − b</sup>/<sub>b − a</sub> = −1.', 'A useful sign rule: b − a = −(a − b), so <sup>a − b</sup>/<sub>b − a</sub> = −1.')
    ] },
    { kind: 'steps', h: L('Kasrni qisqartirish algoritmi', 'Алгоритм сокращения дроби', 'How to simplify a fraction'), list: [
      L('1. Maxrajni nolga aylantiruvchi qiymatlarni yozib qo‘ying.', '1. Запишите значения, обращающие знаменатель в ноль.', '1. Write down the values that make the denominator zero.'),
      L('2. Suratni ko‘paytuvchilarga ajrating (qavsdan chiqarish, formula, guruhlash).', '2. Разложите числитель на множители (вынесение, формулы, группировка).', '2. Factorise the top (common factor, formulas, grouping).'),
      L('3. Maxrajni ham ajrating.', '3. Разложите знаменатель.', '3. Factorise the bottom.'),
      L('4. Bir xil ko‘paytuvchilarni qisqartiring.', '4. Сократите одинаковые множители.', '4. Cancel matching factors.'),
      L('5. Javobni shartlar bilan birga yozing: x − 3 (x ≠ −3).', '5. Запишите ответ с условиями: x − 3 (x ≠ −3).', '5. Write the answer with the conditions: x − 3 (x ≠ −3).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Qisqartiring: <sup>6a<sup>2</sup>b</sup>/<sub>9ab<sup>3</sup></sub>.', 'Сократите: <sup>6a<sup>2</sup>b</sup>/<sub>9ab<sup>3</sup></sub>.', 'Simplify: <sup>6a<sup>2</sup>b</sup>/<sub>9ab<sup>3</sup></sub>.'), s: L('Umumiy ko‘paytuvchi 3ab: <b><sup>2a</sup>/<sub>3b<sup>2</sup></sub></b> (a ≠ 0, b ≠ 0).', 'Общий множитель 3ab: <b><sup>2a</sup>/<sub>3b<sup>2</sup></sub></b> (a ≠ 0, b ≠ 0).', 'Common factor 3ab: <b><sup>2a</sup>/<sub>3b<sup>2</sup></sub></b> (a ≠ 0, b ≠ 0).') },
      { q: L('Qisqartiring: <sup>5x − 15</sup>/<sub>x<sup>2</sup> − 9</sub>.', 'Сократите: <sup>5x − 15</sup>/<sub>x<sup>2</sup> − 9</sub>.', 'Simplify: <sup>5x − 15</sup>/<sub>x<sup>2</sup> − 9</sub>.'), s: L('<sup>5(x − 3)</sup>/<sub>(x − 3)(x + 3)</sub> = <b><sup>5</sup>/<sub>x + 3</sub></b> (x ≠ ±3).', '<sup>5(x − 3)</sup>/<sub>(x − 3)(x + 3)</sub> = <b><sup>5</sup>/<sub>x + 3</sub></b> (x ≠ ±3).', '<sup>5(x − 3)</sup>/<sub>(x − 3)(x + 3)</sub> = <b><sup>5</sup>/<sub>x + 3</sub></b> (x ≠ ±3).') },
      { q: L('Qisqartiring: <sup>a<sup>2</sup> − 4a + 4</sup>/<sub>2 − a</sub>.', 'Сократите: <sup>a<sup>2</sup> − 4a + 4</sup>/<sub>2 − a</sub>.', 'Simplify: <sup>a<sup>2</sup> − 4a + 4</sup>/<sub>2 − a</sub>.'), s: L('Surat (a − 2)<sup>2</sup>, maxraj −(a − 2). Natija: <b>−(a − 2) = 2 − a</b> (a ≠ 2).', 'Числитель (a − 2)<sup>2</sup>, знаменатель −(a − 2). Итог: <b>−(a − 2) = 2 − a</b> (a ≠ 2).', 'Top is (a − 2)<sup>2</sup>, bottom is −(a − 2). Result: <b>−(a − 2) = 2 − a</b> (a ≠ 2).') },
      { q: L('Umumiy maxrajga keltiring: <sup>3</sup>/<sub>x − 2</sub> va <sup>x</sup>/<sub>x<sup>2</sup> − 4</sub>.', 'Приведите к общему знаменателю: <sup>3</sup>/<sub>x − 2</sub> и <sup>x</sup>/<sub>x<sup>2</sup> − 4</sub>.', 'Bring to a common denominator: <sup>3</sup>/<sub>x − 2</sub> and <sup>x</sup>/<sub>x<sup>2</sup> − 4</sub>.'), s: L('x<sup>2</sup> − 4 = (x − 2)(x + 2) — bu umumiy maxraj. Birinchi kasrning qo‘shimcha ko‘paytuvchisi (x + 2): <b><sup>3x + 6</sup>/<sub>x<sup>2</sup> − 4</sub></b> va <b><sup>x</sup>/<sub>x<sup>2</sup> − 4</sub></b>.', 'x<sup>2</sup> − 4 = (x − 2)(x + 2) — это общий знаменатель. Дополнительный множитель первой дроби (x + 2): <b><sup>3x + 6</sup>/<sub>x<sup>2</sup> − 4</sub></b> и <b><sup>x</sup>/<sub>x<sup>2</sup> − 4</sub></b>.', 'x<sup>2</sup> − 4 = (x − 2)(x + 2) is the common denominator. The first fraction’s extra factor is (x + 2): <b><sup>3x + 6</sup>/<sub>x<sup>2</sup> − 4</sub></b> and <b><sup>x</sup>/<sub>x<sup>2</sup> − 4</sub></b>.') }
    ] },
    { kind: 'table', h: L('Qisqartirishda qaysi usul?', 'Какой способ при сокращении?', 'Which method for simplifying?'), p: [
      L('Kasrni qisqartirishning butun sirri — surat va maxrajni to‘g‘ri ajratishda. Quyidagi jadvalda har bir holat uchun qaysi usul ishlatilgani ko‘rsatilgan. Har safar avval umumiy ko‘paytuvchini, keyin formulalarni, so‘ng guruhlashni sinab ko‘ring.', 'Весь секрет сокращения — в правильном разложении числителя и знаменателя. В таблице показано, какой способ применён в каждом случае. Каждый раз пробуйте сначала общий множитель, затем формулы, потом группировку.', 'The whole secret of simplifying lies in factorising the top and bottom correctly. The table shows which method was used in each case. Always try a common factor first, then the formulas, then grouping.')
    ], table: { head: [L('Kasr', 'Дробь', 'Fraction'), L('Usul', 'Способ', 'Method'), L('Natija', 'Результат', 'Result')], rows: [
      ['<sup>4x + 8</sup>/<sub>4</sub>', L('umumiy ko‘paytuvchi', 'общий множитель', 'common factor'), 'x + 2'],
      ['<sup>x<sup>2</sup> − 25</sup>/<sub>x − 5</sub>', L('kvadratlar ayirmasi', 'разность квадратов', 'difference of squares'), 'x + 5'],
      ['<sup>x<sup>2</sup> + 6x + 9</sup>/<sub>x + 3</sub>', L('to‘la kvadrat', 'полный квадрат', 'perfect square'), 'x + 3'],
      ['<sup>ab + 2a</sup>/<sub>b<sup>2</sup> + 2b</sub>', L('ikkalasida ham qavsdan chiqarish', 'вынесение в обоих', 'factor out on both'), '<sup>a</sup>/<sub>b</sub>'],
      ['<sup>x<sup>3</sup> + 8</sup>/<sub>x + 2</sub>', L('kublar yig‘indisi', 'сумма кубов', 'sum of cubes'), 'x<sup>2</sup> − 2x + 4']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Qo‘shiluvchilarni qisqartirish.</b> <sup>x + 3</sup>/<sub>x</sub> = 3 — qo‘pol xato! x — qo‘shiluvchi, ko‘paytuvchi emas. Tekshiring: x = 1 da 4 ≠ 3.', '<b>Сокращать слагаемые.</b> <sup>x + 3</sup>/<sub>x</sub> = 3 — грубая ошибка! x — слагаемое, а не множитель. Проверьте: при x = 1 получается 4 ≠ 3.', '<b>Cancelling terms.</b> <sup>x + 3</sup>/<sub>x</sub> = 3 is a serious mistake! x is a term, not a factor. Check: at x = 1 you get 4 ≠ 3.'),
      L('<b>Shartlarni unutish.</b> <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> = x + 1, lekin x = 1 da chap tomon ma’noga ega emas. Javob: x + 1 (x ≠ 1).', '<b>Забыть условия.</b> <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> = x + 1, но при x = 1 левая часть не имеет смысла. Ответ: x + 1 (x ≠ 1).', '<b>Forgetting conditions.</b> <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> = x + 1, but at x = 1 the left side is meaningless. Answer: x + 1 (x ≠ 1).'),
      L('<b>Ishora xatosi.</b> <sup>a − b</sup>/<sub>b − a</sub> = 1 emas, −1.', '<b>Ошибка в знаке.</b> <sup>a − b</sup>/<sub>b − a</sub> = −1, а не 1.', '<b>Sign error.</b> <sup>a − b</sup>/<sub>b − a</sub> = −1, not 1.'),
      L('<b>Qisqartirgandan keyin 1 ni yo‘qotish.</b> <sup>x − 2</sup>/<sub>3(x − 2)</sub> = <sup>1</sup>/<sub>3</sub>, 0 yoki 3 emas.', '<b>Потерять 1 после сокращения.</b> <sup>x − 2</sup>/<sub>3(x − 2)</sub> = <sup>1</sup>/<sub>3</sub>, а не 0 и не 3.', '<b>Losing the 1 after cancelling.</b> <sup>x − 2</sup>/<sub>3(x − 2)</sub> = <sup>1</sup>/<sub>3</sub>, not 0 or 3.')
    ] },
    { kind: 'life', h: L('Algebraik kasrlar hayotda', 'Алгебраические дроби в жизни', 'Algebraic fractions in real life'), p: [
      L('<b>Narx bo‘lish.</b> Sinf ekskursiya uchun avtobus ijarasi 600 000 so‘m. Agar n o‘quvchi borsa, har biri <sup>600 000</sup>/<sub>n</sub> so‘m to‘laydi. n = 0 ma’nosiz — bu ruxsat etilmagan qiymatning hayotiy ma’nosi: hech kim bormasa, bo‘lishning o‘zi yo‘q.', '<b>Деление стоимости.</b> Аренда автобуса для экскурсии класса — 600 000 сум. Если поедут n учеников, каждый платит <sup>600 000</sup>/<sub>n</sub> сум. n = 0 не имеет смысла — это жизненный смысл недопустимого значения: если никто не едет, делить нечего.', '<b>Splitting a cost.</b> Hiring a bus for a class trip costs 600 000 sum. If n pupils go, each pays <sup>600 000</sup>/<sub>n</sub> sum. n = 0 makes no sense — that is the real-life meaning of a forbidden value: if nobody goes, there is nothing to share.'),
      L('<b>Tezlik va vaqt.</b> 120 km yo‘lni v km/soat tezlikda bosib o‘tish vaqti <sup>120</sup>/<sub>v</sub> soat. Agar tezlik 20 km/soatga oshsa, vaqt <sup>120</sup>/<sub>v + 20</sub>. Bunday kasrlar keyingi mavzuda qo‘shiladi va ayiriladi. <b>Fizika.</b> Zichlik ρ = <sup>m</sup>/<sub>V</sub>, bosim p = <sup>F</sup>/<sub>S</sub> — bular ham algebraik kasrlar.', '<b>Скорость и время.</b> Время на путь 120 км со скоростью v км/ч — <sup>120</sup>/<sub>v</sub> ч. Если скорость вырастет на 20 км/ч, время <sup>120</sup>/<sub>v + 20</sub>. Такие дроби мы будем складывать и вычитать в следующей теме. <b>Физика.</b> Плотность ρ = <sup>m</sup>/<sub>V</sub>, давление p = <sup>F</sup>/<sub>S</sub> — тоже алгебраические дроби.', '<b>Speed and time.</b> The time for 120 km at v km/h is <sup>120</sup>/<sub>v</sub> hours. If speed rises by 20 km/h, the time is <sup>120</sup>/<sub>v + 20</sub>. In the next topic we add and subtract such fractions. <b>Physics.</b> Density ρ = <sup>m</sup>/<sub>V</sub> and pressure p = <sup>F</sup>/<sub>S</sub> are algebraic fractions too.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«Kasr» so‘zi arabcha «kasr» — «sindirish» so‘zidan. Ruscha «дробь» ham «дробить» — maydalash fe’lidan kelib chiqqan.', 'Слово «дробь» происходит от «дробить» — разбивать, а узбекское «kasr» — от арабского «каср», «ломать».', 'The Uzbek word “kasr” comes from the Arabic for “breaking”, and the Latin “fractio” also means “a breaking”.'),
      L('<sup>16</sup>/<sub>64</sub> ni «6 larni o‘chirib» <sup>1</sup>/<sub>4</sub> qilish tasodifan to‘g‘ri chiqadi — lekin bu noto‘g‘ri usul! <sup>12</sup>/<sub>24</sub> da 2 larni o‘chirsangiz, 1/4 chiqadi, to‘g‘risi esa 1/2.', 'Если в <sup>16</sup>/<sub>64</sub> «зачеркнуть шестёрки», случайно выйдет верно <sup>1</sup>/<sub>4</sub> — но это неправильный способ! В <sup>12</sup>/<sub>24</sub> зачеркнув двойки, получим 1/4, а верно 1/2.', 'Crossing out the 6s in <sup>16</sup>/<sub>64</sub> happens to give the right <sup>1</sup>/<sub>4</sub> — but it is a wrong method! Crossing out the 2s in <sup>12</sup>/<sub>24</sub> gives 1/4, when the answer is 1/2.'),
      L('Kompyuter algebra tizimlari (masalan, Wolfram Alpha) kasrlarni qisqartirish uchun ko‘phadlarning EKUBini Yevklid algoritmi yordamida topadi.', 'Системы компьютерной алгебры (например, Wolfram Alpha) сокращают дроби, находя НОД многочленов алгоритмом Евклида.', 'Computer algebra systems (such as Wolfram Alpha) simplify fractions by finding the HCF of polynomials with Euclid’s algorithm.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('1. <sup>7</sup>/<sub>x − 5</sub> uchun ruxsat etilmagan qiymatni toping.', '1. Найдите недопустимое значение для <sup>7</sup>/<sub>x − 5</sub>.', '1. Find the forbidden value for <sup>7</sup>/<sub>x − 5</sub>.'),
      L('2. Qisqartiring: <sup>x<sup>2</sup> + 2x</sup>/<sub>x<sup>2</sup> − 4</sub>.', '2. Сократите: <sup>x<sup>2</sup> + 2x</sup>/<sub>x<sup>2</sup> − 4</sub>.', '2. Simplify: <sup>x<sup>2</sup> + 2x</sup>/<sub>x<sup>2</sup> − 4</sub>.'),
      L('3. Qisqartiring: <sup>a<sup>3</sup> − 1</sup>/<sub>a − 1</sub>.', '3. Сократите: <sup>a<sup>3</sup> − 1</sup>/<sub>a − 1</sub>.', '3. Simplify: <sup>a<sup>3</sup> − 1</sup>/<sub>a − 1</sub>.')
    ], after: [
      L('Javoblar: 1) x = 5; 2) <sup>x(x + 2)</sup>/<sub>(x − 2)(x + 2)</sub> = <sup>x</sup>/<sub>x − 2</sub> (x ≠ ±2); 3) a<sup>2</sup> + a + 1 (a ≠ 1).', 'Ответы: 1) x = 5; 2) <sup>x(x + 2)</sup>/<sub>(x − 2)(x + 2)</sub> = <sup>x</sup>/<sub>x − 2</sub> (x ≠ ±2); 3) a<sup>2</sup> + a + 1 (a ≠ 1).', 'Answers: 1) x = 5; 2) <sup>x(x + 2)</sup>/<sub>(x − 2)(x + 2)</sub> = <sup>x</sup>/<sub>x − 2</sub> (x ≠ ±2); 3) a<sup>2</sup> + a + 1 (a ≠ 1).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Algebraik kasr — surati va maxraji ko‘phad bo‘lgan kasr.', 'Алгебраическая дробь — дробь с многочленами в числителе и знаменателе.', 'An algebraic fraction has polynomials on top and bottom.'),
      L('Maxrajni nolga aylantiradigan qiymatlar ruxsat etilmaydi.', 'Значения, обращающие знаменатель в ноль, недопустимы.', 'Values that make the denominator zero are not allowed.'),
      L('Asosiy xossa: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub>, c ≠ 0.', 'Основное свойство: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub>, c ≠ 0.', 'Basic property: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub>, c ≠ 0.'),
      L('Qisqartirish: avval ajratish, keyin faqat ko‘paytuvchilarni qisqartirish.', 'Сокращение: сначала разложить, потом сокращать только множители.', 'Simplifying: factorise first, then cancel factors only.'),
      L('Umumiy maxraj: har bir ko‘paytuvchi eng katta darajada.', 'Общий знаменатель: каждый множитель в наибольшей степени.', 'Common denominator: every factor to its highest power.')
    ] }
  ] });
})(this);
